def tax_document_label(document_kind: str, income_year: int | None = None) -> str:
    normalized_kind = document_kind.strip().casefold()
    if normalized_kind == "avis":
        label = "Avis/ASDIR"
    elif normalized_kind == "2042":
        label = "2042"
    elif normalized_kind == "2074":
        label = "2074"
    else:
        label = document_kind.strip() or "Document"
    if income_year is None:
        return f"{label} document"
    return f"{label} income year {income_year}"


