def macos_safe_file_dialog_pattern(pattern: object) -> str | None:
    """Return a simple extension glob that macOS Tk can pass to NSSave/OpenPanel.

    Some Aqua/Tk builds abort the process inside setAllowedFileTypes when given
    wildcard-heavy patterns such as *foo*bar*.pdf or a bare "*" all-files rule.
    Reducing filters to extension globs keeps file dialogs stable on macOS.
    """
    cleaned = str(pattern or "").strip()
    if not cleaned or cleaned in {"*", "*.*"}:
        return None
    match = re.search(r"\.([A-Za-z0-9]+)$", cleaned)
    if not match:
        return None
    return f"*.{match.group(1).lower()}"


def macos_safe_file_dialog_filetypes(filetypes: object) -> list[tuple[str, str]]:
    if sys.platform != "darwin":
        return filetypes  # type: ignore[return-value]
    safe_filetypes: list[tuple[str, str]] = []
    seen_patterns: set[str] = set()
    try:
        entries = list(filetypes)  # type: ignore[arg-type]
    except TypeError:
        return []
    for entry in entries:
        if not isinstance(entry, (list, tuple)) or len(entry) < 2:
            continue
        label = str(entry[0])
        raw_patterns = entry[1]
        patterns = raw_patterns if isinstance(raw_patterns, (list, tuple)) else (raw_patterns,)
        for raw_pattern in patterns:
            safe_pattern = macos_safe_file_dialog_pattern(raw_pattern)
            if safe_pattern is None or safe_pattern in seen_patterns:
                continue
            safe_filetypes.append((label, safe_pattern))
            seen_patterns.add(safe_pattern)
    return safe_filetypes


