def fmt_money(value: Decimal, width: int = 12) -> str:
    return f"{excel_round(value, 0):>{width},.0f}".replace(",", " ")


def fmt_money_inline(value: Decimal) -> str:
    return f"{excel_round(value, 0):,.0f}".replace(",", " ")


def tax_rate_comparison_cli_lines(summary: dict[str, object]) -> list[str]:
    comparison = summary.get("tax_rate_comparison")
    if not isinstance(comparison, dict):
        return []

    lines: list[str] = []
    missing_documents = comparison.get("missing_comparison_documents")
    missing_documents_text = ""
    if isinstance(missing_documents, list) and missing_documents:
        missing_documents_text = f"missing {', '.join(str(item) for item in missing_documents)}"
    if (
        missing_documents_text
        and not isinstance(comparison.get("program_average_rate"), Decimal)
        and not comparison.get("avis_same_year")
    ):
        lines.append(
            "Taux moyen/marginal comparison       not compared "
            f"({missing_documents_text})"
        )
        return lines

    program_average_label = "Taux moyen d'imposition (program)"
    program_marginal_label = "Taux marginal d'imposition (program)"
    avis_average_label = "Taux moyen d'imposition (avis)"
    avis_marginal_label = "Taux marginal d'imposition (avis)"
    program_average_rate = comparison.get("program_average_rate")
    if isinstance(program_average_rate, Decimal):
        lines.append(
            f"{program_average_label:<38} "
            f"{format_rate_percent_two_decimals(program_average_rate)}"
        )
    else:
        lines.append(
            f"{program_average_label:<38} unavailable "
            f"({comparison.get('program_average_source', 'unknown source')})"
        )

    program_marginal_rate = comparison.get("program_marginal_rate")
    if isinstance(program_marginal_rate, Decimal):
        lines.append(
            f"{program_marginal_label:<38} "
            f"{format_rate_percent_two_decimals(program_marginal_rate)} "
            f"({comparison.get('program_marginal_source', 'program estimate')})"
        )

    if comparison.get("avis_error"):
        lines.append(f"{'Taux avis':<38} unavailable ({comparison['avis_error']})")
    elif comparison.get("avis_same_year"):
        avis_average_rate = comparison.get("avis_average_rate")
        if isinstance(avis_average_rate, Decimal):
            suffix = ""
            average_diff = comparison.get("average_rate_difference")
            if isinstance(average_diff, Decimal):
                suffix = f" (program - avis: {format_rate_point_difference(average_diff)})"
            lines.append(
                f"{avis_average_label:<38} "
                f"{format_rate_percent_two_decimals(avis_average_rate)}{suffix}"
            )
        avis_marginal_rate = comparison.get("avis_marginal_rate")
        if isinstance(avis_marginal_rate, Decimal):
            suffix = ""
            marginal_diff = comparison.get("marginal_rate_difference")
            if isinstance(marginal_diff, Decimal):
                suffix = f" (program - avis: {format_rate_point_difference(marginal_diff)})"
            lines.append(
                f"{avis_marginal_label:<38} "
                f"{format_rate_percent_two_decimals(avis_marginal_rate)}{suffix}"
            )
    elif comparison.get("avis_baseline_year") is not None:
        baseline_year = comparison["avis_baseline_year"]
        avis_average_rate = comparison.get("avis_average_rate")
        if isinstance(avis_average_rate, Decimal):
            label = f"Taux moyen d'imposition (avis {baseline_year})"
            lines.append(
                f"{label:<38} {format_rate_percent_two_decimals(avis_average_rate)}"
            )
        avis_marginal_rate = comparison.get("avis_marginal_rate")
        if isinstance(avis_marginal_rate, Decimal):
            label = f"Taux marginal d'imposition (avis {baseline_year})"
            lines.append(
                f"{label:<38} {format_rate_percent_two_decimals(avis_marginal_rate)}"
            )
    elif comparison.get("avis_year") is not None:
        lines.append(
            f"{'Taux avis':<38} not compared "
            f"(avis income year {comparison['avis_year']} differs from income year {summary['year']})"
        )
    elif missing_documents_text:
        lines.append(f"{'Taux avis':<38} not compared ({missing_documents_text})")
    return lines


def tax_rate_comparison_gui_lines(summary: dict[str, object]) -> list[str]:
    comparison = summary.get("tax_rate_comparison")
    if not isinstance(comparison, dict):
        return []

    rate_left_width = 40
    rate_value_width = 6

    def rate_number(rate: Decimal) -> str:
        return f"{excel_round(rate * Decimal('100'), 2):.2f}"

    def line(label: str, rate: Decimal | None, suffix: str = "") -> str:
        if rate is None:
            return f"    {label:<{rate_left_width}} {'n/a':>{rate_value_width}}{suffix}"
        return f"    {label:<{rate_left_width}} {rate_number(rate):>{rate_value_width}}{suffix}"

    missing_documents = comparison.get("missing_comparison_documents")
    missing_documents_text = ""
    if isinstance(missing_documents, list) and missing_documents:
        missing_documents_text = f"missing {', '.join(str(item) for item in missing_documents)}"
    if missing_documents_text and not isinstance(comparison.get("program_average_rate"), Decimal):
        return [
            f"    {'Taux moyen/marginal comparison':<{rate_left_width}} {'n/a':>{rate_value_width}} "
            + f"({missing_documents_text})"
        ]

    lines: list[str] = []
    program_average_rate = comparison.get("program_average_rate")
    program_average_source = str(comparison.get("program_average_source", "requires 2042 baseline"))
    lines.append(
        line(
            "Taux moyen d'imposition (program)",
            program_average_rate if isinstance(program_average_rate, Decimal) else None,
            "" if isinstance(program_average_rate, Decimal) else f" (= {program_average_source})",
        )
    )
    program_marginal_rate = comparison.get("program_marginal_rate")
    if isinstance(program_marginal_rate, Decimal):
        lines.append(line("Taux marginal d'imposition (program)", program_marginal_rate))

    if comparison.get("avis_same_year"):
        avis_average_rate = comparison.get("avis_average_rate")
        suffix = ""
        average_diff = comparison.get("average_rate_difference")
        if isinstance(average_diff, Decimal):
            suffix = f" (= program - avis: {format_rate_point_difference(average_diff)})"
        if isinstance(avis_average_rate, Decimal):
            lines.append(line("Taux moyen d'imposition (avis)", avis_average_rate, suffix))

        avis_marginal_rate = comparison.get("avis_marginal_rate")
        suffix = ""
        marginal_diff = comparison.get("marginal_rate_difference")
        if isinstance(marginal_diff, Decimal):
            suffix = f" (= program - avis: {format_rate_point_difference(marginal_diff)})"
        if isinstance(avis_marginal_rate, Decimal):
            lines.append(line("Taux marginal d'imposition (avis)", avis_marginal_rate, suffix))
    elif comparison.get("avis_error"):
        lines.append(f"    {'Taux avis':<{rate_left_width}} {'n/a':>{rate_value_width}} ({comparison['avis_error']})")
    elif comparison.get("avis_baseline_year") is not None:
        baseline_year = comparison["avis_baseline_year"]
        avis_average_rate = comparison.get("avis_average_rate")
        if isinstance(avis_average_rate, Decimal):
            lines.append(line(f"Taux moyen d'imposition (avis {baseline_year})", avis_average_rate))
        avis_marginal_rate = comparison.get("avis_marginal_rate")
        if isinstance(avis_marginal_rate, Decimal):
            lines.append(line(f"Taux marginal d'imposition (avis {baseline_year})", avis_marginal_rate))
    elif comparison.get("avis_year") is not None:
        lines.append(
            f"    {'Taux avis':<{rate_left_width}} {'n/a':>{rate_value_width}} "
            + f"(avis income year {comparison['avis_year']} differs)"
        )
    elif missing_documents_text:
        lines.append(f"    {'Taux avis':<{rate_left_width}} {'n/a':>{rate_value_width}} ({missing_documents_text})")
    return lines


def print_tax_estimate(summary: dict[str, object]) -> None:
    tax_estimate = summary.get("tax_estimate")
    if not isinstance(tax_estimate, dict):
        return

    boxes = summary["boxes"]
    pfu_rate = tax_estimate["pfu_rate"]
    tmi_rate = tax_estimate["tmi_rate"]
    tmi_label = str(tax_estimate.get("tmi_label", format_rate_percent(tmi_rate)))
    capital_base = tax_estimate["capital_gain_base_eur"]
    capital_tax = tax_estimate["capital_gain_tax_eur"]
    acquisition_base = tax_estimate["acquisition_gain_base_eur"]
    acquisition_tax = tax_estimate["acquisition_gain_tax_eur"]
    estimated_total = tax_estimate["estimated_total_eur"]

    print("\nEstimated taxes")
    print(f"{'PFU rate applied':<26} {format_rate_percent(pfu_rate)}")
    print(f"{'Tax rate applied':<26} {tmi_label}")
    for line in tax_rate_comparison_cli_lines(summary):
        print(line)
    for index, line in enumerate(progressive_tax_bracket_output_lines(tax_estimate)):
        label = "Tax bracket details" if index == 0 else ""
        print(f"{label:<26} {line}")
    print(
        f"{'Capital-gain base':<26} "
        f"max(0, 3VG - 3VH) = max(0, {fmt_money_inline(boxes['3VG'])} - "
        f"{fmt_money_inline(boxes['3VH'])}) = {fmt_money_inline(capital_base)}"
    )
    print(
        f"{'Capital-gain tax':<26} "
        f"{fmt_money_inline(capital_base)} x {format_rate_percent(pfu_rate)} = "
        f"{fmt_money_inline(capital_tax)}"
    )
    print(
        f"{'Acquisition-gain base':<26} "
        f"1TZ + 1TT = {fmt_money_inline(boxes['1TZ'])} + "
        f"{fmt_money_inline(boxes['1TT'])} = {fmt_money_inline(acquisition_base)}"
    )
    if is_progressive_tmi_selection(str(tax_estimate.get("tmi_selection", ""))):
        auto_details = tax_estimate.get("auto_tmi_details")
        bracket_source = (
            auto_details.get("bracket_source")
            if isinstance(auto_details, dict)
            else "progressive barème"
        )
        print(
            f"{'Acquisition-gain tax':<26} "
            f"incremental progressive barème estimate ({bracket_source}) = "
            f"{fmt_money_inline(acquisition_tax)}"
        )
    else:
        print(
            f"{'Acquisition-gain tax':<26} "
            f"{fmt_money_inline(acquisition_base)} x {format_rate_percent(tmi_rate)} = "
            f"{fmt_money_inline(acquisition_tax)}"
        )
    print(
        f"{'Estimated tax total':<26} "
        f"{fmt_money_inline(capital_tax)} + {fmt_money_inline(acquisition_tax)} = "
        f"{fmt_money_inline(estimated_total)}"
    )
    print(
        f"{'1WZ note':<26} "
        f"{fmt_money_inline(boxes['1WZ'])} is the 50% abatement box, not added again."
    )


def gui_high_income_tax_adjustments(report: str) -> tuple[list[tuple[str, Decimal, str]], list[tuple[str, Decimal, str]]]:
    additions: list[tuple[str, Decimal, str]] = []
    exclusions: list[tuple[str, Decimal, str]] = []
    cehr_match = re.search(r"CEHR: threshold exceeded; .*? is ([\d ]+) EUR\b", report)
    if cehr_match:
        additions.append(
            (
                "CEHR",
                parse_pdf_integer(cehr_match.group(1)),
                "(= selected RFR threshold calculation)",
            )
        )

    cdhr_match = re.search(r"CDHR: .*? is ([\d ]+) EUR\b", report)
    if cdhr_match:
        additions.append(
            (
                "CDHR",
                parse_pdf_integer(cdhr_match.group(1)),
                "(= minimum-tax calculation)",
            )
        )
    elif "CDHR: selected-RFR threshold gate exceeded" in report:
        exclusions.append(
            (
                "CDHR",
                Decimal("0"),
                "(not included: threshold gate exceeded, but amount is not computed)",
            )
        )
    return additions, exclusions


def gui_tax_estimate_text(summary: dict[str, object], high_income_report: str = "") -> str | None:
    tax_estimate = summary.get("tax_estimate")
    if not isinstance(tax_estimate, dict):
        return None

    rate_left_width = 40
    rate_value_width = 6
    tax_left_width = 32
    tax_value_width = 9

    def section_header(title: str, unit: str, left_width: int, value_width: int) -> str:
        return f"{title:<{4 + left_width + 1}}{unit:>{value_width}}"

    def rate_value(rate: Decimal) -> str:
        return f"{excel_round(rate * Decimal('100'), 2):.2f}"

    def tax_line(label: str, value: str, detail: str = "", bold: bool = False) -> str:
        value_cell = f"{value:>{tax_value_width}}"
        suffix = f" {detail}" if detail else ""
        return f"    {label:<{tax_left_width}} {value_cell}{suffix}"

    def rate_line(label: str, value: str, qualifier: str = "", detail: str = "") -> str:
        left = f"{label:<20} {qualifier}".rstrip()
        suffix = f" {detail}" if detail else ""
        return f"    {left:<{rate_left_width}} {value:>{rate_value_width}}{suffix}"

    boxes = summary["boxes"]
    pfu_rate = tax_estimate["pfu_rate"]
    tmi_rate = tax_estimate["tmi_rate"]
    tmi_selection = str(tax_estimate.get("tmi_selection", ""))
    progressive_tmi_selected = is_progressive_tmi_selection(tmi_selection)
    avis_tmi_selected = is_avis_tmi_selection(tmi_selection)
    capital_base = tax_estimate["capital_gain_base_eur"]
    capital_tax = tax_estimate["capital_gain_tax_eur"]
    acquisition_base = tax_estimate["acquisition_gain_base_eur"]
    acquisition_tax = tax_estimate["acquisition_gain_tax_eur"]
    estimated_total = tax_estimate["estimated_total_eur"]
    high_income_additions, high_income_exclusions = gui_high_income_tax_adjustments(high_income_report)
    estimated_total_with_high_income = estimated_total + sum((amount for _label, amount, _detail in high_income_additions), Decimal("0"))
    total_terms = [fmt_money_inline(capital_tax), fmt_money_inline(acquisition_tax)]
    total_terms.extend(fmt_money_inline(amount) for _label, amount, _detail in high_income_additions)
    total_label = "Estimated tax total" if not high_income_exclusions else "Estimated tax subtotal"
    total_detail = f"(= {' + '.join(total_terms)})"
    if high_income_exclusions:
        total_detail += "; excludes uncomputed CDHR"
    if progressive_tmi_selected:
        auto_details = tax_estimate.get("auto_tmi_details")
        bracket_source = (
            auto_details.get("bracket_source")
            if isinstance(auto_details, dict)
            else "progressive barème"
        )
        acquisition_tax_detail = f"(= incremental progressive barème estimate; {bracket_source})"
    else:
        rate_source = "Avis marginal rate" if avis_tmi_selected else format_rate_percent(tmi_rate)
        acquisition_tax_detail = f"(= {fmt_money_inline(acquisition_base)} x {rate_source})"

    lines = [
        section_header("Estimated rates", "%", rate_left_width, rate_value_width),
        "",
        rate_line("PFU rate applied", rate_value(pfu_rate)),
        rate_line(
            "Tax rate applied",
            rate_value(tmi_rate),
            tmi_selection if progressive_tmi_selected or avis_tmi_selected else "",
            "(from same-year Avis)" if avis_tmi_selected else "(effective)" if progressive_tmi_selected else "",
        ),
        *tax_rate_comparison_gui_lines(summary),
    ]
    for index, bracket_line in enumerate(progressive_tax_bracket_output_lines(tax_estimate)):
        label = "Tax bracket details" if index == 0 else ""
        lines.append(f"    {label:<{rate_left_width}} {bracket_line}")
    lines.extend(
        [
            "",
            section_header("Estimated taxes", "EUR", tax_left_width, tax_value_width),
            "",
            tax_line(
                "Capital-gain base",
                fmt_money_inline(capital_base),
                f"(= max(0, 3VG - 3VH); {fmt_money_inline(boxes['3VG'])} - {fmt_money_inline(boxes['3VH'])})",
            ),
            tax_line(
                "Capital-gain tax",
                fmt_money_inline(capital_tax),
                f"(= {fmt_money_inline(capital_base)} x {format_rate_percent(pfu_rate)})",
                bold=True,
            ),
            tax_line(
                "Acquisition-gain base",
                fmt_money_inline(acquisition_base),
                f"(= 1TZ + 1TT; {fmt_money_inline(boxes['1TZ'])} + {fmt_money_inline(boxes['1TT'])})",
            ),
            tax_line(
                "Acquisition-gain tax",
                fmt_money_inline(acquisition_tax),
                acquisition_tax_detail,
                bold=True,
            ),
        ]
    )
    for label, amount, detail in high_income_additions:
        lines.append(tax_line(label, fmt_money_inline(amount), detail, bold=True))
    for label, amount, detail in high_income_exclusions:
        lines.append(tax_line(label, fmt_money_inline(amount), detail))
    lines.append(tax_line(total_label, fmt_money_inline(estimated_total_with_high_income), total_detail, bold=True))
    return "\n".join(lines) + "\n\n"


def trim_gui_artifact_output(text: str) -> str:
    output_lines: list[str] = []
    for line in text.splitlines(keepends=True):
        if line.startswith("Wrote detail rows:") or line.startswith("Wrote summary JSON:"):
            continue
        if line.startswith("Wrote workbook:") and output_lines and output_lines[-1].strip():
            output_lines.append("\n")
        output_lines.append(line)
    return "".join(output_lines)


def replace_gui_tax_estimate_section(text: str, summary: dict[str, object], high_income_report: str = "") -> str:
    replacement_text = gui_tax_estimate_text(summary, high_income_report)
    if replacement_text is None:
        return text

    replacement_lines = replacement_text.splitlines(keepends=True)
    output_lines: list[str] = []
    lines = text.splitlines(keepends=True)
    index = 0
    skip_until_blank_after_estimated_taxes = False
    while index < len(lines):
        if lines[index].strip() == "Estimated taxes":
            output_lines.extend(replacement_lines)
            index += 1
            skip_until_blank_after_estimated_taxes = True
            while index < len(lines):
                if lines[index].startswith("1WZ note"):
                    index += 1
                    break
                index += 1
            continue
        if skip_until_blank_after_estimated_taxes and lines[index].strip() == "":
            skip_until_blank_after_estimated_taxes = False
            index += 1
            continue
        output_lines.append(lines[index])
        index += 1
    return "".join(output_lines)


