def program_directory() -> Path:
    return Path(__file__).resolve().parent


def git_command(args: list[str], timeout: int = 30, extra_env: Mapping[str, str] | None = None) -> str:
    command_env = None
    if extra_env:
        command_env = environ.copy()
        command_env.update(extra_env)
    completed = subprocess.run(
        ["git", "-C", str(program_directory()), *args],
        check=True,
        capture_output=True,
        text=True,
        timeout=timeout,
        env=command_env,
    )
    return completed.stdout.strip()


def git_return_code(args: list[str], timeout: int = 30, extra_env: Mapping[str, str] | None = None) -> int:
    command_env = None
    if extra_env:
        command_env = environ.copy()
        command_env.update(extra_env)
    completed = subprocess.run(
        ["git", "-C", str(program_directory()), *args],
        check=False,
        capture_output=True,
        text=True,
        timeout=timeout,
        env=command_env,
    )
    return completed.returncode


def tracked_local_changes() -> str:
    return git_command(["status", "--porcelain", "--untracked-files=no"], timeout=10)


class ProgramUpdateLocalChangesError(RuntimeError):
    pass


def git_remote_endpoint(remote_url: str) -> GitRemoteEndpoint | None:
    text = remote_url.strip()
    if not text or text.startswith("file:") or text.startswith("/") or re.match(r"^[A-Za-z]:[\\/]", text):
        return None
    if "://" not in text:
        scp_like_match = re.match(r"^(?:[^@/:]+@)?(?P<host>[^/:]+):(?P<path>.+)$", text)
        if scp_like_match:
            return GitRemoteEndpoint(scp_like_match.group("host"), 22, "ssh")
        return None

    try:
        parsed = urllib.parse.urlsplit(text)
    except ValueError:
        return None
    if not parsed.hostname:
        return None
    scheme = parsed.scheme.casefold()
    default_ports = {"ssh": 22, "http": 80, "https": 443, "git": 9418}
    try:
        port = parsed.port or default_ports.get(scheme)
    except ValueError:
        return None
    if port is None:
        return None
    return GitRemoteEndpoint(parsed.hostname, port, scheme)


def git_network_environment(remote_url: str) -> dict[str, str]:
    env = {"GIT_TERMINAL_PROMPT": "0"}
    endpoint = git_remote_endpoint(remote_url)
    if endpoint is not None and endpoint.scheme == "ssh":
        ssh_command = environ.get("GIT_SSH_COMMAND", "").strip() or "ssh"
        env["GIT_SSH_COMMAND"] = (
            f"{ssh_command} -o BatchMode=yes "
            f"-o ConnectTimeout={GIT_UPDATE_SSH_CONNECT_TIMEOUT_SECONDS} "
            "-o ConnectionAttempts=1"
        )
    return env


def fast_git_remote_unreachable_message(remote_url: str) -> str:
    endpoint = git_remote_endpoint(remote_url)
    if endpoint is None:
        return ""
    try:
        with socket.create_connection(
            (endpoint.host, endpoint.port),
            timeout=GIT_UPDATE_REACHABILITY_TIMEOUT_SECONDS,
        ):
            return ""
    except socket.gaierror:
        return f"GitHub update host not reachable ({endpoint.host}; DNS lookup failed)."
    except TimeoutError:
        return f"GitHub update host not reachable ({endpoint.host}:{endpoint.port}; connection timed out)."
    except OSError as exc:
        return f"GitHub update host not reachable ({endpoint.host}:{endpoint.port}; {exc})."


def git_revision_label(revision: str) -> str:
    if not revision:
        return "unknown"
    try:
        short_revision = git_command(["rev-parse", "--short=8", revision], timeout=10)
    except (FileNotFoundError, subprocess.TimeoutExpired, subprocess.CalledProcessError):
        short_revision = revision[:8]
    subject = git_revision_subject(revision)
    if not subject:
        return short_revision
    return f"{short_revision} {subject}"


def git_revision_subject(revision: str) -> str:
    if not revision:
        return ""
    try:
        return git_command(["log", "-1", "--format=%s", revision], timeout=10)
    except (FileNotFoundError, subprocess.TimeoutExpired, subprocess.CalledProcessError):
        return ""


def check_program_update() -> UpdateCheckResult:
    try:
        if git_command(["rev-parse", "--is-inside-work-tree"], timeout=10) != "true":
            return UpdateCheckResult(False, "", "", "Program is not running from a Git checkout.")
        local_revision = git_command(["rev-parse", "HEAD"], timeout=10)
        remote_url = git_command(["remote", "get-url", "origin"], timeout=3)
        unreachable_message = fast_git_remote_unreachable_message(remote_url)
        if unreachable_message:
            return UpdateCheckResult(False, local_revision, "", f"{unreachable_message} Update check skipped.")
        git_command(
            ["fetch", "--quiet", "origin", "main:refs/remotes/origin/main"],
            timeout=GIT_UPDATE_FETCH_CHECK_TIMEOUT_SECONDS,
            extra_env=git_network_environment(remote_url),
        )
        remote_revision = git_command(["rev-parse", "refs/remotes/origin/main"], timeout=10)
    except FileNotFoundError:
        return UpdateCheckResult(False, "", "", "Git is not installed; update check skipped.")
    except subprocess.TimeoutExpired:
        return UpdateCheckResult(False, "", "", "Git update check timed out.")
    except subprocess.CalledProcessError as exc:
        message = (exc.stderr or exc.stdout or str(exc)).strip()
        return UpdateCheckResult(False, "", "", f"Git update check failed: {message}")

    if not remote_revision:
        return UpdateCheckResult(False, local_revision, "", "Could not read origin/main.")
    if local_revision == remote_revision:
        return UpdateCheckResult(False, local_revision, remote_revision, "Already up to date.")
    try:
        ancestor_status = git_return_code(["merge-base", "--is-ancestor", local_revision, remote_revision], timeout=10)
    except FileNotFoundError:
        return UpdateCheckResult(False, local_revision, remote_revision, "Git is not installed; update check skipped.")
    except subprocess.TimeoutExpired:
        return UpdateCheckResult(False, local_revision, remote_revision, "Git update check timed out.")
    if ancestor_status != 0:
        return UpdateCheckResult(False, local_revision, remote_revision, "Local checkout is not behind origin/main.")
    remote_subject = git_revision_subject(remote_revision)
    remote_label = f"{remote_revision[:8]} {remote_subject}".strip() if remote_subject else git_revision_label(remote_revision)
    return UpdateCheckResult(
        True,
        local_revision,
        remote_revision,
        f"New version available: {local_revision[:8]} -> {remote_label}.",
        remote_subject,
    )


def update_program_from_git() -> str:
    try:
        if git_command(["rev-parse", "--is-inside-work-tree"], timeout=10) != "true":
            raise RuntimeError("Program is not running from a Git checkout.")
        local_changes = tracked_local_changes()
        if local_changes:
            changed_files = "\n".join(local_changes.splitlines()[:8])
            raise ProgramUpdateLocalChangesError(
                "Cannot auto-update because tracked program files have local changes:\n"
                f"{changed_files}"
            )
        before = git_command(["rev-parse", "HEAD"], timeout=10)
        remote_url = git_command(["remote", "get-url", "origin"], timeout=3)
        unreachable_message = fast_git_remote_unreachable_message(remote_url)
        if unreachable_message:
            raise RuntimeError(f"{unreachable_message} Auto-update skipped.")
        git_command(
            ["fetch", "--quiet", "origin", "main:refs/remotes/origin/main"],
            timeout=120,
            extra_env=git_network_environment(remote_url),
        )
        merge_output = git_command(["merge", "--ff-only", "refs/remotes/origin/main"], timeout=120)
        after = git_command(["rev-parse", "HEAD"], timeout=10)
    except FileNotFoundError as exc:
        raise RuntimeError("Git is not installed; auto-update cannot run.") from exc
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError("Git auto-update timed out.") from exc
    except subprocess.CalledProcessError as exc:
        message = (exc.stderr or exc.stdout or str(exc)).strip()
        raise RuntimeError(f"Git auto-update failed: {message}") from exc

    if before == after:
        return "Program was already up to date."
    return f"Updated program: {before[:8]} -> {git_revision_label(after)}.\n{merge_output}".strip()


def current_program_version() -> str:
    try:
        return git_command(["rev-parse", "HEAD"], timeout=10)
    except (FileNotFoundError, subprocess.TimeoutExpired, subprocess.CalledProcessError):
        return "unknown"


def run_gui(initial_args: argparse.Namespace) -> int:
    try:
        import tkinter as tk
        from tkinter import filedialog, messagebox, simpledialog, ttk
        from tkinter import font as tkfont
    except ImportError as exc:
        raise SystemExit("Tkinter is not available in this Python environment.") from exc

    def add_calendar_date_input(
        parent: tk.Misc,
        variable: tk.StringVar,
        *,
        width: int = 12,
    ) -> ttk.Frame:
        control = ttk.Frame(parent)
        entry = ttk.Entry(control, textvariable=variable, width=width, state="readonly")
        entry.pack(side="left", fill="x", expand=True)

        def open_calendar() -> None:
            try:
                selected = date.fromisoformat(variable.get())
            except ValueError:
                selected = date.today()
            display_month = {"year": selected.year, "month": selected.month}
            popup = tk.Toplevel(parent)
            popup.title("Select date")
            popup.transient(parent.winfo_toplevel())
            popup.resizable(False, False)
            popup_frame = ttk.Frame(popup, padding=8)
            popup_frame.grid(row=0, column=0, sticky="nsew")
            month_title = ttk.Label(popup_frame, anchor="center")
            month_title.grid(row=0, column=1, sticky="ew", padx=4, pady=(0, 6))
            calendar_grid = ttk.Frame(popup_frame)
            calendar_grid.grid(row=1, column=0, columnspan=3)
            day_names = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
            for column, day_name in enumerate(day_names):
                ttk.Label(calendar_grid, text=day_name, width=4, anchor="center").grid(
                    row=0,
                    column=column,
                    padx=1,
                    pady=1,
                )

            def choose_day(day_number: int) -> None:
                variable.set(
                    date(
                        display_month["year"],
                        display_month["month"],
                        day_number,
                    ).isoformat()
                )
                popup.destroy()

            def render_month() -> None:
                month_title.configure(
                    text=f"{calendar.month_name[display_month['month']]} {display_month['year']}"
                )
                for child in calendar_grid.grid_slaves():
                    if int(child.grid_info().get("row", 0)) > 0:
                        child.destroy()
                for week_index, week in enumerate(
                    calendar.monthcalendar(display_month["year"], display_month["month"]),
                    1,
                ):
                    for column, day_number in enumerate(week):
                        if day_number:
                            ttk.Button(
                                calendar_grid,
                                text=str(day_number),
                                width=3,
                                command=lambda day=day_number: choose_day(day),
                            ).grid(row=week_index, column=column, padx=1, pady=1)

            def shift_month(offset: int) -> None:
                month_index = display_month["year"] * 12 + display_month["month"] - 1 + offset
                display_month["year"], month_zero_based = divmod(month_index, 12)
                display_month["month"] = month_zero_based + 1
                render_month()

            ttk.Button(
                popup_frame,
                text="<",
                width=3,
                command=lambda: shift_month(-1),
            ).grid(row=0, column=0, sticky="w")
            ttk.Button(
                popup_frame,
                text=">",
                width=3,
                command=lambda: shift_month(1),
            ).grid(row=0, column=2, sticky="e")
            render_month()
            popup.bind("<Escape>", lambda _event: popup.destroy())
            popup.grab_set()
            popup.focus_set()

        ttk.Button(control, text="Calendar...", command=open_calendar).pack(side="left", padx=(4, 0))
        return control

    def ask_calendar_date(
        parent: tk.Misc,
        title: str,
        prompt: str,
        initial: date,
    ) -> date | None:
        dialog = tk.Toplevel(parent)
        dialog.title(title)
        dialog.transient(parent.winfo_toplevel())
        dialog.resizable(False, False)
        variable = tk.StringVar(value=initial.isoformat())
        ttk.Label(dialog, text=prompt).grid(row=0, column=0, columnspan=2, sticky="w", padx=12, pady=(12, 6))
        add_calendar_date_input(dialog, variable).grid(
            row=1,
            column=0,
            columnspan=2,
            sticky="ew",
            padx=12,
            pady=4,
        )
        result: dict[str, date | None] = {"value": None}

        def accept() -> None:
            try:
                result["value"] = date.fromisoformat(variable.get())
            except ValueError:
                messagebox.showerror(title, "Select a valid date from the calendar.", parent=dialog)
                return
            dialog.destroy()

        def cancel() -> None:
            dialog.destroy()

        buttons = ttk.Frame(dialog)
        buttons.grid(row=2, column=0, columnspan=2, sticky="e", padx=12, pady=(8, 12))
        ttk.Button(buttons, text="Cancel", command=cancel).pack(side="left", padx=(0, 6))
        ttk.Button(buttons, text="OK", command=accept).pack(side="left")
        dialog.bind("<Return>", lambda _event: accept())
        dialog.bind("<Escape>", lambda _event: cancel())
        dialog.protocol("WM_DELETE_WINDOW", cancel)
        dialog.grab_set()
        dialog.wait_window()
        return result["value"]

    loaded_preferences = load_gui_preferences()
    raw_owner_preferences = loaded_preferences.get(GUI_OWNERS_PREFERENCE_KEY, {})
    owner_preferences_by_name: dict[str, dict[str, object]] = {}
    if isinstance(raw_owner_preferences, dict):
        for raw_name, raw_preferences in raw_owner_preferences.items():
            owner_name = str(raw_name).strip()
            if not owner_name or owner_name == GUI_DEFAULT_OWNER_LABEL or not isinstance(raw_preferences, dict):
                continue
            owner_preferences_by_name[owner_name] = copy.deepcopy(raw_preferences)
    default_owner_preferences: dict[str, object] = {
        key: copy.deepcopy(value)
        for key, value in loaded_preferences.items()
        if key not in {GUI_OWNERS_PREFERENCE_KEY, GUI_ACTIVE_OWNER_PREFERENCE_KEY}
    }
    active_owner_name = str(loaded_preferences.get(GUI_ACTIVE_OWNER_PREFERENCE_KEY, "") or "").strip()
    if active_owner_name not in owner_preferences_by_name:
        active_owner_name = ""
    preferences = copy.deepcopy(
        owner_preferences_by_name[active_owner_name] if active_owner_name else default_owner_preferences
    )
    current_income_year = date.today().year
    future_planning_income_year = current_income_year + 2
    earliest_visible_income_year = current_income_year - 4
    requested_default_year = initial_args.year if initial_args.year is not None else current_income_year
    default_year = min(
        max(requested_default_year, earliest_visible_income_year),
        future_planning_income_year,
    )

    def preference_text(key: str, fallback: str = "") -> str:
        value = preferences.get(key, fallback)
        if value is None:
            value = fallback
        if key in GUI_SINGLE_PATH_PREFERENCE_KEYS:
            return display_path_text(value)
        if key in GUI_MULTI_PATH_PREFERENCE_KEYS:
            return join_transfer_form_paths(split_transfer_form_paths(str(value)))
        return str(value)

    def preference_bool(key: str, fallback: bool = False) -> bool:
        value = preferences.get(key, fallback)
        return bool(value)

    def preference_int(key: str, fallback: int = 0) -> int:
        try:
            return int(preferences.get(key, fallback))
        except (TypeError, ValueError):
            return fallback

    def current_owner_display_name() -> str:
        return active_owner_name or GUI_DEFAULT_OWNER_LABEL

    def fidelity_lot_exports_unavailable() -> bool:
        try:
            return bool(no_fidelity_lot_exports_var.get())
        except NameError:
            return preference_bool(GUI_NO_FIDELITY_LOT_EXPORTS_PREFERENCE_KEY, False)

    def closed_lots_required_for_current_owner() -> bool:
        return not active_owner_name and not fidelity_lot_exports_unavailable()

    def owner_window_title(base_title: str) -> str:
        return f"{base_title} - Owner: {current_owner_display_name()}"

    def set_window_title(window: object, base_title: str) -> None:
        window.title(owner_window_title(base_title))

    def update_root_title() -> None:
        root.title(f"ARM RSU French Tax Calculator - Owner: {current_owner_display_name()}")

    def owner_choice_values() -> list[str]:
        return [GUI_DEFAULT_OWNER_LABEL, *sorted(owner_preferences_by_name)]

    def initial_fidelity_receiving_institutions() -> dict[str, dict[str, str]]:
        profiles = load_shared_fidelity_receiving_institutions()
        raw_profiles = preferences.get("fidelity_receiving_institutions", {})
        if not isinstance(raw_profiles, dict):
            return profiles
        for raw_name, raw_data in raw_profiles.items():
            profile_name = str(raw_name).strip()
            if not profile_name:
                continue
            merged_data = dict(profiles.get(profile_name, {}))
            if isinstance(raw_data, dict):
                merged_data.update({str(key): value for key, value in raw_data.items()})
            details = fidelity_receiving_institution_from_mapping(profile_name, merged_data)
            try:
                validated = validate_fidelity_receiving_institution_details(details)
            except ValueError:
                continue
            profiles[validated.profile_name] = asdict(validated)
        return profiles

    def initial_pdf_paths_by_year() -> dict[str, dict[str, dict[str, str]]]:
        return normalize_pdf_paths_by_year(preferences.get("pdf_paths_by_year", {}))

    def initial_carry_forward_box_overrides_by_pdf() -> dict[str, dict[str, Decimal]]:
        normalized = normalize_carry_forward_box_overrides(
            preferences.get(CARRY_FORWARD_BOX_OVERRIDES_PREFERENCE_KEY, {})
        )
        return {
            path_key: {
                box: Decimal(value_text)
                for box, value_text in sorted(boxes.items())
            }
            for path_key, boxes in sorted(normalized.items())
        }

    def initial_advise_selected_lots_by_year() -> dict[str, dict[str, str]]:
        raw_years = preferences.get("advise_selected_lots_by_year", {})
        if not isinstance(raw_years, dict):
            return {}
        selected_by_year: dict[str, dict[str, str]] = {}
        for raw_year, raw_selection in raw_years.items():
            if not isinstance(raw_selection, dict):
                continue
            year = str(raw_year).strip()
            if not year:
                continue
            selection: dict[str, str] = {}
            for raw_lot_key, raw_owner in raw_selection.items():
                lot_key = str(raw_lot_key).strip()
                owner = str(raw_owner).strip()
                if lot_key and owner in {"Sale", "Transfer/Donation"}:
                    selection[lot_key] = owner
            if selection:
                selected_by_year[year] = selection
        return selected_by_year

    def initial_advise_in_transfer_lots_by_year() -> dict[str, set[str]]:
        raw_years = preferences.get("advise_in_transfer_lots_by_year", {})
        if not isinstance(raw_years, dict):
            return {}
        in_transfer_by_year: dict[str, set[str]] = {}
        for raw_year, raw_lot_keys in raw_years.items():
            year = str(raw_year).strip()
            if not year:
                continue
            if isinstance(raw_lot_keys, dict):
                raw_keys = raw_lot_keys.keys()
            elif isinstance(raw_lot_keys, list):
                raw_keys = raw_lot_keys
            else:
                continue
            lot_keys = {str(lot_key).strip() for lot_key in raw_keys if str(lot_key).strip()}
            if lot_keys:
                in_transfer_by_year[year] = lot_keys
        return in_transfer_by_year

    def initial_advise_transfer_in_confirmations_by_year() -> dict[str, dict[str, dict[str, str]]]:
        raw_years = preferences.get("advise_transfer_in_confirmations_by_year", {})
        if not isinstance(raw_years, dict):
            return {}
        confirmations_by_year: dict[str, dict[str, dict[str, str]]] = {}
        for raw_year, raw_confirmations in raw_years.items():
            year = str(raw_year).strip()
            if not year or not isinstance(raw_confirmations, dict):
                continue
            confirmations: dict[str, dict[str, str]] = {}
            for raw_lot_key, raw_confirmation in raw_confirmations.items():
                lot_key = str(raw_lot_key).strip()
                if not lot_key or not isinstance(raw_confirmation, dict):
                    continue
                broker = str(raw_confirmation.get("broker", "")).strip()
                transfer_date = str(raw_confirmation.get("date", "")).strip()
                try:
                    date.fromisoformat(transfer_date)
                except ValueError:
                    continue
                if not broker:
                    continue
                confirmation = {"broker": broker, "date": transfer_date}
                raw_market_value = str(raw_confirmation.get("market_value_usd", "")).strip()
                market_value = None
                if raw_market_value:
                    try:
                        market_value = Decimal(raw_market_value)
                    except decimal.InvalidOperation:
                        pass
                raw_market_value_as_of = str(raw_confirmation.get("market_value_as_of", "")).strip()
                market_value_as_of = ""
                if raw_market_value_as_of:
                    try:
                        date.fromisoformat(raw_market_value_as_of)
                    except ValueError:
                        pass
                    else:
                        market_value_as_of = raw_market_value_as_of
                if (
                    market_value is not None
                    and market_value.is_finite()
                    and market_value > 0
                    and market_value_as_of
                ):
                    confirmation["market_value_usd"] = str(market_value)
                    confirmation["market_value_as_of"] = market_value_as_of
                    confirmation["market_value_basis"] = "Yahoo historical close"
                else:
                    confirmation["market_value_basis"] = "Current Advise estimate"
                confirmations[lot_key] = confirmation
            if confirmations:
                confirmations_by_year[year] = confirmations
        return confirmations_by_year

    def initial_advise_lot_prices_by_year(preference_key: str) -> dict[str, dict[str, Decimal]]:
        raw_years = preferences.get(preference_key, {})
        if not isinstance(raw_years, dict):
                return {}
        pending_by_year: dict[str, dict[str, Decimal]] = {}
        for raw_year, raw_lots in raw_years.items():
            year = str(raw_year).strip()
            if not year or not isinstance(raw_lots, dict):
                continue
            lots: dict[str, Decimal] = {}
            for raw_lot_key, raw_details in raw_lots.items():
                lot_key = str(raw_lot_key).strip()
                if not lot_key:
                    continue
                if isinstance(raw_details, dict):
                    raw_price = raw_details.get("sale_price_usd", "")
                else:
                    raw_price = raw_details
                try:
                    sale_price = parse_decimal(str(raw_price))
                except Exception:
                    continue
                if sale_price > 0:
                    lots[lot_key] = sale_price
            if lots:
                pending_by_year[year] = lots
        return pending_by_year

    @dataclass(frozen=True)
    class AdvisePlacedSaleOrderDetails:
        sale_price_usd: Decimal
        order_date: date
        validity: str = "day"
        all_or_none: bool = False
        quantity: Decimal | None = None

    ADVISE_LAST_PLACED_SALE_ORDERS_PREFERENCE_KEY = "advise_last_placed_sale_orders_by_year"

    def normalize_placed_sale_order_validity(value: object) -> str:
        normalized = re.sub(r"[^a-z]+", "_", str(value or "").strip().casefold()).strip("_")
        if normalized in {"gtc", "good_till_cancel", "good_til_cancel", "good_until_cancel"}:
            return "good_till_cancel"
        return "day"

    def placed_sale_order_validity_label(value: object) -> str:
        return "Good till cancel" if normalize_placed_sale_order_validity(value) == "good_till_cancel" else "Day"

    def placed_sale_order_bool(value: object) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return bool(value)
        normalized = str(value or "").strip().casefold()
        return normalized in {"1", "true", "yes", "y", "on"}

    def parse_placed_sale_order_date(value: object) -> date:
        if isinstance(value, datetime):
            return value.date()
        if isinstance(value, date):
            return value
        text = str(value or "").strip()
        if not text:
            return date.today()
        for date_format in ("%Y-%m-%d", "%d/%m/%Y"):
            try:
                return datetime.strptime(text, date_format).date()
            except ValueError:
                continue
        return date.today()

    def placed_sale_order_is_expired(order: AdvisePlacedSaleOrderDetails) -> bool:
        return (
            normalize_placed_sale_order_validity(order.validity) == "day"
            and order.order_date < date.today()
        )

    def initial_advise_placed_sale_order_details_by_year(
        preference_key: str,
    ) -> dict[str, dict[str, AdvisePlacedSaleOrderDetails]]:
        raw_years = preferences.get(preference_key, {})
        if not isinstance(raw_years, dict):
            return {}
        orders_by_year: dict[str, dict[str, AdvisePlacedSaleOrderDetails]] = {}
        for raw_year, raw_lots in raw_years.items():
            year = str(raw_year).strip()
            if not year or not isinstance(raw_lots, dict):
                continue
            orders: dict[str, AdvisePlacedSaleOrderDetails] = {}
            for raw_lot_key, raw_details in raw_lots.items():
                lot_key = str(raw_lot_key).strip()
                if not lot_key:
                    continue
                if isinstance(raw_details, dict):
                    raw_price = raw_details.get("sale_price_usd", "")
                    raw_order_date = raw_details.get("order_date", "")
                    raw_quantity = raw_details.get("quantity")
                    if "order_date" in raw_details:
                        raw_validity = raw_details.get("validity", "day")
                        raw_all_or_none = raw_details.get("all_or_none", False)
                    else:
                        raw_validity = "good_till_cancel"
                        raw_all_or_none = True
                else:
                    raw_price = raw_details
                    raw_order_date = ""
                    raw_quantity = None
                    raw_validity = "good_till_cancel"
                    raw_all_or_none = True
                try:
                    sale_price = parse_decimal(str(raw_price))
                except Exception:
                    continue
                if sale_price <= 0:
                    continue
                quantity: Decimal | None = None
                if raw_quantity is not None and str(raw_quantity).strip():
                    try:
                        parsed_quantity = parse_decimal(str(raw_quantity))
                    except Exception:
                        parsed_quantity = Decimal("0")
                    if parsed_quantity > 0:
                        quantity = parsed_quantity
                orders[lot_key] = AdvisePlacedSaleOrderDetails(
                    sale_price_usd=sale_price,
                    order_date=parse_placed_sale_order_date(raw_order_date),
                    validity=normalize_placed_sale_order_validity(raw_validity),
                    all_or_none=placed_sale_order_bool(raw_all_or_none),
                    quantity=quantity,
                )
            if orders:
                orders_by_year[year] = orders
        return orders_by_year

    def initial_advise_placed_sale_orders_by_year() -> dict[str, dict[str, AdvisePlacedSaleOrderDetails]]:
        return initial_advise_placed_sale_order_details_by_year("advise_placed_sale_orders_by_year")

    def initial_advise_last_placed_sale_orders_by_year() -> dict[str, dict[str, AdvisePlacedSaleOrderDetails]]:
        return initial_advise_placed_sale_order_details_by_year(
            ADVISE_LAST_PLACED_SALE_ORDERS_PREFERENCE_KEY
        )

    def serialize_advise_placed_sale_orders_by_year(
        orders_by_year: dict[str, dict[str, AdvisePlacedSaleOrderDetails]]
    ) -> dict[str, dict[str, dict[str, object]]]:
        def serialize_order(order: AdvisePlacedSaleOrderDetails) -> dict[str, object]:
            serialized: dict[str, object] = {
                "sale_price_usd": str(order.sale_price_usd),
                "order_date": order.order_date.isoformat(),
                "validity": order.validity,
                "all_or_none": order.all_or_none,
            }
            if order.quantity is not None:
                serialized["quantity"] = str(order.quantity)
            return serialized

        return {
            year: {
                lot_key: serialize_order(order)
                for lot_key, order in sorted(lot_orders.items())
            }
            for year, lot_orders in sorted(orders_by_year.items())
            if lot_orders
        }

