    def default_transfer_form_paths() -> str:
        remembered = preference_text("transfer_forms", "")
        if remembered:
            return remembered
        search_dirs = [Path.cwd(), program_directory().parent, program_directory()]
        patterns = ("*IBKR*Transfer*Form*.pdf", "*Transfer*IBKR*.pdf", "*Transfer_Form*.pdf")
        matches: list[Path] = []
        seen: set[str] = set()
        for directory in search_dirs:
            if not directory.exists():
                continue
            for pattern in patterns:
                for path in sorted(directory.glob(pattern)):
                    if not path.is_file():
                        continue
                    if path.name.casefold().startswith("fidelity_transfer_of_assets_form"):
                        continue
                    key = path_compare_key(path)
                    if key not in seen:
                        seen.add(key)
                        matches.append(path)
        return join_transfer_form_paths(matches)

