    def macos_desktop_bounds() -> tuple[int, int, int, int] | None:
        if sys.platform != "darwin":
            return None
        try:
            output = subprocess.check_output(
                [
                    "osascript",
                    "-e",
                    'tell application "Finder" to get bounds of window of desktop',
                ],
                text=True,
                stderr=subprocess.DEVNULL,
                timeout=2,
            )
        except (FileNotFoundError, subprocess.SubprocessError, OSError):
            return None
        parts = [part.strip() for part in output.replace(",", " ").split()]
        if len(parts) < 4:
            return None
        try:
            left, top, right, bottom = (int(float(part)) for part in parts[:4])
        except ValueError:
            return None
        width = right - left
        height = bottom - top
        if width <= 0 or height <= 0:
            return None
        return left, top, width, height

    def windows_work_area_bounds() -> tuple[int, int, int, int] | None:
        if not sys.platform.startswith("win"):
            return None

        class RECT(ctypes.Structure):
            _fields_ = [
                ("left", ctypes.c_long),
                ("top", ctypes.c_long),
                ("right", ctypes.c_long),
                ("bottom", ctypes.c_long),
            ]

        rect = RECT()
        spi_get_work_area = 0x0030
        try:
            ok = ctypes.windll.user32.SystemParametersInfoW(
                spi_get_work_area,
                0,
                ctypes.byref(rect),
                0,
            )
        except (AttributeError, OSError):
            return None
        if not ok:
            return None
        width = rect.right - rect.left
        height = rect.bottom - rect.top
        if width <= 0 or height <= 0:
            return None
        return rect.left, rect.top, width, height

    def fit_window_to_available_height(window: tk.Toplevel | tk.Tk, min_width: int) -> None:
        if not (sys.platform.startswith("win") or sys.platform == "darwin"):
            return
        window.update_idletasks()
        bounds = windows_work_area_bounds() if sys.platform.startswith("win") else macos_desktop_bounds()
        if bounds is None:
            left = 0
            top = 0
            width = window.winfo_screenwidth()
            height = max(700, window.winfo_screenheight() - 80)
        else:
            left, top, width, height = bounds
        # Tk geometry sizes the client area; Windows decorations add height outside that
        # area, so leave room for the title bar/frame on top of the taskbar work area.
        bottom_margin = 84 if sys.platform.startswith("win") else 0
        height = max(700, height - bottom_margin)
        requested_width = max(min_width, window.winfo_reqwidth(), window.winfo_width())
        target_width = min(width, requested_width)
        x = left + max(0, (width - target_width) // 2)
        window.geometry(f"{target_width}x{height}+{x}+{top}")

