    @dataclass
    class BrokerInputTabState:
        name_var: tk.StringVar
        closed_lots_var: tk.StringVar
        transaction_history_var: tk.StringVar
        award_details_var: tk.StringVar
        transfer_form_vars: list[tk.StringVar]
        open_lots_var: tk.StringVar
        broker_statement_vars: list[tk.StringVar]
        manual_statement_rows: list[dict[str, str]]
        frame: ttk.Frame | None = None
        transfer_forms_frame: ttk.Frame | None = None
        broker_statements_frame: ttk.Frame | None = None
        manual_statement_rows_frame: ttk.Frame | None = None
        closed_lots_entry: ttk.Entry | None = None
        open_lots_entry: ttk.Entry | None = None
        broker_statement_focus_widget: tk.Widget | None = None

    def broker_tab_texts(raw_values: object) -> list[str]:
        if isinstance(raw_values, list):
            values = raw_values
        else:
            values = split_transfer_form_paths(str(raw_values or ""))
        texts: list[str] = []
        seen: set[str] = set()
        for raw_value in values:
            text = display_path_text(raw_value).strip()
            key = path_compare_key(text)
            if text and key and key not in seen:
                seen.add(key)
                texts.append(text)
        return texts

    def create_broker_input_tab_state(raw: dict[str, object] | None = None) -> BrokerInputTabState:
        data = raw if isinstance(raw, dict) else {}
        return BrokerInputTabState(
            name_var=tk.StringVar(value=str(data.get("name", "") or "").strip()),
            closed_lots_var=tk.StringVar(value=display_path_text(data.get("closed_lots", ""))),
            transaction_history_var=tk.StringVar(value=display_path_text(data.get("transaction_history", ""))),
            award_details_var=tk.StringVar(value=display_path_text(data.get("award_details", ""))),
            transfer_form_vars=[
                tk.StringVar(value=text)
                for text in broker_tab_texts(data.get("transfer_forms", []))
            ],
            open_lots_var=tk.StringVar(value=display_path_text(data.get("open_lots", ""))),
            broker_statement_vars=[
                tk.StringVar(value=text)
                for text in broker_tab_texts(data.get("broker_statements", []))
            ],
            manual_statement_rows=normalize_manual_broker_statement_rows(
                data.get("manual_statement_rows", [])
            ),
        )

    def broker_input_tab_preferences(state: BrokerInputTabState) -> dict[str, object]:
        return {
            "name": state.name_var.get().strip(),
            "closed_lots": state.closed_lots_var.get().strip(),
            "transaction_history": state.transaction_history_var.get().strip(),
            "award_details": state.award_details_var.get().strip(),
            "transfer_forms": [
                variable.get().strip()
                for variable in state.transfer_form_vars
                if variable.get().strip()
            ],
            "open_lots": state.open_lots_var.get().strip(),
            "broker_statements": [
                variable.get().strip()
                for variable in state.broker_statement_vars
                if variable.get().strip()
            ],
            "manual_statement_rows": normalize_manual_broker_statement_rows(state.manual_statement_rows),
        }

    def broker_input_tab_has_data(state: BrokerInputTabState) -> bool:
        values = broker_input_tab_preferences(state)
        return any(
            value
            for key, value in values.items()
            if key != "name"
        )

    def broker_input_tab_is_empty_placeholder(state: BrokerInputTabState) -> bool:
        return (
            re.fullmatch(r"Broker\s+\d+", state.name_var.get().strip(), flags=re.IGNORECASE) is not None
            and not broker_input_tab_has_data(state)
        )

    broker_input_tabs: list[BrokerInputTabState] = []

    def initial_broker_input_tabs() -> list[BrokerInputTabState]:
        raw_tabs = preferences.get("broker_tabs", [])
        result: list[BrokerInputTabState] = []
        if isinstance(raw_tabs, list):
            for raw_tab in raw_tabs:
                if isinstance(raw_tab, dict):
                    state = create_broker_input_tab_state(raw_tab)
                    if (
                        broker_input_tab_has_data(state)
                        or (state.name_var.get().strip() and not broker_input_tab_is_empty_placeholder(state))
                    ):
                        result.append(state)
        if result:
            return result
        legacy_broker_statement_paths = split_transfer_form_paths(
            preference_text("broker_statements", "") or preference_text("broker_statement", "")
        ) or list(initial_broker_statement_paths)
        if (
            preference_text("other_broker_closed_lots", "")
            or preference_text("other_broker_open_lots", "")
            or legacy_broker_statement_paths
        ):
            return [
                create_broker_input_tab_state(
                    {
                        "closed_lots": preference_text("other_broker_closed_lots", ""),
                        "open_lots": preference_text("other_broker_open_lots", ""),
                        "broker_statements": [
                            display_path_text(path)
                            for path in legacy_broker_statement_paths
                        ],
                    }
                )
            ]
        return []

    broker_input_tabs.extend(initial_broker_input_tabs())
    advice_tmi_rate_var.set(normalize_tmi_selection_text(advice_tmi_rate_var.get()))
    last_user_tmi_selection = (
        "30%" if is_avis_tmi_selection(advice_tmi_rate_var.get()) else advice_tmi_rate_var.get()
    )
    suppress_tmi_rate_control_update = False
    award_catalog_locked_var = tk.BooleanVar(value=True)

    def remembered_file_chooser_dir() -> str | None:
        raw_dir = preference_text("last_file_chooser_dir", "").strip()
        if not raw_dir:
            return None
        try:
            path = gui_path(raw_dir)
        except OSError:
            return None
        return display_path_text(path) if path.exists() and path.is_dir() else None

    def file_dialog_options(**options: object) -> dict[str, object]:
        initial_dir = remembered_file_chooser_dir()
        if initial_dir and not options.get("initialdir"):
            options["initialdir"] = initial_dir
        filetypes = options.get("filetypes")
        if filetypes is not None:
            safe_filetypes = macos_safe_file_dialog_filetypes(filetypes)
            if safe_filetypes:
                options["filetypes"] = safe_filetypes
            else:
                options.pop("filetypes", None)
        return options

    def remember_file_chooser_path(path_text: str, *, directory_selected: bool = False) -> None:
        if not path_text:
            return
        try:
            path = gui_path(path_text)
            directory = path if directory_selected else path.parent
        except OSError:
            return
        if not directory.exists() or not directory.is_dir():
            return
        preferences["last_file_chooser_dir"] = canonical_path_text(directory)
        try:
            persist_gui_preferences()
        except NameError:
            try:
                save_gui_preferences(preferences)
            except OSError:
                pass

    def choose_file(
        target: tk.StringVar,
        title: str,
        filetypes: list[tuple[str, str]],
        validator: Callable[[Path], bool] | None = None,
        invalid_message: str = "The selected file does not look like the expected input.",
    ) -> None:
        selected = filedialog.askopenfilename(**file_dialog_options(title=title, filetypes=filetypes))
        if selected:
            selected_path = gui_path(selected)
            if validator and not validator(selected_path):
                messagebox.showwarning("Wrong file", invalid_message)
                return
            remember_file_chooser_path(selected)
            target.set(display_path_text(selected_path))

    def choose_files(
        target: tk.StringVar,
        title: str,
        filetypes: list[tuple[str, str]],
        validator: Callable[[Path], bool] | None = None,
        invalid_message: str = "One selected file does not look like the expected input.",
        *,
        append: bool = False,
    ) -> None:
        selected = filedialog.askopenfilenames(**file_dialog_options(title=title, filetypes=filetypes))
        if not selected:
            return
        paths = [gui_path(path) for path in selected]
        if validator:
            invalid_paths = [path for path in paths if not validator(path)]
            if invalid_paths:
                messagebox.showwarning("Wrong file", invalid_message + f"\n\n{invalid_paths[0]}")
                return
        remember_file_chooser_path(str(paths[0]))
        if append:
            paths = [*split_transfer_form_paths(target.get()), *paths]
        target.set(join_transfer_form_paths(paths))

    def choose_output_prefix() -> None:
        selected = filedialog.askdirectory(**file_dialog_options(title="Select output folder"))
        if selected:
            remember_file_chooser_path(selected, directory_selected=True)
            try:
                year = int(year_var.get().strip())
            except ValueError:
                year = default_year
            out_prefix_var.set(display_path_text(gui_path(selected) / output_prefix_for_income_year(year)))

    def choose_cloud_backup_dir() -> None:
        selected = filedialog.askdirectory(**file_dialog_options(title="Select cloud backup folder"))
        if selected:
            remember_file_chooser_path(selected, directory_selected=True)
            cloud_backup_dir_var.set(display_path_text(selected))

    def google_drive_detection_status_text() -> str:
        roots = likely_google_drive_roots()
        if roots:
            return f"Google Drive sync folder detected: {display_path_text(roots[0])}"
        markers = likely_google_drive_install_markers()
        if markers:
            return "Google Drive appears installed, but no local sync folder was detected."
        return "Google Drive sync folder not detected."

    def update_output_prefix_for_year(income_year: int) -> None:
        out_prefix_var.set(output_prefix_for_gui_year(income_year, out_prefix_var.get()))

    def add_field_label(
        row: int,
        label: str,
        *,
        required: bool | None = None,
        sticky: str = "w",
        parent: tk.Misc | None = None,
    ) -> ttk.Frame:
        container = parent or main_frame
        frame = ttk.Frame(container)
        frame.grid(row=row, column=0, sticky=sticky, pady=3)
        if required is None:
            ttk.Label(frame, text=label).grid(row=0, column=0, sticky=sticky)
            return frame
        icon = MANDATORY_FIELD_ICON if required else OPTIONAL_FIELD_ICON
        icon_color = "#b00020" if required else "#666666"
        icon_label = ttk.Label(frame, text=icon, foreground=icon_color, width=2)
        icon_label.grid(row=0, column=0, sticky="w")
        text_label = ttk.Label(frame, text=label)
        text_label.grid(row=0, column=1, sticky=sticky)
        frame.required_icon_label = icon_label  # type: ignore[attr-defined]
        frame.field_text_label = text_label  # type: ignore[attr-defined]
        return frame

    def add_file_row(
        row: int,
        label: str,
        variable: tk.StringVar,
        title: str,
        filetypes: list[tuple[str, str]],
        required: bool = False,
        enabled: bool = True,
        validator: Callable[[Path], bool] | None = None,
        invalid_message: str = "The selected file does not look like the expected input.",
        parent: tk.Misc | None = None,
    ) -> tuple[ttk.Entry, ttk.Button]:
        container = parent or main_frame
        label_frame = add_field_label(row, label, required=required, parent=container)
        entry = ttk.Entry(container, textvariable=variable, state="normal" if enabled else "disabled")
        entry.required_label_frame = label_frame  # type: ignore[attr-defined]
        entry.grid(row=row, column=1, sticky="ew", padx=8, pady=3)
        button = ttk.Button(
            container,
            text="Browse...",
            command=lambda: choose_file(variable, title, filetypes, validator, invalid_message),
            state="normal" if enabled else "disabled",
        )
        button.grid(row=row, column=2, sticky="ew", pady=3)
        return entry, button

    def add_multi_file_row(
        row: int,
        label: str,
        variable: tk.StringVar,
        title: str,
        filetypes: list[tuple[str, str]],
        validator: Callable[[Path], bool] | None = None,
        invalid_message: str = "One selected file does not look like the expected input.",
        button_text: str = "Browse...",
        append: bool = False,
        required: bool = False,
        parent: tk.Misc | None = None,
    ) -> tuple[ttk.Entry, ttk.Button]:
        container = parent or main_frame
        add_field_label(row, label, required=required, parent=container)
        entry = ttk.Entry(container, textvariable=variable)
        entry.grid(row=row, column=1, sticky="ew", padx=8, pady=3)
        button = ttk.Button(
            container,
            text=button_text,
            command=lambda: choose_files(variable, title, filetypes, validator, invalid_message, append=append),
        )
        button.grid(row=row, column=2, sticky="ew", pady=3)
        return entry, button

    def load_scaled_photo_image(path: Path, *, max_height: int) -> tk.PhotoImage | None:
        if not path.exists():
            return None
        try:
            image = tk.PhotoImage(file=str(path))
        except tk.TclError:
            return None
        if image.height() > max_height:
            image = image.subsample(max(1, math.ceil(image.height() / max_height)))
        return image

    def show_help_screenshots(title: str, screenshots: tuple[Path, ...]) -> None:
        image_paths = [program_directory() / path for path in screenshots]
        missing = [path for path in image_paths if not path.exists()]
        if missing:
            missing_list = "\n".join(str(path) for path in missing)
            messagebox.showerror("PDF help", f"Screenshot not found:\n{missing_list}")
            return
        images: list[tk.PhotoImage] = []
        try:
            for image_path in image_paths:
                images.append(tk.PhotoImage(file=str(image_path)))
        except tk.TclError as exc:
            messagebox.showerror("PDF help", f"Could not open screenshot:\n{exc}")
            return
        current_index = 0

        popup = tk.Toplevel(root)
        set_window_title(popup, title)
        popup.transient(root)
        canvas_width = max(image.width() for image in images)
        canvas_height = max(image.height() for image in images)
        popup.geometry(f"{canvas_width}x{canvas_height + 48}")
        popup.minsize(min(canvas_width, 900), min(canvas_height + 48, 560))
        popup.columnconfigure(0, weight=1)
        popup.rowconfigure(0, weight=1)

        canvas = tk.Canvas(popup, width=canvas_width, height=canvas_height, highlightthickness=0)
        canvas.grid(row=0, column=0, sticky="nsew")
        image_item = canvas.create_image(0, 0, anchor="nw", image=images[current_index])
        popup._pdf_help_images = images

        button_row = ttk.Frame(popup, padding=(12, 8, 12, 12))
        button_row.grid(row=1, column=0, sticky="ew")
        button_row.columnconfigure(0, weight=1)
        page_label = ttk.Label(button_row)
        page_label.grid(row=0, column=0, sticky="w")
        previous_button = ttk.Button(button_row, text="<", width=3)
        previous_button.grid(row=0, column=1, sticky="e")
        next_button = ttk.Button(button_row, text=">", width=3)
        next_button.grid(row=0, column=2, sticky="e", padx=(4, 12))
        ttk.Button(button_row, text="Close", command=popup.destroy).grid(row=0, column=3, sticky="e")

        def update_image() -> None:
            image = images[current_index]
            canvas.itemconfigure(image_item, image=image)
            canvas.configure(scrollregion=(0, 0, image.width(), image.height()))
            canvas.coords(image_item, 0, 0)
            page_label.configure(
                text=f"{current_index + 1} / {len(images)} - {image_paths[current_index].name}"
            )
            previous_button.configure(state="normal" if current_index > 0 else "disabled")
            next_button.configure(state="normal" if current_index + 1 < len(images) else "disabled")

        def move_image(delta: int) -> None:
            nonlocal current_index
            next_index = current_index + delta
            if 0 <= next_index < len(images):
                current_index = next_index
                update_image()

        previous_button.configure(command=lambda: move_image(-1))
        next_button.configure(command=lambda: move_image(1))
        update_image()

    def tooltip_geometry_near_widget(
        widget: tk.Widget,
        window: tk.Toplevel,
        preferred_x: int,
        preferred_y: int,
    ) -> str:
        window.update_idletasks()
        width = window.winfo_reqwidth()
        height = window.winfo_reqheight()
        margin_x = 12
        margin_y = 8
        screen_width = widget.winfo_screenwidth()
        screen_height = widget.winfo_screenheight()
        x = preferred_x
        y = preferred_y
        if x + width > screen_width - margin_x:
            x = widget.winfo_rootx() - width - margin_x
        x = max(margin_x, min(x, screen_width - width - margin_x))
        if y + height > screen_height - margin_y:
            y = widget.winfo_rooty() - height - margin_y
        y = max(margin_y, min(y, screen_height - height - margin_y))
        return f"+{x}+{y}"

    class Tooltip:
        def __init__(self, widget: tk.Widget, text: object) -> None:
            self.widget = widget
            self.text_source = text
            self.window: tk.Toplevel | None = None
            self.after_id: str | None = None
            widget.bind("<Enter>", self.schedule, add="+")
            widget.bind("<Leave>", self.hide, add="+")
            widget.bind("<ButtonPress>", self.hide, add="+")

        def schedule(self, _event: tk.Event | None = None) -> None:
            self.cancel()
            self.after_id = self.widget.after(450, self.show)

        def cancel(self) -> None:
            if self.after_id is not None:
                self.widget.after_cancel(self.after_id)
                self.after_id = None

        def show(self) -> None:
            self.after_id = None
            if self.window is not None:
                return
            text = self.text()
            if not text:
                return
            x = self.widget.winfo_rootx() + 16
            y = self.widget.winfo_rooty() + self.widget.winfo_height() + 8
            window = tk.Toplevel(self.widget)
            window.wm_overrideredirect(True)
            label = ttk.Label(window, text=text, padding=(6, 3), relief="solid", borderwidth=1)
            label.grid(row=0, column=0)
            window.wm_geometry(tooltip_geometry_near_widget(self.widget, window, x, y))
            self.window = window

        def text(self) -> str:
            source = self.text_source
            if callable(source):
                return str(source()).strip()
            if hasattr(source, "get"):
                return str(source.get()).strip()
            return str(source).strip()

        def hide(self, _event: tk.Event | None = None) -> None:
            self.cancel()
            if self.window is not None:
                self.window.destroy()
                self.window = None

    def detail_text_display_and_tooltips(
        raw_text: str,
        document_tooltips: Mapping[str, str | Path] | None = None,
    ) -> tuple[str, dict[str, str]]:
        tooltip_map: dict[str, str] = {}
        display_text = raw_text
        for raw_label, raw_path in (document_tooltips or {}).items():
            label = str(raw_label).strip()
            path_text = str(raw_path).strip()
            if not label or not path_text:
                continue
            tooltip_map[label] = path_text
            path_tokens = {path_text, Path(path_text).name}
            for token in sorted((token for token in path_tokens if token and token != label), key=len, reverse=True):
                display_text = display_text.replace(token, label)
        return display_text, tooltip_map

    def tag_detail_document_tooltips(text_widget: tk.Text, tooltip_map: Mapping[str, str]) -> None:
        tooltip_window: tk.Toplevel | None = None

        def hide_tooltip(_event: tk.Event | None = None) -> None:
            nonlocal tooltip_window
            if tooltip_window is not None:
                tooltip_window.destroy()
                tooltip_window = None

        def show_tooltip(event: tk.Event, path_text: str) -> None:
            nonlocal tooltip_window
            hide_tooltip()
            tooltip_window = tk.Toplevel(text_widget)
            tooltip_window.wm_overrideredirect(True)
            ttk.Label(
                tooltip_window,
                text=path_text,
                padding=(6, 3),
                relief="solid",
                borderwidth=1,
            ).grid(row=0, column=0)
            tooltip_window.wm_geometry(
                tooltip_geometry_near_widget(
                    text_widget,
                    tooltip_window,
                    int(event.x_root) + 12,
                    int(event.y_root) + 10,
                )
            )

        for index, (label, path_text) in enumerate(tooltip_map.items()):
            tag = f"document_tooltip_{index}"
            start = "1.0"
            while True:
                start = text_widget.search(label, start, stopindex="end")
                if not start:
                    break
                end = f"{start}+{len(label)}c"
                text_widget.tag_add(tag, start, end)
                start = end
            text_widget.tag_configure(tag, underline=True)
            text_widget.tag_bind(tag, "<Enter>", lambda event, path=path_text: show_tooltip(event, path))
            text_widget.tag_bind(tag, "<Leave>", hide_tooltip)
            text_widget.tag_bind(tag, "<ButtonPress>", hide_tooltip)

    def make_logo_link(widget: tk.Widget, tooltip: str, url: str) -> None:
        Tooltip(widget, tooltip)
        widget.configure(cursor="hand2")

        def open_url(_event: tk.Event | None = None) -> str:
            if not webbrowser.open(url, new=2):
                messagebox.showwarning("Open browser", f"Could not open the configured browser for:\n{url}")
            return "break"

        widget.bind("<Button-1>", open_url, add="+")

