    def configure_broker_statement_icon(label: ttk.Label, path_text: str) -> None:
        label.configure(image="", text="")
        label.image = None
        if not path_text.strip():
            return
        path = gui_path(path_text)
        if not path.is_file():
            label.configure(text="?")
            return
        broker_name = broker_statement_broker_name(path)
        if not broker_name:
            label.configure(text="?")
            return
        broker_code = compact_institution_code(broker_name, fallback="BRKR")
        image = broker_statement_icon_images.get(broker_code)
        if image is not None:
            label.configure(image=image)
            label.image = image
        else:
            label.configure(text=broker_code)

    def add_broker_statement_path(path: Path | str, *, trigger_change: bool = False) -> None:
        variable = tk.StringVar(value=display_path_text(path))
        variable.trace_add("write", broker_statement_entry_changed)
        broker_statement_vars.append(variable)
        render_broker_statement_rows()
        if trigger_change:
            clear_output_on_change()

    def remove_broker_statement(index: int) -> None:
        if 0 <= index < len(broker_statement_vars):
            del broker_statement_vars[index]
            render_broker_statement_rows()
            clear_output_on_change()

    def render_broker_statement_rows() -> None:
        for child in broker_statements_frame.winfo_children():
            child.destroy()
        broker_statements_frame.columnconfigure(0, weight=1)
        if not broker_statement_vars:
            ttk.Label(broker_statements_frame, text="No broker statements selected").grid(
                row=0,
                column=0,
                sticky="w",
            )
            return
        for index, variable in enumerate(broker_statement_vars):
            entry = ttk.Entry(broker_statements_frame, textvariable=variable)
            entry.grid(row=index, column=0, sticky="ew", pady=(0 if index == 0 else 2, 2))
            icon_label = ttk.Label(broker_statements_frame)
            icon_label.grid(row=index, column=1, sticky="w", padx=(4, 0), pady=(0 if index == 0 else 2, 2))
            Tooltip(icon_label, "Detected broker for this statement CSV.")
            configure_broker_statement_icon(icon_label, variable.get().strip())
            ttk.Button(
                broker_statements_frame,
                text="Remove",
                command=lambda row_index=index: remove_broker_statement(row_index),
            ).grid(row=index, column=2, sticky="e", padx=(4, 0), pady=(0 if index == 0 else 2, 2))

