    def broker_state_broker_name(state: BrokerInputTabState, index: int | None = None) -> str:
        explicit = state.name_var.get().strip()
        generic_name = re.fullmatch(r"Broker\s+\d+", explicit, flags=re.IGNORECASE) is not None
        if explicit and not generic_name:
            return explicit
        for variable in state.broker_statement_vars:
            path_text = variable.get().strip()
            if not path_text:
                continue
            path = gui_path(path_text)
            if path.is_file():
                broker_name = broker_statement_broker_name(path)
                if broker_name:
                    return broker_name
        if state.manual_statement_rows:
            return "Societe Generale"
        if index is not None:
            return f"Broker {index}"
        return "Other broker"

    def broker_state_is_sg(state: BrokerInputTabState) -> bool:
        return compact_institution_code(broker_state_broker_name(state), fallback="") == "SG"

    def broker_tab_name_for_state(state: BrokerInputTabState, index: int) -> str:
        if not state.name_var.get().strip() and not broker_input_tab_has_data(state):
            return "New broker"
        explicit_name = broker_state_broker_name(state, index)
        if re.fullmatch(r"Broker\s+\d+", explicit_name, flags=re.IGNORECASE):
            return "Other broker" if broker_input_tab_has_data(state) else "New broker"
        if explicit_name != f"Broker {index}":
            return explicit_name
        code = ""
        for variable in state.broker_statement_vars:
            path_text = variable.get().strip()
            if not path_text:
                continue
            path = gui_path(path_text)
            if path.is_file():
                code = compact_institution_code(broker_statement_broker_name(path), fallback="")
                if code:
                    break
        return code or explicit_name

    def broker_tab_image_for_state(state: BrokerInputTabState) -> tk.PhotoImage | None:
        for variable in state.broker_statement_vars:
            path_text = variable.get().strip()
            if not path_text:
                continue
            path = gui_path(path_text)
            if path.is_file():
                code = compact_institution_code(broker_statement_broker_name(path), fallback="")
                image = broker_tab_icon_images.get(code)
                if image is not None:
                    return image
        code = compact_institution_code(state.name_var.get().strip(), fallback="")
        return broker_tab_icon_images.get(code)

    def update_broker_tab_titles() -> None:
        for index, state in enumerate(broker_input_tabs, 1):
            if state.frame is None:
                continue
            image = broker_tab_image_for_state(state)
            text = broker_tab_name_for_state(state, index)
            if image is not None:
                broker_notebook.tab(state.frame, text=f" {text}", image=image, compound="left")
            else:
                broker_notebook.tab(state.frame, text=text, image="")

