    def add_path_list_row(
        parent: tk.Misc,
        row: int,
        label: str,
        variables: list[tk.StringVar],
        title: str,
        filetypes: list[tuple[str, str]],
        validator: Callable[[Path], bool] | None,
        invalid_message: str,
        *,
        help_command: Callable[[], None] | None = None,
        disabled_help: bool = False,
        path_kind: str = "file",
    ) -> ttk.Frame:
        add_field_label(row, label, required=False, sticky="nw", parent=parent)
        list_frame = ttk.Frame(parent)
        list_frame.grid(row=row, column=1, sticky="ew", padx=8, pady=3)
        list_frame.columnconfigure(0, weight=1)

        def changed(*_args: object) -> None:
            if path_kind == "transfer":
                transfer_form_status_by_path.clear()
                for entry in list(transfer_form_entry_by_path.values()):
                    try:
                        entry.configure(style="TEntry")
                    except tk.TclError:
                        pass
            clear_output_on_change()
            update_broker_tab_titles()

        def render() -> None:
            for child in list_frame.winfo_children():
                child.destroy()
            list_frame.columnconfigure(0, weight=1)
            if not variables:
                ttk.Label(list_frame, text=f"No {label.lower()} selected").grid(row=0, column=0, sticky="w")
                return
            for index, variable in enumerate(variables):
                entry = ttk.Entry(list_frame, textvariable=variable)
                if path_kind == "transfer":
                    key = path_compare_key(variable.get().strip())
                    if key:
                        transfer_form_entry_by_path[key] = entry
                        entry.configure(
                            style=pdf_status_styles.get(transfer_form_status_by_path.get(key, "default"), "TEntry")
                        )
                    Tooltip(entry, lambda variable=variable: transfer_form_status_tooltip_text(variable.get().strip()))
                entry.grid(row=index, column=0, sticky="ew", pady=(0 if index == 0 else 2, 2))
                if path_kind == "statement":
                    icon_label = ttk.Label(list_frame)
                    icon_label.grid(row=index, column=1, sticky="w", padx=(4, 0), pady=(0 if index == 0 else 2, 2))
                    Tooltip(icon_label, "Detected broker for this statement CSV.")
                    configure_broker_statement_icon(icon_label, variable.get().strip())
                    remove_column = 2
                else:
                    remove_column = 1
                ttk.Button(
                    list_frame,
                    text="Remove",
                    command=lambda row_index=index: remove_path(row_index),
                ).grid(row=index, column=remove_column, sticky="e", padx=(4, 0), pady=(0 if index == 0 else 2, 2))

        def add_path(path: Path | str) -> None:
            variable = tk.StringVar(value=display_path_text(path))
            variable.trace_add("write", changed)
            variables.append(variable)
            render()

        def remove_path(index: int) -> None:
            if 0 <= index < len(variables):
                del variables[index]
                render()
                changed()

        def browse() -> None:
            selected = filedialog.askopenfilenames(**file_dialog_options(title=title, filetypes=filetypes))
            if not selected:
                return
            paths = [gui_path(path) for path in selected]
            if validator is not None:
                invalid_paths = [path for path in paths if not validator(path)]
                if invalid_paths:
                    messagebox.showwarning("Wrong file", invalid_message + f"\n\n{invalid_paths[0]}")
                    return
            remember_file_chooser_path(str(paths[0]))
            for path in paths:
                add_path(path)
            changed()

        ttk.Button(parent, text="Add...", command=browse).grid(row=row, column=2, sticky="new", pady=3)
        if help_command is not None:
            help_button = ttk.Button(parent, text=gui_help_button_text, width=3, command=help_command)
            Tooltip(help_button, f"Open {label} help.")
            help_button.grid(
                row=row, column=3, sticky="w", padx=(4, 0), pady=3
            )
        elif disabled_help:
            add_disabled_broker_help_button(parent, row, label)
        for variable in variables:
            variable.trace_add("write", changed)
        render()
        return list_frame

