    def build_other_broker_tab(state: BrokerInputTabState, index: int) -> ttk.Frame:
        frame = ttk.Frame(broker_notebook, padding=(8, 6))
        frame.columnconfigure(1, weight=1)
        state.frame = frame

        def broker_state_path_changed(*_args: object) -> None:
            clear_output_on_change()
            update_broker_tab_titles()
            update_manual_statement_row_visibility()

        def manual_statement_counterparty_values() -> list[str]:
            values = ["Fidelity", "Societe Generale", "Interactive Brokers"]
            for broker_index, broker_state in enumerate(broker_input_tabs, 1):
                name = broker_state_broker_name(broker_state, broker_index).strip()
                if name:
                    values.append(name)
            seen: set[str] = set()
            unique_values: list[str] = []
            for value in values:
                key = normalize_designation(value)
                if not key or key in seen:
                    continue
                seen.add(key)
                unique_values.append(value)
            return unique_values

        def manual_statement_transfer_form_defaults(
            transfer_form_path: Path,
        ) -> tuple[str, Decimal, str, int]:
            parsed_form = parse_fidelity_transfer_form(transfer_form_path)
            if not parsed_form.lots:
                raise ValueError("The Fidelity transfer form does not contain any parsed lot rows.")
            symbols = {
                normalize_manual_broker_statement_symbol(lot.symbol)
                for lot in parsed_form.lots
                if normalize_manual_broker_statement_symbol(lot.symbol)
            }
            if len(symbols) != 1:
                raise ValueError("The Fidelity transfer form must contain exactly one symbol for this manual row.")
            total_quantity = sum((lot.quantity for lot in parsed_form.lots), Decimal("0"))
            if total_quantity <= 0:
                raise ValueError("The Fidelity transfer form parsed quantity is zero.")
            return next(iter(symbols)), total_quantity, parsed_form.receiving_institution, len(parsed_form.lots)

        def attached_transfer_form_duplicate_message(
            transfer_form_path: Path,
            current_row_index: int | None = None,
        ) -> str:
            key = path_compare_key(transfer_form_path)
            if not key:
                return ""
            for broker_index, broker_state in enumerate(broker_input_tabs, 1):
                broker_name = broker_state_broker_name(broker_state, broker_index)
                for manual_index, raw_manual_row in enumerate(broker_state.manual_statement_rows):
                    if broker_state is state and manual_index == current_row_index:
                        continue
                    if path_compare_key(str(raw_manual_row.get("transfer_form", "") or "").strip()) == key:
                        return (
                            "This transfer form is already attached to "
                            f"{broker_name} manual statement row {manual_index + 1}."
                        )
            return ""

        def parse_manual_statement_row(raw_row: dict[str, str]) -> ManualBrokerStatementRow:
            transfer_form_text = raw_row.get("transfer_form", "").strip()
            transfer_form_path = gui_path(transfer_form_text) if transfer_form_text else None
            transfer_form_symbol = ""
            transfer_form_quantity: Decimal | None = None
            if transfer_form_path is not None:
                if not is_pdf_file(transfer_form_path):
                    raise ValueError("Select a Fidelity transfer form PDF for the attached transfer form.")
                transfer_form_symbol, transfer_form_quantity, _receiving, _lot_count = (
                    manual_statement_transfer_form_defaults(transfer_form_path)
                )

            statement_date = parse_lot_date(raw_row.get("statement_date", "").strip() or date.today().isoformat())
            quantity_text = raw_row.get("quantity", "").strip()
            quantity = parse_decimal(quantity_text) if quantity_text else (transfer_form_quantity or Decimal("0"))
            if quantity <= 0:
                raise ValueError("Quantity must be greater than zero.")
            owner = raw_row.get("owner", "").strip() or current_owner_display_name()
            if owner not in owner_choice_values():
                raise ValueError(f"Owner '{owner}' does not exist.")
            transfer_direction = normalize_manual_broker_statement_transfer_direction(
                raw_row.get("transfer_direction", "")
            )
            if transfer_form_path is not None and not transfer_direction:
                transfer_direction = "in"
            symbol = normalize_manual_broker_statement_symbol(raw_row.get("symbol", "")) or transfer_form_symbol
            if not symbol:
                raise ValueError("Symbol is required.")
            counterparty = raw_row.get("counterparty", "").strip()
            if transfer_direction == "in" and not counterparty:
                counterparty = "Fidelity"
            if transfer_direction and not counterparty:
                raise ValueError("Sending/receiving institution is required for transfer rows.")
            share_price_text = raw_row.get("share_price_usd", "").strip()
            share_price_usd = parse_decimal(share_price_text) if share_price_text else None
            if share_price_usd is not None and share_price_usd <= 0:
                raise ValueError("Share price must be greater than zero when provided.")
            share_price_currency = normalize_manual_broker_statement_share_price_currency(
                raw_row.get("share_price_currency", "")
            )
            if (
                share_price_usd is not None
                and not manual_broker_statement_is_outgoing_direction(transfer_direction)
                and share_price_currency != "USD"
            ):
                raise ValueError("EUR share prices are supported only for outgoing manual rows.")
            return ManualBrokerStatementRow(
                broker=broker_state_broker_name(state, index),
                owner=owner,
                symbol=symbol,
                quantity=quantity,
                statement_date=statement_date,
                transfer_direction=transfer_direction,
                counterparty=counterparty,
                share_price_usd=share_price_usd,
                share_price_currency=share_price_currency,
                transfer_form_path=transfer_form_path,
                source_lot_quantities=manual_broker_statement_source_lot_quantities(
                    raw_row.get("source_lot_quantities", "")
                ),
            )

        def manual_statement_row_preferences(row: ManualBrokerStatementRow) -> dict[str, str]:
            return {
                "symbol": row.symbol,
                "quantity": format(row.quantity.normalize(), "f"),
                "statement_date": row.statement_date.isoformat(),
                "transfer_direction": row.transfer_direction,
                "counterparty": row.counterparty,
                "owner": row.owner,
                "share_price_usd": "" if row.share_price_usd is None else format(row.share_price_usd.normalize(), "f"),
                "share_price_currency": normalize_manual_broker_statement_share_price_currency(
                    row.share_price_currency
                ),
                "transfer_form": canonical_path_text(row.transfer_form_path),
                "source_lot_quantities": json.dumps(
                    [
                        {"lot_key": lot_key, "quantity": format(quantity.normalize(), "f")}
                        for lot_key, quantity in row.source_lot_quantities
                    ],
                    separators=(",", ":"),
                ),
            }

        def show_manual_statement_row_dialog(row_index: int | None = None) -> None:
            raw_row = (
                dict(state.manual_statement_rows[row_index])
                if row_index is not None and 0 <= row_index < len(state.manual_statement_rows)
                else {}
            )
            dialog = tk.Toplevel(root)
            set_window_title(dialog, "SG Manual Statement Row")
            dialog.transient(root)
            dialog.columnconfigure(1, weight=1)
            symbol_var = tk.StringVar(value=raw_row.get("symbol", ""))
            quantity_var = tk.StringVar(value=raw_row.get("quantity", ""))
            statement_date_value = raw_row.get("statement_date", "") or date.today().isoformat()
            statement_date_var = tk.StringVar(value=statement_date_value)
            direction_var = tk.StringVar(
                value=manual_broker_statement_transfer_direction_label(
                    normalize_manual_broker_statement_transfer_direction(raw_row.get("transfer_direction", ""))
                )
            )
            counterparty_var = tk.StringVar(value=raw_row.get("counterparty", ""))
            owner_var = tk.StringVar(value=raw_row.get("owner", "") or current_owner_display_name())
            share_price_usd_var = tk.StringVar(value=raw_row.get("share_price_usd", ""))
            share_price_currency_var = tk.StringVar(
                value=normalize_manual_broker_statement_share_price_currency(
                    raw_row.get("share_price_currency", "")
                )
            )
            transfer_form_var = tk.StringVar(value=raw_row.get("transfer_form", ""))
            transfer_form_status_var = tk.StringVar(
                value=(
                    "Optional for paper-only confirmation: enter symbol, total quantity, and date. "
                    "The app matches it to Fidelity-observed transfers."
                )
            )

            def direction_code() -> str:
                return normalize_manual_broker_statement_transfer_direction(direction_var.get())

            def update_counterparty_label(*_args: object) -> None:
                direction = direction_code()
                if direction == "in":
                    counterparty_label_var.set("Sending institution")
                elif manual_broker_statement_is_outgoing_direction(direction):
                    counterparty_label_var.set("Receiving institution")
                else:
                    counterparty_label_var.set("Institution")

            def update_share_price_currency_state(*_args: object) -> None:
                if manual_broker_statement_is_outgoing_direction(direction_code()):
                    share_price_label_var.set("Arrival share price")
                    share_price_currency_combo.configure(state="readonly")
                else:
                    share_price_label_var.set("Share price USD")
                    share_price_currency_var.set("USD")
                    share_price_currency_combo.configure(state="disabled")

            def apply_transfer_form_defaults(*, overwrite: bool) -> bool:
                transfer_form_text = transfer_form_var.get().strip()
                if not transfer_form_text:
                    return False
                try:
                    transfer_form_path = gui_path(transfer_form_text)
                    if not is_pdf_file(transfer_form_path):
                        raise ValueError("Select a Fidelity transfer form PDF.")
                    duplicate_message = attached_transfer_form_duplicate_message(transfer_form_path, row_index)
                    if duplicate_message:
                        raise ValueError(duplicate_message)
                    symbol, quantity, receiving, lot_count = manual_statement_transfer_form_defaults(
                        transfer_form_path
                    )
                except Exception as exc:
                    transfer_form_status_var.set(f"Could not parse transfer form: {exc}")
                    return False

                if overwrite or not symbol_var.get().strip():
                    symbol_var.set(symbol)
                if overwrite or not quantity_var.get().strip():
                    quantity_var.set(format(quantity.normalize(), "f"))
                if overwrite or not direction_code():
                    direction_var.set("Transfer in")
                if overwrite or not counterparty_var.get().strip():
                    counterparty_var.set("Fidelity")
                if overwrite or not owner_var.get().strip():
                    owner_var.set(current_owner_display_name())
                if not statement_date_var.get().strip():
                    statement_date_var.set(date.today().isoformat())
                transfer_form_status_var.set(
                    f"Parsed {format_gui_quantity(quantity)} {symbol} share(s) "
                    f"from {lot_count} Fidelity transfer-form lot(s); receiving institution: {receiving}."
                )
                update_counterparty_label()
                return True

            def choose_manual_statement_transfer_form() -> None:
                selected = filedialog.askopenfilename(
                    **file_dialog_options(title="Select Fidelity transfer form PDF", filetypes=TRANSFER_FORM_FILETYPES)
                )
                if not selected:
                    return
                selected_path = gui_path(selected)
                if not is_pdf_file(selected_path):
                    messagebox.showwarning(
                        "Wrong file",
                        "Select the Fidelity transfer form PDF for this received statement row.",
                        parent=dialog,
                    )
                    return
                duplicate_message = attached_transfer_form_duplicate_message(selected_path, row_index)
                if duplicate_message:
                    messagebox.showwarning("SG manual row", duplicate_message, parent=dialog)
                    return
                remember_file_chooser_path(selected)
                transfer_form_var.set(display_path_text(selected_path))
                if not apply_transfer_form_defaults(overwrite=True):
                    messagebox.showwarning(
                        "SG manual row",
                        transfer_form_status_var.get() or "Could not parse transfer form.",
                        parent=dialog,
                    )

            ttk.Label(dialog, text="Transfer form (optional)").grid(
                row=0, column=0, sticky="w", padx=10, pady=(10, 3)
            )
            transfer_form_entry = ttk.Entry(dialog, textvariable=transfer_form_var, width=42)
            transfer_form_entry.grid(
                row=0,
                column=1,
                sticky="ew",
                padx=10,
                pady=(10, 3),
            )
            Tooltip(
                transfer_form_entry,
                "Optional for paper-only receipt confirmation. Enter the symbol, total quantity, and date; "
                "the app matches these against Fidelity-observed transfer-out lots.",
            )
            ttk.Button(
                dialog,
                text="Browse...",
                command=choose_manual_statement_transfer_form,
            ).grid(row=0, column=2, sticky="ew", padx=(0, 10), pady=(10, 3))
            ttk.Button(
                dialog,
                text="Parse",
                command=lambda: apply_transfer_form_defaults(overwrite=True),
            ).grid(row=0, column=3, sticky="ew", padx=(0, 10), pady=(10, 3))
            ttk.Label(
                dialog,
                textvariable=transfer_form_status_var,
                foreground="#555555",
                wraplength=540,
            ).grid(row=1, column=1, columnspan=3, sticky="w", padx=10, pady=(0, 5))

            ttk.Label(dialog, text="Symbol").grid(row=2, column=0, sticky="w", padx=10, pady=3)
            symbol_entry = ttk.Entry(dialog, textvariable=symbol_var, width=24)
            symbol_entry.grid(
                row=2, column=1, sticky="ew", padx=10, pady=3
            )
            ttk.Label(dialog, text="Quantity").grid(row=3, column=0, sticky="w", padx=10, pady=3)
            ttk.Entry(dialog, textvariable=quantity_var, width=24).grid(
                row=3, column=1, sticky="ew", padx=10, pady=3
            )
            ttk.Label(dialog, text="Statement date").grid(row=4, column=0, sticky="w", padx=10, pady=3)
            add_calendar_date_input(dialog, statement_date_var, width=14).grid(
                row=4, column=1, sticky="w", padx=10, pady=3
            )
            ttk.Label(dialog, text="Transfer").grid(row=5, column=0, sticky="w", padx=10, pady=3)
            direction_combo = ttk.Combobox(
                dialog,
                textvariable=direction_var,
                values=["No transfer", "Transfer in", "Transfer out", "Donation"],
                state="readonly",
                width=22,
            )
            direction_combo.grid(row=5, column=1, sticky="ew", padx=10, pady=3)
            counterparty_label_var = tk.StringVar(value="Institution")
            ttk.Label(dialog, textvariable=counterparty_label_var).grid(
                row=6, column=0, sticky="w", padx=10, pady=3
            )
            counterparty_combo = ttk.Combobox(
                dialog,
                textvariable=counterparty_var,
                values=manual_statement_counterparty_values(),
                width=22,
            )
            counterparty_combo.grid(row=6, column=1, sticky="ew", padx=10, pady=3)
            ttk.Label(dialog, text="Owner").grid(row=7, column=0, sticky="w", padx=10, pady=3)
            owner_combo = ttk.Combobox(
                dialog,
                textvariable=owner_var,
                values=owner_choice_values(),
                state="readonly",
                width=22,
            )
            owner_combo.grid(row=7, column=1, sticky="ew", padx=10, pady=3)
            share_price_label_var = tk.StringVar(value="Share price USD")
            ttk.Label(dialog, textvariable=share_price_label_var).grid(row=8, column=0, sticky="w", padx=10, pady=3)
            ttk.Entry(dialog, textvariable=share_price_usd_var, width=24).grid(
                row=8, column=1, sticky="ew", padx=10, pady=3
            )
            share_price_currency_combo = ttk.Combobox(
                dialog,
                textvariable=share_price_currency_var,
                values=MANUAL_BROKER_STATEMENT_SHARE_PRICE_CURRENCIES,
                state="readonly",
                width=8,
            )
            share_price_currency_combo.grid(row=8, column=2, sticky="w", padx=(0, 10), pady=3)
            direction_var.trace_add("write", update_counterparty_label)
            direction_var.trace_add("write", update_share_price_currency_state)
            update_counterparty_label()
            update_share_price_currency_state()
            apply_transfer_form_defaults(overwrite=False)

            button_frame = ttk.Frame(dialog)
            button_frame.grid(row=9, column=0, columnspan=4, sticky="e", padx=10, pady=(8, 10))

            def save_row() -> None:
                raw_candidate = {
                    "symbol": symbol_var.get().strip(),
                    "quantity": quantity_var.get().strip(),
                    "statement_date": statement_date_var.get().strip(),
                    "transfer_direction": direction_code(),
                    "counterparty": counterparty_var.get().strip(),
                    "owner": owner_var.get().strip(),
                    "share_price_usd": share_price_usd_var.get().strip(),
                    "share_price_currency": (
                        share_price_currency_var.get().strip()
                        if manual_broker_statement_is_outgoing_direction(direction_code())
                        else "USD"
                    ),
                    "transfer_form": transfer_form_var.get().strip(),
                    "source_lot_quantities": raw_row.get("source_lot_quantities", ""),
                }
                transfer_form_text = raw_candidate["transfer_form"]
                if transfer_form_text:
                    duplicate_message = attached_transfer_form_duplicate_message(gui_path(transfer_form_text), row_index)
                    if duplicate_message:
                        messagebox.showwarning("SG manual row", duplicate_message, parent=dialog)
                        return
                try:
                    parsed_row = parse_manual_statement_row(raw_candidate)
                except (decimal.InvalidOperation, ValueError) as exc:
                    messagebox.showwarning("SG manual row", str(exc), parent=dialog)
                    return
                normalized_row = manual_statement_row_preferences(parsed_row)
                if row_index is None:
                    state.manual_statement_rows.append(normalized_row)
                else:
                    state.manual_statement_rows[row_index] = normalized_row
                render_manual_statement_rows()
                clear_output_on_change()
                dialog.destroy()

            ttk.Button(button_frame, text="OK", command=save_row).grid(row=0, column=0, sticky="e")
            ttk.Button(button_frame, text="Cancel", command=dialog.destroy).grid(
                row=0, column=1, sticky="e", padx=(6, 0)
            )
            dialog.bind("<Return>", lambda _event: save_row())
            dialog.bind("<Escape>", lambda _event: dialog.destroy())
            dialog.update_idletasks()
            dialog.geometry(f"+{root.winfo_rootx() + 90}+{root.winfo_rooty() + 90}")
            dialog.grab_set()
            transfer_form_entry.focus_set()

        def render_manual_statement_rows() -> None:
            if state.manual_statement_rows_frame is None:
                return
            for child in state.manual_statement_rows_frame.winfo_children():
                child.destroy()
            state.manual_statement_rows_frame.columnconfigure(0, weight=1)
            if not state.manual_statement_rows:
                ttk.Label(state.manual_statement_rows_frame, text="No SG manual rows").grid(
                    row=0,
                    column=0,
                    sticky="w",
                )
                return
            headings = ("Symbol", "Qty", "Date", "Transfer", "Institution", "Owner", "Price", "Form")
            for column, heading in enumerate(headings):
                ttk.Label(state.manual_statement_rows_frame, text=heading, font=pdf_bold_font).grid(
                    row=0,
                    column=column,
                    sticky="w",
                    padx=(0 if column == 0 else 8, 0),
                )
            for row_number, raw_row in enumerate(state.manual_statement_rows, 1):
                try:
                    parsed_row = parse_manual_statement_row(raw_row)
                    values = (
                        parsed_row.symbol,
                        format_gui_quantity(parsed_row.quantity),
                        parsed_row.statement_date.strftime("%d/%m/%Y"),
                        manual_broker_statement_transfer_direction_label(parsed_row.transfer_direction),
                        parsed_row.counterparty or "-",
                        parsed_row.owner,
                        (
                            f"{format(parsed_row.share_price_usd.normalize(), 'f')} "
                            f"{normalize_manual_broker_statement_share_price_currency(parsed_row.share_price_currency)}"
                            if parsed_row.share_price_usd
                            else "-"
                        ),
                        parsed_row.transfer_form_path.name if parsed_row.transfer_form_path else "-",
                    )
                    row_style = ""
                except (decimal.InvalidOperation, ValueError):
                    values = (
                        raw_row.get("symbol", ""),
                        raw_row.get("quantity", ""),
                        raw_row.get("statement_date", ""),
                        "Invalid",
                        raw_row.get("counterparty", ""),
                        raw_row.get("owner", ""),
                        (
                            f"{raw_row.get('share_price_usd', '')} "
                            f"{normalize_manual_broker_statement_share_price_currency(raw_row.get('share_price_currency', ''))}"
                            if raw_row.get("share_price_usd", "")
                            else ""
                        ),
                        Path(raw_row.get("transfer_form", "")).name if raw_row.get("transfer_form", "") else "",
                    )
                    row_style = "QuoteError.TLabel"
                for column, value in enumerate(values):
                    kwargs = {"style": row_style} if row_style else {}
                    ttk.Label(state.manual_statement_rows_frame, text=value, **kwargs).grid(
                        row=row_number,
                        column=column,
                        sticky="w",
                        padx=(0 if column == 0 else 8, 0),
                    )
                ttk.Button(
                    state.manual_statement_rows_frame,
                    text="Edit",
                    command=lambda index=row_number - 1: show_manual_statement_row_dialog(index),
                ).grid(row=row_number, column=len(headings), sticky="e", padx=(8, 0))
                ttk.Button(
                    state.manual_statement_rows_frame,
                    text="Remove",
                    command=lambda index=row_number - 1: remove_manual_statement_row(index),
                ).grid(row=row_number, column=len(headings) + 1, sticky="e", padx=(4, 0))

        def manual_statement_row_confirmation_text(raw_row: dict[str, str]) -> str:
            try:
                parsed_row = parse_manual_statement_row(raw_row)
            except (decimal.InvalidOperation, ValueError):
                parts = [
                    raw_row.get("symbol", "").strip(),
                    raw_row.get("quantity", "").strip(),
                    raw_row.get("statement_date", "").strip(),
                ]
                summary = " ".join(part for part in parts if part) or "this invalid manual statement row"
                return f"Remove {summary}?"
            transfer_label = manual_broker_statement_transfer_direction_label(parsed_row.transfer_direction)
            if parsed_row.counterparty:
                if parsed_row.transfer_direction == "in":
                    transfer_label = f"{transfer_label} from {parsed_row.counterparty}"
                elif manual_broker_statement_is_outgoing_direction(parsed_row.transfer_direction):
                    transfer_label = f"{transfer_label} to {parsed_row.counterparty}"
            return (
                f"Remove manual statement row?\n\n"
                f"Symbol: {parsed_row.symbol}\n"
                f"Quantity: {format_gui_quantity(parsed_row.quantity)}\n"
                f"Statement date: {parsed_row.statement_date.strftime('%d/%m/%Y')}\n"
                f"Transfer: {transfer_label}\n"
                f"Owner: {parsed_row.owner}"
            )

        def remove_manual_statement_row(row_index: int) -> None:
            if 0 <= row_index < len(state.manual_statement_rows):
                raw_row = state.manual_statement_rows[row_index]
                if not messagebox.askyesno(
                    "Remove manual statement",
                    manual_statement_row_confirmation_text(raw_row),
                    parent=root,
                ):
                    return
                del state.manual_statement_rows[row_index]
                render_manual_statement_rows()
                clear_output_on_change()

        def update_manual_statement_row_visibility() -> None:
            if state.manual_statement_rows_frame is None:
                return
            visible = broker_state_is_sg(state)
            for widget in (
                getattr(state.manual_statement_rows_frame, "label_frame", None),
                state.manual_statement_rows_frame,
                getattr(state.manual_statement_rows_frame, "add_button", None),
            ):
                if widget is None:
                    continue
                if visible:
                    widget.grid()
                else:
                    widget.grid_remove()
            if visible:
                render_manual_statement_rows()

        add_field_label(0, "Broker name", required=False, parent=frame)
        broker_name_entry = ttk.Combobox(
            frame,
            textvariable=state.name_var,
            values=("Societe Generale", "Interactive Brokers"),
        )
        broker_name_entry.grid(row=0, column=1, sticky="ew", padx=8, pady=3)
        state.name_var.trace_add("write", lambda *_args: (update_broker_tab_titles(), clear_output_on_change()))
        state.closed_lots_entry, _closed_button = add_file_row(
            1,
            "Closed lots CSV",
            state.closed_lots_var,
            "Select other broker closed lots CSV",
            [("CSV files", CSV_FILE_PATTERN), ("All files", "*")],
            required=False,
            validator=is_other_broker_closed_lots_csv,
            invalid_message="Select an other broker closed lots CSV with the expected header.",
            parent=frame,
        )
        add_disabled_broker_help_button(frame, 1, "Closed lots CSV")
        add_file_row(
            2,
            "Transaction history CSV",
            state.transaction_history_var,
            "Select broker transaction history CSV",
            [("CSV files", CSV_FILE_PATTERN), ("All files", "*")],
            required=False,
            parent=frame,
        )
        add_disabled_broker_help_button(frame, 2, "Transaction history CSV")
        add_file_row(
            3,
            "Award details",
            state.award_details_var,
            "Select broker award details file",
            [("PDF files", "*.pdf"), ("CSV files", CSV_FILE_PATTERN), ("All files", "*")],
            required=False,
            parent=frame,
        )
        add_disabled_broker_help_button(frame, 3, "Award details")
        state.transfer_forms_frame = add_path_list_row(
            frame,
            4,
            "Transfer form PDFs",
            state.transfer_form_vars,
            "Select broker transfer form PDF(s)",
            TRANSFER_FORM_FILETYPES,
            is_pdf_file,
            "Select one or more transfer form PDFs.",
            disabled_help=True,
            path_kind="transfer",
        )
        state.open_lots_entry, _open_button = add_file_row(
            5,
            "Open lots CSV",
            state.open_lots_var,
            "Select other broker open lots CSV",
            [("CSV files", CSV_FILE_PATTERN), ("All files", "*")],
            required=False,
            validator=is_other_broker_open_lots_csv,
            invalid_message="Select an other broker open lots CSV with the expected header.",
            parent=frame,
        )
        add_disabled_broker_help_button(frame, 5, "Open lots CSV")
        state.broker_statements_frame = add_path_list_row(
            frame,
            6,
            "Broker statement CSVs",
            state.broker_statement_vars,
            "Select broker statement CSV(s)",
            BROKER_STATEMENT_FILETYPES,
            is_broker_statement_csv,
            "Select recognized broker activity statement CSVs, such as Interactive Brokers statement CSVs.",
            disabled_help=True,
            path_kind="statement",
        )
        state.broker_statement_focus_widget = state.broker_statements_frame
        manual_rows_label_frame = add_field_label(7, "Manual SG statement rows", required=False, sticky="nw", parent=frame)
        state.manual_statement_rows_frame = ttk.Frame(frame)
        state.manual_statement_rows_frame.grid(row=7, column=1, sticky="ew", padx=8, pady=3)
        state.manual_statement_rows_frame.label_frame = manual_rows_label_frame  # type: ignore[attr-defined]
        add_manual_statement_row_button = ttk.Button(
            frame,
            text="Add...",
            command=lambda: show_manual_statement_row_dialog(),
        )
        add_manual_statement_row_button.grid(row=7, column=2, sticky="new", pady=3)
        state.manual_statement_rows_frame.add_button = add_manual_statement_row_button  # type: ignore[attr-defined]
        Tooltip(
            add_manual_statement_row_button,
            "Add a Societe Generale manual statement row: symbol, quantity, statement date, transfer direction, institution, and owner.",
        )
        for variable in (
            state.closed_lots_var,
            state.transaction_history_var,
            state.award_details_var,
            state.open_lots_var,
        ):
            variable.trace_add("write", broker_state_path_changed)
        state.name_var.trace_add("write", broker_state_path_changed)
        render_manual_statement_rows()
        update_manual_statement_row_visibility()
        return frame

    def add_broker_tab(state: BrokerInputTabState | None = None, *, select: bool = False) -> BrokerInputTabState:
        state = state or create_broker_input_tab_state({"name": f"Broker {len(broker_input_tabs) + 1}"})
        if state not in broker_input_tabs:
            broker_input_tabs.append(state)
        frame = build_other_broker_tab(state, len(broker_input_tabs))
        try:
            insert_index: int | str = broker_notebook.index(broker_plus_frame)
        except (NameError, tk.TclError):
            insert_index = "end"
        broker_notebook.insert(insert_index, frame, text=broker_tab_name_for_state(state, len(broker_input_tabs)))
        broker_notebook_tabs[frame] = state
        update_broker_tab_titles()
        if select:
            broker_notebook.select(frame)
        return state

    def add_broker_from_plus_tab() -> None:
        plus_frame = broker_plus_frame
        for state in broker_input_tabs:
            if not state.name_var.get().strip() and not broker_input_tab_has_data(state):
                if state.frame is not None:
                    broker_notebook.select(state.frame)
                return
        index = broker_notebook.index(plus_frame)
        state = create_broker_input_tab_state()
        broker_input_tabs.append(state)
        frame = build_other_broker_tab(state, len(broker_input_tabs))
        broker_notebook.insert(index, frame, text=broker_tab_name_for_state(state, len(broker_input_tabs)))
        broker_notebook_tabs[frame] = state
        update_broker_tab_titles()
        broker_notebook.select(frame)
        clear_output_on_change()

    def last_real_broker_notebook_index() -> int:
        tabs = broker_notebook.tabs()
        if not tabs:
            return 0
        try:
            plus_index = broker_notebook.index(broker_plus_frame)
        except (NameError, tk.TclError):
            plus_index = len(tabs)
        return max(0, plus_index - 1)

    def selected_broker_tab_index_for_preferences() -> int:
        try:
            selected_tab = broker_notebook.select()
            if not selected_tab:
                return preference_int(GUI_LAST_BROKER_TAB_INDEX_PREFERENCE_KEY, 0)
            selected_index = broker_notebook.index(selected_tab)
            try:
                plus_index = broker_notebook.index(broker_plus_frame)
            except (NameError, tk.TclError):
                plus_index = -1
            if selected_index == plus_index:
                return preference_int(GUI_LAST_BROKER_TAB_INDEX_PREFERENCE_KEY, 0)
            return max(0, min(selected_index, last_real_broker_notebook_index()))
        except tk.TclError:
            return preference_int(GUI_LAST_BROKER_TAB_INDEX_PREFERENCE_KEY, 0)

    def restore_broker_notebook_selection_from_preferences() -> None:
        target_index = max(
            0,
            min(
                preference_int(GUI_LAST_BROKER_TAB_INDEX_PREFERENCE_KEY, 0),
                last_real_broker_notebook_index(),
            ),
        )
        try:
            broker_notebook.select(target_index)
        except tk.TclError:
            pass

    def broker_tab_changed(_event: tk.Event | None = None) -> None:
        selected_tab = broker_notebook.select()
        if selected_tab and broker_notebook_tabs.get(broker_notebook.nametowidget(selected_tab)) == "plus":
            add_broker_from_plus_tab()
            return
        try:
            persist_gui_preferences()
        except NameError:
            pass

    fidelity_input_frame = build_fidelity_broker_tab()
