    def carry_forward_value_text(value: Decimal) -> str:
        if value == value.to_integral_value():
            return f"{value:.0f}"
        return format(value.normalize(), "f")

    def parse_carry_forward_editor_value(text: str) -> Decimal | None:
        normalized = normalized_decimal_preference_text(text)
        if not normalized:
            return None
        return Decimal(normalized)

    def carry_forward_box_description(box: str) -> str:
        if box in SALARY_BOX_TO_EXPENSE_BOX:
            return "salary"
        if box in SALARY_BOX_TO_EXPENSE_BOX.values():
            return "actual expenses"
        if box in EXEMPT_OVERTIME_BOXES:
            return "exempt overtime / RTT"
        if box in RCM_RFR_BOXES:
            return "RCM / dividends"
        if box in RCM_INFORMATION_OR_CREDIT_BOXES:
            return "RCM info / credit"
        if re.fullmatch(r"6N[STU]", box):
            return "PER deduction"
        return "parsed 2042 box"

    def open_2042_carry_forward_editor() -> None:
        path = pdf_path_from_variable(declaration_2042_pdf_var)
        if path is None:
            messagebox.showwarning(
                "Carry-forward values",
                "Select an existing 2042 declaration PDF first.",
            )
            return
        try:
            text = extract_pdf_text(path)
            parsed_boxes = parse_2042_declared_boxes(text)
        except Exception as exc:
            messagebox.showerror("Carry-forward values", f"Could not parse this 2042 PDF:\n{exc}")
            return
        if not parsed_boxes:
            messagebox.showwarning(
                "Carry-forward values",
                "No 2042 declaration boxes were parsed from this PDF.",
            )
            return

        path_key = path_compare_key(path)
        saved_overrides = carry_forward_box_overrides_by_pdf.get(path_key, {})
        visible_boxes = {
            box
            for box in {*parsed_boxes.keys(), *saved_overrides.keys()}
            if box not in CALCULATOR_PROJECTED_RFR_BOXES
        }
        if not visible_boxes:
            messagebox.showwarning(
                "Carry-forward values",
                "This 2042 PDF has no parsed non-share-plan boxes to carry forward.",
            )
            return

        baseline_year = parse_pdf_income_year(text)
        year_note = f" income year {baseline_year}" if baseline_year is not None else ""
        popup = tk.Toplevel(root)
        set_window_title(popup, "2042 Carry-Forward Values")
        popup.transient(root)
        popup.grab_set()
        popup.columnconfigure(0, weight=1)
        popup.rowconfigure(1, weight=1)
        ttk.Label(
            popup,
            text=(
                f"2042{year_note}: values below are carried forward when Projected mode uses this PDF. "
                "Blank means use the parsed PDF value; 1TZ/1WZ/1TT and 3VG/3VH are recomputed or neutralized."
            ),
            wraplength=760,
        ).grid(row=0, column=0, sticky="ew", padx=12, pady=(12, 8))

        body = ttk.Frame(popup)
        body.grid(row=1, column=0, sticky="nsew", padx=12)
        body.columnconfigure(0, weight=1)
        body.rowconfigure(0, weight=1)
        canvas = tk.Canvas(body, borderwidth=0, highlightthickness=0, height=380)
        scrollbar = ttk.Scrollbar(body, orient="vertical", command=canvas.yview)
        rows_frame = ttk.Frame(canvas)
        rows_frame.columnconfigure(3, weight=1)
        canvas_window = canvas.create_window((0, 0), window=rows_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.grid(row=0, column=0, sticky="nsew")
        scrollbar.grid(row=0, column=1, sticky="ns")

        def resize_canvas_window(event: tk.Event) -> None:
            canvas.itemconfigure(canvas_window, width=event.width)

        def update_scrollregion(_event: tk.Event | None = None) -> None:
            canvas.configure(scrollregion=canvas.bbox("all"))

        canvas.bind("<Configure>", resize_canvas_window, add="+")
        rows_frame.bind("<Configure>", update_scrollregion, add="+")

        ttk.Label(rows_frame, text="Box", font=pdf_bold_font).grid(row=0, column=0, sticky="w", padx=(0, 8))
        ttk.Label(rows_frame, text="Parsed EUR", font=pdf_bold_font).grid(row=0, column=1, sticky="e", padx=(0, 8))
        ttk.Label(rows_frame, text="Carried-forward EUR", font=pdf_bold_font).grid(
            row=0,
            column=2,
            sticky="w",
            padx=(0, 8),
        )
        ttk.Label(rows_frame, text="Meaning", font=pdf_bold_font).grid(row=0, column=3, sticky="w")

        entry_vars: dict[str, tk.StringVar] = {}
        for row_index, box in enumerate(sorted(visible_boxes, key=declaration_box_sort_key), 1):
            parsed_value = parsed_boxes.get(box, Decimal("0"))
            carried_value = saved_overrides.get(box, parsed_value)
            entry_var = tk.StringVar(value=carry_forward_value_text(carried_value))
            entry_vars[box] = entry_var
            ttk.Label(rows_frame, text=box).grid(row=row_index, column=0, sticky="w", padx=(0, 8), pady=2)
            ttk.Label(rows_frame, text=carry_forward_value_text(parsed_value)).grid(
                row=row_index,
                column=1,
                sticky="e",
                padx=(0, 8),
                pady=2,
            )
            ttk.Entry(rows_frame, textvariable=entry_var, width=16).grid(
                row=row_index,
                column=2,
                sticky="w",
                padx=(0, 8),
                pady=2,
            )
            ttk.Label(rows_frame, text=carry_forward_box_description(box)).grid(
                row=row_index,
                column=3,
                sticky="w",
                pady=2,
            )

        button_row = ttk.Frame(popup)
        button_row.grid(row=2, column=0, sticky="ew", padx=12, pady=12)
        button_row.columnconfigure(0, weight=1)

        def reset_entries_to_parsed() -> None:
            for box, entry_var in entry_vars.items():
                entry_var.set(carry_forward_value_text(parsed_boxes.get(box, Decimal("0"))))

        def save_overrides() -> None:
            new_overrides: dict[str, Decimal] = {}
            for box, entry_var in entry_vars.items():
                raw_value = entry_var.get().strip()
                parsed_entry = parse_carry_forward_editor_value(raw_value)
                if parsed_entry is None:
                    if raw_value:
                        messagebox.showwarning(
                            "Carry-forward values",
                            f"Enter a valid EUR amount for box {box}, or leave it blank to use the parsed value.",
                            parent=popup,
                        )
                        return
                    continue
                parsed_pdf_value = parsed_boxes.get(box, Decimal("0"))
                if parsed_entry != parsed_pdf_value:
                    new_overrides[box] = parsed_entry
            if new_overrides:
                carry_forward_box_overrides_by_pdf[path_key] = new_overrides
            else:
                carry_forward_box_overrides_by_pdf.pop(path_key, None)
            persist_gui_preferences()
            popup.destroy()
            clear_output_on_change()

        ttk.Button(button_row, text="Reset to parsed", command=reset_entries_to_parsed).grid(
            row=0,
            column=1,
            sticky="e",
        )
        ttk.Button(button_row, text="Save", command=save_overrides).grid(row=0, column=2, sticky="e", padx=(8, 0))
        ttk.Button(button_row, text="Cancel", command=popup.destroy).grid(row=0, column=3, sticky="e", padx=(8, 0))
        popup.protocol("WM_DELETE_WINDOW", popup.destroy)

