    def append_output(text: str) -> None:
        parts = re.split(r"(\*\*.*?\*\*)", text)
        for part in parts:
            if part.startswith("**") and part.endswith("**") and len(part) >= 4:
                output.insert("end", part[2:-2], "bold")
            else:
                output.insert("end", part)
        output.see("end")

    def gui_pdf_parse_event(text: str) -> None:
        try:
            root.after(0, lambda text=text: append_output(text))
        except tk.TclError:
            pass

