    def run_button_label() -> str:
        return "Estimate" if is_estimate_mode() else "Declare"

    def update_now_tooltip_text() -> str:
        if update_installed:
            return "Update installed. Click Restart now to relaunch the calculator."
        if restart_pending_reason:
            return f"{restart_pending_reason}\nClick Restart now to relaunch the calculator."
        if update_check_in_progress:
            return "Checking GitHub for program updates..."
        if update_check_result is None:
            return "Check GitHub for program updates."
        if update_check_result.update_available:
            latest = update_check_result.remote_revision[:8] if update_check_result.remote_revision else "unknown"
            subject = update_check_result.remote_subject.strip()
            if subject:
                return (
                    "Update available.\n"
                    f"Latest commit: {latest}\n"
                    f"{subject}\n"
                    "Click to update; Restart now appears after a successful update."
                )
            return (
                "Update available.\n"
                f"{update_check_result.message}\n"
                "Click to update; Restart now appears after a successful update."
            )
        return f"Last update check: {update_check_result.message}\nClick to check/update from GitHub."

    def update_update_button_state() -> None:
        update_now_tooltip_var.set(update_now_tooltip_text())
        try:
            restart_pending = bool(update_installed or restart_pending_reason)
            update_available = bool(
                update_check_result
                and update_check_result.update_available
                and not restart_pending
            )
            button_style = "UpdateAvailable.TButton" if update_available else "TButton"
            if run_in_progress or verify_in_progress:
                text = "Restart now" if restart_pending else "Update now"
                update_now_button.configure(text=text, state="disabled", style=button_style)
            elif restart_pending:
                update_now_button.configure(text="Restart now", state="normal", style="UpdateAvailable.TButton")
            elif update_check_in_progress:
                update_now_button.configure(text="Update now", state="normal", style=button_style)
            else:
                update_now_button.configure(text="Update now", state="normal", style=button_style)
        except NameError:
            pass

    def finish_update_check(result: UpdateCheckResult) -> None:
        nonlocal update_check_result, update_check_in_progress, restart_pending_reason
        update_check_in_progress = False
        update_check_result = result
        if (
            not result.update_available
            and running_program_revision
            and current_program_version() != running_program_revision
        ):
            restart_pending_reason = "Program files changed on disk since this window started."
        append_output(f"\nUpdate check: {result.message}\n")
        update_update_button_state()

    def start_update_check(force: bool = False) -> None:
        nonlocal update_check_in_progress, last_update_check_monotonic
        if update_installed or restart_pending_reason or update_check_in_progress:
            return
        now = time.monotonic()
        if (
            not force
            and last_update_check_monotonic is not None
            and now - last_update_check_monotonic < GUI_UPDATE_CHECK_THROTTLE_SECONDS
        ):
            return
        update_check_in_progress = True
        last_update_check_monotonic = now
        update_update_button_state()

        def worker() -> None:
            result = check_program_update()
            root.after(0, lambda result=result: finish_update_check(result))

        threading.Thread(target=worker, daemon=True).start()

    def restart_program_after_update() -> None:
        if not update_installed and not restart_pending_reason:
            run_program_update()
            return
        try:
            persist_gui_preferences()
            if getattr(sys, "frozen", False):
                command = [sys.executable, *sys.argv[1:]]
            else:
                script_path = Path(sys.argv[0]).resolve() if sys.argv and sys.argv[0] else Path(__file__).resolve()
                command = [sys.executable, str(script_path), *sys.argv[1:]]
            subprocess.Popen(command, cwd=str(Path.cwd()))
        except Exception as exc:
            messagebox.showerror("Restart", f"Could not restart the calculator:\n{exc}")
            append_output(f"\nRestart failed: {exc}\n")
            return
        append_output("\nRestarting calculator...\n")
        close_app()

    def update_or_restart_program() -> None:
        if update_installed or restart_pending_reason:
            restart_program_after_update()
        else:
            run_program_update()

    def finish_program_update(message: str | None = None, error: BaseException | None = None) -> None:
        nonlocal update_check_result, update_installed, restart_pending_reason
        if error is not None:
            if isinstance(error, ProgramUpdateLocalChangesError):
                update_check_result = None
                update_installed = False
                restart_pending_reason = "Local tracked changes are present; Git auto-update was skipped."
                update_update_button_state()
                append_output(
                    "\n"
                    f"{error}\n"
                    "Auto-update was skipped to avoid overwriting local work.\n"
                    "Click Restart now to relaunch the calculator with the current local files.\n"
                )
                return
            update_now_button.configure(state="normal", text="Retry update", style="TButton")
            update_now_tooltip_var.set(f"Last auto-update failed:\n{error}")
            append_output(f"\nAuto-update failed: {error}\n")
            return
        if message and message.startswith("Updated program:"):
            update_check_result = None
            update_installed = True
            restart_pending_reason = ""
            update_update_button_state()
            append_output(f"\n{message}\nClick Restart now to relaunch the calculator with the updated version.\n")
            return
        update_check_result = None
        update_installed = False
        disk_revision = current_program_version()
        if running_program_revision and disk_revision != running_program_revision:
            restart_pending_reason = "Program files changed on disk since this window started."
            message = (
                f"{message or 'Program was already up to date.'}\n"
                "The running window loaded an older revision; click Restart now to load the current files."
            )
        else:
            restart_pending_reason = ""
        update_update_button_state()
        append_output(f"\n{message}\n")

    def run_program_update() -> None:
        update_now_button.configure(state="disabled", text="Updating...", style="TButton")
        update_now_tooltip_var.set("Updating program from GitHub...")
        append_output("\nUpdating program from GitHub...\n")

        def worker() -> None:
            try:
                message = update_program_from_git()
            except BaseException as exc:
                root.after(0, lambda exc=exc: finish_program_update(error=exc))
            else:
                root.after(0, lambda message=message: finish_program_update(message=message))

        threading.Thread(target=worker, daemon=True).start()

    def build_issue_description(user_text: str) -> str:
        version = current_program_version()
        python_version = sys.version.split()[0]
        return (
            "### Description\n"
            f"{user_text.strip()}\n\n"
            "### Program version\n"
            f"`{version}`\n\n"
            "### Environment\n"
            f"- Python: `{python_version}`\n"
            f"- Platform: `{sys.platform}`\n\n"
            "### Privacy check\n"
            "Do not attach Fidelity exports, payroll files, or tax declaration PDFs unless you intend to share private financial data."
        )

    def open_github_issue(title: str, description: str) -> None:
        query = urllib.parse.urlencode(
            {
                "title": title,
                "body": description,
            }
        )
        issue_url = f"{GITHUB_NEW_ISSUE_URL}?{query}"
        opened = webbrowser.open(issue_url, new=2)
        if opened:
            append_output("\nOpened a prefilled GitHub issue in the browser.\n")
            return
        root.clipboard_clear()
        root.clipboard_append(issue_url)
        root.update()
        messagebox.showwarning(
            "Report Issue",
            "Could not open the browser. The prefilled GitHub issue URL was copied to the clipboard.",
        )

    def report_issue() -> None:
        start_update_check()
        popup = tk.Toplevel(root)
        set_window_title(popup, "Report Issue")
        popup.transient(root)
        popup.grab_set()
        popup.minsize(720, 420)
        popup.columnconfigure(0, weight=1)
        popup.rowconfigure(3, weight=1)

        ttk.Label(
            popup,
            text="Describe the issue. The current program version will be added automatically.",
        ).grid(row=0, column=0, sticky="w", padx=12, pady=(12, 6))

        title_var = tk.StringVar(value="RSU Tax Calculator issue")
        ttk.Label(popup, text="Title").grid(row=1, column=0, sticky="w", padx=12, pady=(0, 3))
        ttk.Entry(popup, textvariable=title_var).grid(row=2, column=0, sticky="ew", padx=12, pady=(0, 8))

        description_text = tk.Text(popup, height=12, wrap="word")
        description_text.grid(row=3, column=0, sticky="nsew", padx=12)
        description_text.focus_set()

        button_row = ttk.Frame(popup)
        button_row.grid(row=4, column=0, sticky="ew", padx=12, pady=12)
        button_row.columnconfigure(0, weight=1)

        def submit_issue() -> None:
            user_text = description_text.get("1.0", "end-1c").strip()
            if not user_text:
                messagebox.showwarning("Report Issue", "Describe the issue before opening GitHub.")
                description_text.focus_set()
                return
            title = title_var.get().strip() or "RSU Tax Calculator issue"
            description = build_issue_description(user_text)
            open_github_issue(title, description)
            popup.destroy()

        ttk.Button(button_row, text="Open GitHub Issue", command=submit_issue).grid(row=0, column=1, sticky="e")
        ttk.Button(button_row, text="Cancel", command=popup.destroy).grid(row=0, column=2, sticky="e", padx=(8, 0))

