    def save_active_owner_preferences_snapshot(snapshot: dict[str, object]) -> None:
        nonlocal preferences
        snapshot_copy = copy.deepcopy(snapshot)
        if active_owner_name:
            owner_preferences_by_name[active_owner_name] = snapshot_copy
        else:
            default_owner_preferences.clear()
            default_owner_preferences.update(snapshot_copy)
        preferences = copy.deepcopy(snapshot_copy)

    def combined_gui_preferences_for_save() -> dict[str, object]:
        data = copy.deepcopy(default_owner_preferences)
        if owner_preferences_by_name:
            data[GUI_OWNERS_PREFERENCE_KEY] = copy.deepcopy(owner_preferences_by_name)
        if active_owner_name:
            data[GUI_ACTIVE_OWNER_PREFERENCE_KEY] = active_owner_name
        else:
            data.pop(GUI_ACTIVE_OWNER_PREFERENCE_KEY, None)
        return data

    def save_combined_gui_preferences() -> None:
        save_gui_preferences(combined_gui_preferences_for_save())

    def clear_cached_data() -> None:
        nonlocal last_run_completed, last_calculation_result, last_verify_details_text, preferences
        try:
            deleted_pdf_cache = clear_pdf_parse_cache()
        except OSError as exc:
            append_output(f"\nClear cache: could not remove parsed-PDF cache: {exc}\n")
            return
        pdf_paths_by_year.clear()
        carry_forward_box_overrides_by_pdf.clear()
        advise_selected_lots_by_year.clear()
        advise_in_transfer_lots_by_year.clear()
        advise_transfer_in_confirmations_by_year.clear()
        advise_pending_sold_lots_by_year.clear()
        advise_placed_sale_orders_by_year.clear()
        advise_last_placed_sale_orders_by_year.clear()
        advise_last_tab_by_year.clear()
        advice_share_prices_by_symbol.clear()
        advice_share_price_var.set("")
        path_only_preferences = current_path_only_gui_preferences()
        save_active_owner_preferences_snapshot(path_only_preferences)
        for field in pdf_variables:
            set_pdf_status(field, "default")
        last_run_completed = False
        last_calculation_result = None
        last_verify_details_text = ""
        last_verify_details_document_tooltips.clear()
        try:
            save_combined_gui_preferences()
        except OSError as exc:
            append_output(f"\nClear cache: could not save reduced GUI settings: {exc}\n")
            return
        append_output(
            "\nClear cache: removed parsed-PDF cache"
            + ("." if deleted_pdf_cache else " (no parsed-PDF cache file existed).")
            + "\nClear cache: cleared Advise selections, transfer confirmations/in-transfer state, "
            "carry-forward overrides, and per-year PDF status cache; kept visible file paths.\n"
        )
        update_post_run_buttons()

    def persist_gui_preferences() -> None:
        if suppress_preference_persist:
            return
        try:
            save_active_owner_preferences_snapshot(current_gui_preferences())
            save_combined_gui_preferences()
        except OSError as exc:
            append_output(f"\nCould not save GUI preferences: {exc}\n")

