    def load_advice_share_prices_from_active_preferences() -> None:
        advice_share_price_var.set(preference_text("advice_share_price_usd", ""))
        advice_share_prices_by_symbol.clear()
        raw_prices = preferences.get("advice_share_prices_usd", {})
        if isinstance(raw_prices, dict):
            for raw_symbol, raw_price in raw_prices.items():
                symbol = str(raw_symbol).strip().upper()
                price = str(raw_price).strip()
                if symbol and price:
                    advice_share_prices_by_symbol[symbol] = price
        if advice_share_price_var.get().strip() and ARM_QUOTE_SYMBOL not in advice_share_prices_by_symbol:
            advice_share_prices_by_symbol[ARM_QUOTE_SYMBOL] = advice_share_price_var.get().strip()

