    def switch_owner(owner_choice: str) -> None:
        nonlocal active_owner_name, preferences
        requested_owner = "" if owner_choice == GUI_DEFAULT_OWNER_LABEL else normalize_owner_name(owner_choice)
        if requested_owner == active_owner_name:
            return
        save_current_owner_state_for_switch()
        active_owner_name = requested_owner
        if active_owner_name:
            preferences = copy.deepcopy(owner_preferences_by_name.get(active_owner_name, {}))
        else:
            preferences = copy.deepcopy(default_owner_preferences)
        apply_active_owner_preferences_to_gui()
        try:
            save_combined_gui_preferences()
        except OSError as exc:
            append_output(f"\nCould not save selected owner: {exc}\n")

