    def finish_rates_download(path: Path | None = None, error: BaseException | None = None) -> None:
        set_download_rates_enabled(True)
        if error is not None:
            append_output(f"\nExchange-rate CSV download failed: {error}\n")
            messagebox.showerror("Download exchange rates", str(error))
            return
        if path is None:
            return
        set_rates_csv_field_enabled(True)
        rates_csv_var.set(display_path_text(path))
        persist_gui_preferences()
        append_output(f"\nDownloaded and saved exchange-rate CSV: {path}\n")

    def download_rates_from_gui() -> None:
        set_download_rates_enabled(False)
        append_output(f"\nDownloading exchange-rate CSV from Banque de France/Webstat...\n{BDF_WEBSTAT_DOWNLOAD_URL}\n")

        def worker() -> None:
            try:
                downloaded_path = download_bdf_webstat_csv()
            except BaseException as exc:
                root.after(0, lambda exc=exc: finish_rates_download(error=exc))
            else:
                root.after(0, lambda path=downloaded_path: finish_rates_download(path=path))

        threading.Thread(target=worker, daemon=True).start()

