    def carry_forward_overrides_for_pdf_path(path_text: str | Path | None) -> dict[str, Decimal]:
        key = path_compare_key(path_text)
        if not key:
            return {}
        return dict(carry_forward_box_overrides_by_pdf.get(key, {}))

    def apply_2042_carry_forward_overrides_to_boxes(
        path_text: str | Path | None,
        boxes: dict[str, Decimal],
    ) -> tuple[dict[str, Decimal], tuple[str, ...]]:
        overrides = carry_forward_overrides_for_pdf_path(path_text)
        if not overrides:
            return boxes, ()
        merged = dict(boxes)
        notes: list[str] = []
        for box, amount in sorted(overrides.items(), key=lambda item: declaration_box_sort_key(item[0])):
            previous_amount = merged.get(box, Decimal("0"))
            merged[box] = amount
            if previous_amount != amount:
                notes.append(
                    f"{box}: parsed {fmt_money_inline(previous_amount)} EUR -> "
                    f"carried forward {fmt_money_inline(amount)} EUR"
                )
        return merged, tuple(notes)

    def apply_2042_carry_forward_overrides_to_context(context: AutoTmiContext) -> AutoTmiContext:
        baseline_boxes, override_notes = apply_2042_carry_forward_overrides_to_boxes(
            context.document_path,
            context.baseline_boxes,
        )
        if not override_notes:
            return context
        return replace(
            context,
            baseline_boxes=baseline_boxes,
            baseline_override_notes=override_notes,
        )

