    def verify_report_summary_lines(report: str) -> list[str]:
        summary_lines: list[str] = []
        for raw_line in report.splitlines():
            line = raw_line.strip()
            if not line:
                continue
            if line.startswith(("2042 PDF verification:", "2074 PDF verification:", "Avis/ASDIR PDF verification:")):
                continue
            if line.startswith(("Income year:", "Result:")):
                continue
            if line.startswith("- INFO:"):
                summary_lines.append("INFO: " + line.removeprefix("- INFO:").strip())
            elif line.startswith("- "):
                summary_lines.append(line.removeprefix("- ").strip())
            elif line.startswith("Info:") or line.startswith("The PDF values matched"):
                summary_lines.append(line)
        return summary_lines

    def initial_verify_summary_item(field: str, label: str, variable: tk.StringVar) -> dict[str, object]:
        raw_path = variable.get().strip()
        if raw_path:
            message = "Not verified: selected path is missing, unreadable, or is not a PDF."
        else:
            message = "Not selected: verification is incomplete."
        return {
            "field": field,
            "label": label,
            "path": raw_path or "(not selected)",
            "status": "missing",
            "result": "MISSING",
            "messages": [message],
        }

    def format_verify_summary_text(items: list[dict[str, object]]) -> str:
        lines = ["Declaration verification summary"]
        for item in items:
            lines.append("")
            lines.append(f"{item['result']}: {item['label']}")
            lines.append(f"Path: {item['path']}")
            for message in item.get("messages", []):
                lines.append(f"- {message}")
        return "\n".join(lines) + "\n"

    def show_verify_summary_popup(items: list[dict[str, object]]) -> None:
        colors = {
            "ok": "#0b6b2b",
            "info": "#1f5f99",
            "missing": "#9a5b00",
            "mismatch": "#b00020",
            "error": "#b00020",
        }
        markers = {
            "ok": "[x] OK",
            "info": "[i] INFO",
            "missing": "[ ] MISSING",
            "mismatch": "[!] MISMATCH",
            "error": "[!] ERROR",
        }

        popup = tk.Toplevel(root)
        set_window_title(popup, "Declaration Verification Summary")
        popup.transient(root)
        popup.minsize(860, 520)
        popup.columnconfigure(0, weight=1)
        popup.rowconfigure(0, weight=1)

        outer = ttk.Frame(popup, padding=12)
        outer.grid(row=0, column=0, sticky="nsew")
        outer.columnconfigure(0, weight=1)
        row_index = 0
        ttk.Label(
            outer,
            text="Declaration verification summary",
            font=pdf_bold_font,
        ).grid(row=row_index, column=0, sticky="w")
        row_index += 1
        ttk.Label(
            outer,
            text="Full details are also available in the main output.",
        ).grid(row=row_index, column=0, sticky="w", pady=(2, 10))
        row_index += 1

        for item in items:
            status = str(item.get("status", "missing"))
            color = colors.get(status, "#333333")
            frame = ttk.Frame(outer, padding=(0, 6))
            frame.grid(row=row_index, column=0, sticky="ew", pady=(0, 6))
            frame.columnconfigure(2, weight=1)
            row_index += 1

            tk.Label(
                frame,
                text=markers.get(status, "[INFO]"),
                fg=color,
                font=pdf_bold_font,
            ).grid(row=0, column=0, sticky="nw", padx=(0, 10))
            tk.Label(
                frame,
                text=str(item["label"]),
                fg=color,
                font=pdf_bold_font,
            ).grid(row=0, column=1, sticky="nw", padx=(0, 10))
            ttk.Label(
                frame,
                text=str(item.get("path", "")),
                wraplength=560,
            ).grid(row=0, column=2, sticky="w")

            messages = [str(message) for message in item.get("messages", [])]
            if not messages:
                messages = ["No detail message."]
            for message_index, message in enumerate(messages[:5], 1):
                ttk.Label(
                    frame,
                    text=f"- {message}",
                    wraplength=760,
                ).grid(row=message_index, column=1, columnspan=2, sticky="w", pady=(2, 0))
            if len(messages) > 5:
                ttk.Label(
                    frame,
                    text=f"- {len(messages) - 5} more line(s) in main output.",
                    wraplength=760,
                ).grid(row=6, column=1, columnspan=2, sticky="w", pady=(2, 0))

        button_row = ttk.Frame(popup, padding=(12, 0, 12, 12))
        button_row.grid(row=1, column=0, sticky="ew")
        button_row.columnconfigure(0, weight=1)

        def copy_summary() -> None:
            root.clipboard_clear()
            root.clipboard_append(format_verify_summary_text(items))
            root.update()

        ttk.Button(button_row, text="Copy Summary", command=copy_summary).grid(row=0, column=1, sticky="e")
        ttk.Button(button_row, text="Close", command=popup.destroy).grid(row=0, column=2, sticky="e", padx=(8, 0))

    def verify_declaration() -> None:
        start_update_check()
        income_year_for_verification = current_income_year_from_gui()
        if income_year_for_verification is None:
            messagebox.showerror("Verify", "Income year must be selected before verifying declaration PDFs.")
            return
        if income_year_for_verification >= current_income_year:
            messagebox.showinfo(
                "Verify",
                "Verify is only for completed declaration years with same-year 2042/2074/Avis PDFs. "
                "Use Advise for current/future-year planning.",
            )
            update_verify_button()
            return
        has_2042 = declaration_2042_pdf_exists()
        has_2074 = declaration_2074_pdf_exists()
        has_avis = previous_avis_pdf_exists()
        if not has_2042 and not has_2074 and not has_avis:
            messagebox.showwarning("Verify", "Select an existing 2042, avis/ASDIR, or 2074 PDF first.")
            return
        result_for_verification = (
            last_calculation_result if last_calculation_matches_selected_year() else None
        )
        calc_args_for_verify: argparse.Namespace | None = None
        if result_for_verification is None:
            if not completed_declaration_pdf_set_selected():
                messagebox.showwarning(
                    "Verify",
                    "Run Declare first, or select the 2042, 2074, and avis/ASDIR PDFs so Verify can "
                    "compute the declaration model before comparing PDFs.",
                )
                update_verify_button()
                return
            try:
                calc_args_for_verify = build_args()
            except GuiInputCancelled:
                return
            except ValueError as exc:
                messagebox.showerror("Invalid option", str(exc))
                return
            calc_income_year = calc_args_for_verify.year if calc_args_for_verify.year is not None else date.today().year - 1
            if calc_income_year != income_year_for_verification:
                messagebox.showerror(
                    "Verify",
                    f"Declaration model year {calc_income_year} does not match selected year "
                    f"{income_year_for_verification}.",
                )
                return
        verify_summary_by_field = {
            "2042": initial_verify_summary_item("2042", "2042 PDF", declaration_2042_pdf_var),
            "2074": initial_verify_summary_item("2074", "2074 PDF", declaration_pdf_var),
            "avis": initial_verify_summary_item("avis", "Avis / ASDIR PDF", previous_avis_pdf_var),
        }
        skip_projected_baseline_documents = (
            is_projected_tmi_selection(advice_tmi_rate_var.get())
            and income_year_for_verification == active_declaration_income_year(current_income_year)
        )
        paths_to_verify: list[tuple[str, str, Callable[[Path, CalculationResult], tuple[bool, str]]]] = []
        if has_2042:
            paths_to_verify.append(("2042", declaration_2042_pdf_var.get().strip(), verify_2042_declaration_pdf))
        if has_2074:
            paths_to_verify.append(("2074", declaration_pdf_var.get().strip(), verify_declaration_pdf))
        if has_avis:
            paths_to_verify.append(("avis", previous_avis_pdf_var.get().strip(), verify_avis_pdf))

        def finish_verify(
            output_text: str,
            status_updates: dict[str, tuple[str, str]],
            remember_requests: list[tuple[str, str, str, int]],
            summary_items: list[dict[str, object]],
            computed_result: CalculationResult | None = None,
            error: BaseException | None = None,
        ) -> None:
            nonlocal last_run_completed, last_calculation_result, last_verify_details_text
            if output_text:
                append_output(output_text)
            if error is None and computed_result is not None:
                last_run_completed = True
                last_calculation_result = computed_result
                last_verify_details_text = ""
                last_verify_details_document_tooltips.clear()
            set_verifying(False)
            if error is not None:
                messagebox.showerror("Verify", str(error))
                return
            apply_pdf_status_updates(status_updates, income_year_for_verification)
            for field, path_text, status, income_year in remember_requests:
                remember_pdf_path(field, path_text, status, income_year)
            if remember_requests:
                persist_gui_preferences()
            show_verify_summary_popup(summary_items)

        def worker() -> None:
            worker_status_updates: dict[str, tuple[str, str]] = {}
            remember_requests: list[tuple[str, str, str, int]] = []
            worker_summary_by_field = {field: dict(item) for field, item in verify_summary_by_field.items()}
            output_parts: list[str] = []
            worker_result = result_for_verification

            if worker_result is None:
                try:
                    buffer = io.StringIO()
                    with contextlib.redirect_stdout(buffer):
                        if calc_args_for_verify is None:
                            raise ValueError("Declaration model arguments were not prepared.")
                        worker_result = run_calculator(calc_args_for_verify)
                except ExchangeRateCsvRequired as exc:
                    output_text = buffer.getvalue() + f"\nERROR: {exc}\n"
                    root.after(
                        0,
                        lambda text=output_text, exc=exc: (
                            append_output(text),
                            set_verifying(False),
                            show_exchange_rate_csv_popup(exc),
                        ),
                    )
                    return
                except SystemExit as exc:
                    message = str(exc) or "Calculation stopped."
                    output_text = buffer.getvalue() + f"\nERROR: {message}\n"
                    root.after(
                        0,
                        lambda output_text=output_text, exc=exc: finish_verify(
                            output_text,
                            worker_status_updates,
                            remember_requests,
                            [
                                worker_summary_by_field["2042"],
                                worker_summary_by_field["2074"],
                                worker_summary_by_field["avis"],
                            ],
                            None,
                            exc,
                        ),
                    )
                    return
                except Exception as exc:
                    output_text = buffer.getvalue() + f"\nDeclaration model calculation failed before verification: {exc}\n"
                    root.after(
                        0,
                        lambda output_text=output_text, exc=exc: finish_verify(
                            output_text,
                            worker_status_updates,
                            remember_requests,
                            [
                                worker_summary_by_field["2042"],
                                worker_summary_by_field["2074"],
                                worker_summary_by_field["avis"],
                            ],
                            None,
                            exc,
                        ),
                    )
                    return
                model_output = trim_gui_artifact_output(buffer.getvalue()).strip()
                output_parts.append("\nDeclaration model computed for verification.\n")
                if model_output:
                    output_parts.append(model_output + "\n")

            def verify_pdf_field(
                field: str,
                path_text: str,
                verifier: Callable[[Path, CalculationResult], tuple[bool, str]],
            ) -> None:
                path = gui_path(path_text)
                status, parsed_year = classify_pdf_path_for_year(str(path), income_year_for_verification)
                if (
                    skip_projected_baseline_documents
                    and status == "wrong-year"
                    and parsed_year is not None
                    and int(parsed_year) < income_year_for_verification
                ):
                    report = (
                        f"\n{tax_document_label(field, int(parsed_year))}:\nResult: INFO\n"
                        f"- Prior-year PDF used as Projected tax-rate baseline for income year "
                        f"{income_year_for_verification}; not verified as a same-year declaration PDF.\n"
                    )
                    output_parts.append(report)
                    worker_summary_by_field[field] = {
                        "field": field,
                        "label": worker_summary_by_field[field]["label"],
                        "path": str(path),
                        "status": "info",
                        "result": "INFO",
                        "messages": verify_report_summary_lines(report),
                    }
                    remember_requests.append((field, str(path), "ok", int(parsed_year)))
                    return
                if status in {"missing", "unreadable"}:
                    worker_status_updates[field] = (status, str(path))
                    report = (
                        f"\n{tax_document_label(field, parsed_year)}:\nResult: MISMATCH\n"
                        f"- PDF status is {status}; the file cannot be verified for income year "
                        f"{income_year_for_verification}.\n"
                    )
                    output_parts.append(report)
                    worker_summary_by_field[field] = {
                        "field": field,
                        "label": worker_summary_by_field[field]["label"],
                        "path": str(path),
                        "status": "error",
                        "result": "ERROR",
                        "messages": verify_report_summary_lines(report),
                    }
                    return
                try:
                    if worker_result is None:
                        raise ValueError("Declaration model is unavailable for verification.")
                    ok, report = verifier(path, worker_result)
                except Exception as exc:
                    worker_status_updates[field] = ("verification-failed", str(path))
                    report = (
                        f"\n{tax_document_label(field, parsed_year)}:\nResult: ERROR\n"
                        f"- PDF parsing or verification failed: {exc}\n"
                    )
                    output_parts.append(report)
                    worker_summary_by_field[field] = {
                        "field": field,
                        "label": worker_summary_by_field[field]["label"],
                        "path": str(path),
                        "status": "error",
                        "result": "ERROR",
                        "messages": verify_report_summary_lines(report),
                    }
                    return
                output_parts.append(report)
                worker_summary_by_field[field] = {
                    "field": field,
                    "label": worker_summary_by_field[field]["label"],
                    "path": str(path),
                    "status": "ok" if ok else "mismatch",
                    "result": "OK" if ok else "MISMATCH",
                    "messages": verify_report_summary_lines(report),
                }
                if status == "wrong-year":
                    worker_status_updates[field] = ("wrong-year", str(path))
                elif ok:
                    worker_status_updates[field] = ("ok", str(path))
                else:
                    worker_status_updates[field] = ("verification-failed", str(path))

            try:
                for field, path_text, verifier in paths_to_verify:
                    if worker_result is None:
                        raise ValueError("Declaration model is unavailable for verification.")
                    verify_pdf_field(field, path_text, verifier)
            except Exception as exc:
                output_text = "".join(output_parts) + f"\nDeclaration PDF verification failed: {exc}\n"
                root.after(
                    0,
                    lambda output_text=output_text, exc=exc: finish_verify(
                        output_text,
                        worker_status_updates,
                        remember_requests,
                            [
                                worker_summary_by_field["2042"],
                                worker_summary_by_field["2074"],
                                worker_summary_by_field["avis"],
                            ],
                            None,
                            exc,
                        ),
                )
                return
            computed_result = worker_result if result_for_verification is None else None
            root.after(
                0,
                lambda: finish_verify(
                    "".join(output_parts),
                    worker_status_updates,
                    remember_requests,
                    [
                        worker_summary_by_field["2042"],
                        worker_summary_by_field["2074"],
                        worker_summary_by_field["avis"],
                    ],
                    computed_result,
                ),
            )

        append_output("\nVerifying declaration PDFs...\n")
        if result_for_verification is None:
            append_output("Computing declaration model for verification...\n")
        set_verifying(True)
        threading.Thread(target=worker, daemon=True).start()

    def view_2074_titles() -> None:
        start_update_check()
        if last_calculation_result is None:
            messagebox.showwarning("View", "Run the calculator before viewing declaration details.")
            return

        form_rows = form_2074_sheet_rows(
            last_calculation_result.detail_rows,
            last_calculation_result.income_year,
        )
        header = form_rows[0]
        title_count = max(0, len(header) - 2)
        page_2074_11_index = title_count + 1
        page_count = title_count + 2
        form_2074_11_rows = form_2074_11_sheet_rows(last_calculation_result.summary)

        popup = tk.Toplevel(root)
        set_window_title(popup, "2042 / 2074 Viewer")
        popup.transient(root)
        popup.minsize(980, 500)
        popup.columnconfigure(0, weight=1)
        popup.rowconfigure(2, weight=1)

        page_index = tk.IntVar(value=0)
        title_label = ttk.Label(popup, anchor="center")
        title_label.grid(row=0, column=0, sticky="ew", padx=12, pady=(12, 4))

        designation_label = ttk.Label(popup, anchor="center", wraplength=720)
        designation_label.grid(row=1, column=0, sticky="ew", padx=12, pady=(0, 8))

        tree_frame = ttk.Frame(popup)
        tree_frame.grid(row=2, column=0, sticky="nsew", padx=12)
        tree_frame.columnconfigure(0, weight=1)
        tree_frame.rowconfigure(0, weight=1)

        tree = ttk.Treeview(
            tree_frame,
            columns=("line", "label", "value", "source", "copy"),
            show="headings",
            selectmode="browse",
            height=13,
        )
        tree.heading("line", text="Ligne")
        tree.heading("label", text="Libellé")
        tree.heading("value", text="Valeur")
        tree.heading("source", text="")
        tree.heading("copy", text="Copy")
        tree.column("line", width=70, anchor="center", stretch=False)
        tree.column("label", width=420, anchor="w")
        tree.column("value", width=220, anchor="e")
        tree.column("source", width=0, anchor="w", stretch=False)
        tree.column("copy", width=70, anchor="center", stretch=False)
        tree.grid(row=0, column=0, sticky="nsew")
        tree_scrollbar = ttk.Scrollbar(tree_frame, orient="vertical", command=tree.yview)
        tree_scrollbar.grid(row=0, column=1, sticky="ns")
        tree.configure(yscrollcommand=tree_scrollbar.set)
        tree.tag_configure("computed", background="#eeeeee")
        tree.tag_configure("positive_result", foreground="blue")
        tree.tag_configure("negative_result", foreground="red")

        copied_status_var = tk.StringVar()

        def editable_value_for_item(item_id: str) -> str:
            if not item_id or item_id in FORM_2074_VIEWER_READONLY_LINES:
                return ""
            values = tree.item(item_id, "values")
            return str(values[2]) if len(values) >= 3 else ""

        def selected_editable_value() -> str:
            selected = tree.selection()
            if not selected:
                return ""
            return editable_value_for_item(str(selected[0]))

        def copy_item_value(item_id: str) -> bool:
            value = editable_value_for_item(item_id)
            if not value:
                return False
            root.clipboard_clear()
            root.clipboard_append(value)
            root.update()
            copied_status_var.set(f"Copied line {item_id}: {value}")
            return True

        def copy_selected_value() -> None:
            selected = tree.selection()
            if selected:
                copy_item_value(str(selected[0]))

        def update_copy_value_button() -> None:
            copy_value_button.configure(state="normal" if selected_editable_value() else "disabled")

        def selection_changed(_event: tk.Event | None = None) -> None:
            selected = tree.selection()
            if selected and selected[0] in FORM_2074_VIEWER_READONLY_LINES:
                tree.selection_remove(selected[0])
            update_copy_value_button()

        def handle_tree_click(event: tk.Event) -> str | None:
            item_id = tree.identify_row(event.y)
            if item_id in FORM_2074_VIEWER_READONLY_LINES:
                selected = tree.selection()
                if selected:
                    tree.selection_remove(*selected)
                update_copy_value_button()
                return "break"
            if item_id and tree.identify_column(event.x) == "#5":
                tree.selection_set(item_id)
                tree.focus(item_id)
                copy_item_value(item_id)
                update_copy_value_button()
                return "break"
            return None

        def copy_selected_value_from_key(_event: tk.Event) -> str:
            copy_selected_value()
            return "break"

        tree_menu = tk.Menu(popup, tearoff=False)
        tree_menu.add_command(label="Copy Value", command=copy_selected_value)

        def show_tree_menu(event: tk.Event) -> str | None:
            item_id = tree.identify_row(event.y)
            if not item_id or item_id in FORM_2074_VIEWER_READONLY_LINES:
                return "break"
            tree.selection_set(item_id)
            tree.focus(item_id)
            update_copy_value_button()
            tree_menu.tk_popup(event.x_root, event.y_root)
            return "break"

        def display_view_value(value: object) -> str:
            if isinstance(value, Decimal):
                return fmt_money_inline(value)
            if value is None:
                return ""
            return str(value)

