        def reload_advise_popup() -> None:
            nonlocal active_advise_reload_callback, pending_advise_popup_to_close, rerun_advise_after_close
            if pending_advise_popup_to_close is popup:
                return
            rerun_advise_after_close = False
            cancel_live_quote_auto_refresh()
            if active_advise_reload_callback is reload_advise_popup:
                active_advise_reload_callback = None
            pending_advise_popup_to_close = popup
            try:
                popup.withdraw()
                popup.update_idletasks()
                popup.destroy()
            except tk.TclError:
                pass
            root.after_idle(advise_open_lots)

        active_advise_reload_callback = reload_advise_popup

