        def lot_key_is_inherited_blocked(lot_key: str) -> bool:
            return lot_key in inherited_state_lot_keys

        def selected_quote_change_range() -> str:
            return normalized_advice_quote_change_range(advice_quote_change_range_var.get())

        def quote_fetch_in_progress_for_symbol(symbol: str) -> bool:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            return any(fetch_symbol == normalized_symbol for fetch_symbol, _range in quote_fetch_in_progress_symbols)

        def quote_market_status_line(symbol: str) -> str:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            market_status = quote_market_status_by_symbol.get(normalized_symbol)
            if not market_status:
                return ""
            return f"Market status: {market_status.label}."

        def live_quote_button_text(symbol: str) -> str:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            if quote_fetch_in_progress_for_symbol(normalized_symbol):
                return "..."
            if live_quote_mode_by_symbol.get(normalized_symbol, False):
                market_status = quote_market_status_by_symbol.get(normalized_symbol)
                if market_status is not None:
                    if market_status.is_open is False:
                        return "■"
                    if market_status.is_open is None:
                        return gui_unknown_status_button_text
            return "↻"

        def persist_advise_selected_lots() -> None:
            if advise_dummy_mode:
                return
            year_key = str(advice_income_year)
            current_selection = {
                lot_key: owner
                for lot_key, owner in selected_advice_lot_owners.items()
                if lot_key not in inherited_state_lot_keys
            }
            if current_selection:
                advise_selected_lots_by_year[year_key] = dict(sorted(current_selection.items()))
            else:
                advise_selected_lots_by_year.pop(year_key, None)
            persist_gui_preferences()

        def persist_advise_in_transfer_lots() -> None:
            if advise_dummy_mode:
                return
            year_key = str(advice_income_year)
            manual_lot_keys = (
                in_transfer_lot_keys
                - transfer_form_in_transfer_lot_keys
                - inherited_in_transfer_lot_keys
            )
            if manual_lot_keys:
                advise_in_transfer_lots_by_year[year_key] = set(manual_lot_keys)
            else:
                advise_in_transfer_lots_by_year.pop(year_key, None)
            persist_gui_preferences()

        def persist_advise_pending_sold_lots() -> None:
            if advise_dummy_mode:
                return
            year_key = str(advice_income_year)
            current_prices = {
                lot_key: sale_price
                for lot_key, sale_price in pending_sold_lot_prices.items()
                if lot_key not in inherited_pending_sold_lot_prices
            }
            if current_prices:
                advise_pending_sold_lots_by_year[year_key] = dict(sorted(current_prices.items()))
            else:
                advise_pending_sold_lots_by_year.pop(year_key, None)
            persist_gui_preferences()

        def persist_advise_placed_sale_orders() -> None:
            if advise_dummy_mode:
                return
            year_key = str(advice_income_year)
            placed_orders_to_persist = dict(expired_placed_sale_orders)
            placed_orders_to_persist.update(placed_sale_order_prices)
            current_orders = {
                placed_order_parent_lot_key(lot_key): order
                for lot_key, order in placed_orders_to_persist.items()
                if placed_order_parent_lot_key(lot_key) not in inherited_placed_sale_orders
            }
            if current_orders:
                advise_placed_sale_orders_by_year[year_key] = dict(sorted(current_orders.items()))
            else:
                advise_placed_sale_orders_by_year.pop(year_key, None)
            persist_gui_preferences()

        def persist_advise_last_placed_sale_order_details() -> None:
            if advise_dummy_mode:
                return
            year_key = str(advice_income_year)
            current_orders = {
                lot_key: order
                for lot_key, order in last_placed_sale_order_details.items()
                if lot_key in valid_pending_sold_lot_keys
                and lot_key not in inherited_state_lot_keys
            }
            if current_orders:
                advise_last_placed_sale_orders_by_year[year_key] = dict(sorted(current_orders.items()))
            else:
                advise_last_placed_sale_orders_by_year.pop(year_key, None)
            persist_gui_preferences()

        if stale_pending_sold_lots:
            persist_advise_pending_sold_lots()
        if stale_placed_sale_order_lots:
            persist_advise_placed_sale_orders()
        if stale_last_placed_sale_order_lots:
            persist_advise_last_placed_sale_order_details()
        if expired_orders_removed_selection:
            persist_advise_selected_lots()
        if pending_sold_lots_also_in_transfer:
            persist_advise_in_transfer_lots()
        if placed_sale_orders_also_in_transfer:
            persist_advise_in_transfer_lots()

        def expire_day_placed_sale_orders_if_needed() -> None:
            changed = False
            selection_changed = False
            for lot_key, order in list(placed_sale_order_prices.items()):
                if not placed_sale_order_is_expired(order):
                    continue
                placed_sale_order_prices.pop(lot_key, None)
                expired_placed_sale_orders[lot_key] = order
                if selected_advice_lot_owners.pop(lot_key, None) is not None:
                    selection_changed = True
                changed = True
            if changed:
                persist_advise_placed_sale_orders()
            if selection_changed:
                persist_advise_selected_lots()

        def refresh_all_advice_tab_states() -> None:
            expire_day_placed_sale_orders_if_needed()
            for refresh in advice_tab_state_refreshers:
                refresh()

