        def current_applied_live_quote_price(symbol: str) -> Decimal | None:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            if not live_quote_mode_by_symbol.get(normalized_symbol, False):
                return None
            try:
                return parse_advice_share_price_text(popup_share_price_vars[normalized_symbol].get())
            except (KeyError, ValueError):
                return None

        def live_quote_reaches_placed_sale_order(
            lot_key: str,
            symbol: str,
            price: Decimal | None = None,
        ) -> bool:
            limit_price = placed_sale_order_limit_price(lot_key)
            if limit_price is None:
                return False
            live_price = price if price is not None else current_applied_live_quote_price(symbol)
            return live_price is not None and live_price >= limit_price

