        def set_price_direction(symbol: str, direction: str) -> None:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            direction_var = price_direction_vars.get(normalized_symbol)
            direction_label = price_direction_labels.get(normalized_symbol)
            if direction_var is None or direction_label is None:
                return
            icons = {
                "up": "↑",
                "down": "↓",
                "flat": "→",
                "none": "-",
            }
            styles = {
                "up": "QuoteUp.TLabel",
                "down": "QuoteDown.TLabel",
                "flat": "QuoteFlat.TLabel",
                "none": "QuoteFlat.TLabel",
            }
            direction_var.set(icons.get(direction, "-"))
            direction_label.configure(style=styles.get(direction, "QuoteFlat.TLabel"))

        def set_price_day_change(
            symbol: str,
            day_change: Decimal | None,
            day_change_percent: Decimal | None,
        ) -> str:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            day_change_var = price_day_change_vars.get(normalized_symbol)
            day_change_label = price_day_change_labels.get(normalized_symbol)
            if day_change_var is None or day_change_label is None:
                return ""
            if day_change is None or day_change_percent is None:
                day_change_var.set("")
                day_change_label.configure(style="QuoteFlat.TLabel")
                return ""
            rounded_change = excel_round(day_change, 2)
            rounded_percent = excel_round(day_change_percent, 2)
            sign = "+" if rounded_change > 0 else ""
            percent_sign = "+" if rounded_percent > 0 else ""
            text = f"{sign}{rounded_change:,.2f} ({percent_sign}{rounded_percent:,.2f}%)"
            if rounded_change > 0:
                style_name = "QuoteUp.TLabel"
            elif rounded_change < 0:
                style_name = "QuoteDown.TLabel"
            else:
                style_name = "QuoteFlat.TLabel"
            day_change_var.set(text)
            day_change_label.configure(style=style_name)
            return text

        def format_quote_day_change_text(day_change: Decimal, day_change_percent: Decimal) -> str:
            rounded_change = excel_round(day_change, 2)
            rounded_percent = excel_round(day_change_percent, 2)
            sign = "+" if rounded_change > 0 else ""
            percent_sign = "+" if rounded_percent > 0 else ""
            return f"{sign}{rounded_change:,.2f} ({percent_sign}{rounded_percent:,.2f}%)"

        def quote_day_change_style(day_change: Decimal) -> str:
            rounded_change = excel_round(day_change, 2)
            if rounded_change > 0:
                return "QuoteUp.TLabel"
            if rounded_change < 0:
                return "QuoteDown.TLabel"
            return "QuoteFlat.TLabel"

        def row_is_recipient_donation(row: OpenLotAdviceRow) -> bool:
            return row.source_note.startswith("Donation from original owner ")

        def update_portfolio_donation_basis_change(
            portfolio_rows: Iterable[OpenLotAdviceRow],
        ) -> str:
            donation_rows = [
                row
                for row in portfolio_rows
                if row_is_recipient_donation(row) and row.cost_basis_usd > 0
            ]
            donation_basis_usd = sum((row.cost_basis_usd for row in donation_rows), Decimal("0"))
            if not donation_rows or donation_basis_usd <= 0:
                portfolio_donation_basis_change_var.set("")
                for label in portfolio_donation_basis_change_labels:
                    label.grid_remove()
                    label.configure(style="QuoteFlat.TLabel")
                return ""

            donation_value_usd = sum((row.value_usd for row in donation_rows), Decimal("0"))
            donation_change_usd = donation_value_usd - donation_basis_usd
            donation_change_percent = (donation_change_usd / donation_basis_usd) * Decimal("100")
            donation_change_text = format_quote_day_change_text(
                donation_change_usd,
                donation_change_percent,
            )
            portfolio_donation_basis_change_var.set(f"Donation basis: {donation_change_text}")
            for label in portfolio_donation_basis_change_labels:
                label.grid()
                label.configure(style=quote_day_change_style(donation_change_usd))
            donation_symbols = sorted(
                {
                    (row.symbol or ARM_QUOTE_SYMBOL).strip().upper()
                    for row in donation_rows
                }
            )
            donation_quantity = sum((row.quantity for row in donation_rows), Decimal("0"))
            return (
                "\nDonation basis line uses current value minus recipient donation cost basis "
                f"for {format_gui_quantity(donation_quantity)} donated share(s): "
                f"{', '.join(donation_symbols)}."
            )

        def update_portfolio_day_change() -> None:
            change_range = selected_quote_change_range()
            portfolio_rows = [
                row
                for row in sale_advice
                if row.share_source != CLOSED_SALE_SHARE_SOURCE
            ]
            donation_basis_detail = update_portfolio_donation_basis_change(portfolio_rows)
            total_change_usd = Decimal("0")
            total_previous_value_usd = Decimal("0")
            included_symbols: set[str] = set()
            skipped_symbols: set[str] = set()
            for row in portfolio_rows:
                symbol = (row.symbol or ARM_QUOTE_SYMBOL).strip().upper()
                quote_change = quote_day_change_by_symbol.get(symbol)
                if quote_change is None:
                    skipped_symbols.add(symbol)
                    continue
                current_price, day_change = quote_change
                previous_price = current_price - day_change
                if previous_price <= 0:
                    skipped_symbols.add(symbol)
                    continue
                included_symbols.add(symbol)
                total_change_usd += row.quantity * day_change
                total_previous_value_usd += row.quantity * previous_price
            if not included_symbols or total_previous_value_usd <= 0:
                portfolio_day_change_var.set("-")
                for label in portfolio_day_change_labels:
                    label.configure(style="QuoteFlat.TLabel")
                portfolio_day_change_status_var.set(
                    f"Portfolio {change_range} change needs at least one live quote with range data."
                    f"{donation_basis_detail}"
                )
                return
            day_change_percent = (total_change_usd / total_previous_value_usd) * Decimal("100")
            day_change_text = format_quote_day_change_text(total_change_usd, day_change_percent)
            portfolio_day_change_var.set(day_change_text)
            for label in portfolio_day_change_labels:
                label.configure(style=quote_day_change_style(total_change_usd))
            detail = (
                f"Portfolio {change_range} change excludes closed rows and uses live quote range data "
                f"for: {', '.join(sorted(included_symbols))}."
            )
            if skipped_symbols:
                detail += f"\nNo live {change_range} range data yet for: {', '.join(sorted(skipped_symbols))}."
            detail += donation_basis_detail
            portfolio_day_change_status_var.set(detail)

        def live_quote_direction(symbol: str, price: Decimal) -> tuple[str, Decimal | None]:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            previous = last_live_quote_by_symbol.get(normalized_symbol)
            if previous is None:
                return "none", None
            if price > previous:
                return "up", previous
            if price < previous:
                return "down", previous
            return "flat", previous

        def remember_advice_share_price(symbol: str, price: Decimal) -> None:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            formatted_price = format_advice_share_price(price)
            advice_share_prices_by_symbol[normalized_symbol] = formatted_price
            if normalized_symbol == ARM_QUOTE_SYMBOL:
                advice_share_price_var.set(formatted_price)

        def remember_advice_quote_mode(symbol: str, *, live_quote: bool) -> None:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            advise_quote_live_modes_by_symbol[normalized_symbol] = live_quote

        def set_popup_share_price(
            symbol: str,
            price: Decimal,
            status: str,
            *,
            live_quote: bool,
            day_change: Decimal | None = None,
            day_change_percent: Decimal | None = None,
            market_status: QuoteMarketStatus | None = None,
        ) -> None:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            live_quote_mode_by_symbol[normalized_symbol] = live_quote
            remember_advice_quote_mode(normalized_symbol, live_quote=live_quote)
            direction = "none"
            previous_live_quote: Decimal | None = None
            if live_quote:
                user_edited_price_symbols.discard(normalized_symbol)
                direction, previous_live_quote = live_quote_direction(normalized_symbol, price)
                last_live_quote_by_symbol[normalized_symbol] = price
                if market_status is not None:
                    quote_market_status_by_symbol[normalized_symbol] = market_status
            else:
                last_live_quote_by_symbol.pop(normalized_symbol, None)
                quote_market_status_by_symbol.pop(normalized_symbol, None)
            programmatic_price_update_symbols.add(normalized_symbol)
            try:
                popup_share_price_vars[normalized_symbol].set(format_advice_share_price(price))
            finally:
                programmatic_price_update_symbols.discard(normalized_symbol)
            if live_quote and previous_live_quote is not None:
                direction_word = {
                    "up": "up",
                    "down": "down",
                    "flat": "unchanged",
                }.get(direction, "updated")
                status = (
                    f"{normalized_symbol} live quote {direction_word}: "
                    f"{format_advice_share_price(previous_live_quote)} -> {format_advice_share_price(price)} USD. "
                    "Auto-refreshes every 15 s; click refresh to update now."
                )
            change_range = selected_quote_change_range()
            day_change_text = set_price_day_change(
                normalized_symbol,
                day_change if live_quote else None,
                day_change_percent if live_quote else None,
            )
            if live_quote and day_change is not None:
                quote_day_change_by_symbol[normalized_symbol] = (price, day_change)
            else:
                quote_day_change_by_symbol.pop(normalized_symbol, None)
            update_portfolio_day_change()
            if live_quote and day_change_text:
                status = f"{status}\n{change_range} change: {day_change_text}."
            market_status_line = quote_market_status_line(normalized_symbol) if live_quote else ""
            if market_status_line:
                status = f"{status}\n{market_status_line}"
            set_price_indicator(normalized_symbol, "live" if live_quote else "manual", status)
            set_price_direction(normalized_symbol, direction if live_quote else "none")
            set_live_quote_button_enabled(normalized_symbol, online_quote_supported)
            remember_advice_share_price(normalized_symbol, price)
            persist_gui_preferences()
            apply_price_to_advice_tabs(normalized_symbol, price)
            if live_quote:
                for handler in live_quote_limit_alert_handlers:
                    handler(normalized_symbol, price)
                schedule_live_quote_auto_refresh()

        def popup_share_price_changed(symbol: str, *_args: object) -> None:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            if normalized_symbol in programmatic_price_update_symbols:
                return
            live_quote_mode_by_symbol[normalized_symbol] = False
            remember_advice_quote_mode(normalized_symbol, live_quote=False)
            last_live_quote_by_symbol.pop(normalized_symbol, None)
            quote_market_status_by_symbol.pop(normalized_symbol, None)
            user_edited_price_symbols.add(normalized_symbol)
            try:
                price = parse_advice_share_price_text(popup_share_price_vars[normalized_symbol].get())
            except ValueError as exc:
                set_price_indicator(normalized_symbol, "error", str(exc))
                return
            remember_advice_share_price(normalized_symbol, price)
            persist_gui_preferences()
            set_price_indicator(
                normalized_symbol,
                "manual",
                f"{normalized_symbol} manual price is used. Click refresh to apply a live quote when available.",
            )
            quote_day_change_by_symbol.pop(normalized_symbol, None)
            set_price_day_change(normalized_symbol, None, None)
            update_portfolio_day_change()
            set_price_direction(normalized_symbol, "none")
            set_live_quote_button_enabled(normalized_symbol, online_quote_supported)
            apply_price_to_advice_tabs(normalized_symbol, price)
            if not live_quote_symbols():
                cancel_live_quote_auto_refresh()

        for symbol, variable in popup_share_price_vars.items():
            variable.trace_add("write", lambda *_args, symbol=symbol: popup_share_price_changed(symbol))

        def finish_online_quote(
            symbol: str,
            price: Decimal | None = None,
            day_change: Decimal | None = None,
            day_change_percent: Decimal | None = None,
            market_status: QuoteMarketStatus | None = None,
            error: BaseException | None = None,
            change_range: str = "1D",
            *,
            apply_even_if_manual: bool = False,
        ) -> None:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            normalized_range = normalized_advice_quote_change_range(change_range)
            quote_fetch_in_progress_symbols.discard((normalized_symbol, normalized_range))
            if not popup_exists():
                return
            set_live_quote_button_enabled(normalized_symbol, online_quote_supported)
            if normalized_range != selected_quote_change_range():
                return
            if error is not None:
                current_price = popup_share_price_vars[normalized_symbol].get().strip() or format_advice_share_price(
                    share_prices_usd.get(normalized_symbol, DEFAULT_ADVICE_SHARE_PRICE_USD)
                )
                quote_market_status_by_symbol[normalized_symbol] = QuoteMarketStatus(
                    None,
                    "market status unavailable because live quote failed",
                )
                set_price_indicator(
                    normalized_symbol,
                    "error",
                    f"{normalized_symbol} live quote unavailable; current price kept ({current_price}).\n"
                    f"{quote_market_status_line(normalized_symbol)}\n"
                    f"Fetch error: {error}"
                )
                set_live_quote_button_enabled(normalized_symbol, online_quote_supported)
                return
            if price is None:
                return
            if normalized_symbol in user_edited_price_symbols and not apply_even_if_manual:
                set_price_indicator(
                    normalized_symbol,
                    "manual",
                    f"{normalized_symbol} live quote {format_advice_share_price(price)} available; "
                    "manual price kept. Click refresh to apply it."
                )
                return
            set_popup_share_price(
                normalized_symbol,
                price,
                f"{normalized_symbol} live quote applied for {normalized_range}; "
                "auto-refreshes every 15 s. Click refresh to update now.",
                live_quote=True,
                day_change=day_change,
                day_change_percent=day_change_percent,
                market_status=market_status,
            )

        def start_online_quote_fetch(symbol: str, *, apply_even_if_manual: bool = False) -> None:
            normalized_symbol = (symbol or ARM_QUOTE_SYMBOL).strip().upper()
            change_range = selected_quote_change_range()
            if apply_even_if_manual:
                live_quote_mode_by_symbol[normalized_symbol] = True
                remember_advice_quote_mode(normalized_symbol, live_quote=True)
                user_edited_price_symbols.discard(normalized_symbol)
            if not online_quote_supported:
                set_live_quote_button_enabled(normalized_symbol, False)
                set_price_indicator(
                    normalized_symbol,
                    "error",
                    "Live quote not available in this environment; manual price used."
                )
                return
            fetch_key = (normalized_symbol, change_range)
            if fetch_key in quote_fetch_in_progress_symbols:
                return
            quote_fetch_in_progress_symbols.add(fetch_key)
            set_live_quote_button_enabled(normalized_symbol, False)
            set_price_indicator(normalized_symbol, "fetching", f"Fetching {normalized_symbol} live quote ({change_range})...")

            def worker() -> None:
                try:
                    price, _source, day_change, day_change_percent, market_status = fetch_share_price_usd(
                        normalized_symbol,
                        change_range=change_range,
                    )
                except BaseException as exc:
                    root.after(
                        0,
                        lambda exc=exc, symbol=normalized_symbol: finish_online_quote(
                            symbol,
                            error=exc,
                            change_range=change_range,
                            apply_even_if_manual=apply_even_if_manual,
                        ),
                    )
                else:
                    root.after(
                        0,
                        lambda price=price,
                        day_change=day_change,
                        day_change_percent=day_change_percent,
                        market_status=market_status,
                        symbol=normalized_symbol: finish_online_quote(
                            symbol,
                            price=price,
                            day_change=day_change,
                            day_change_percent=day_change_percent,
                            market_status=market_status,
                            change_range=change_range,
                            apply_even_if_manual=apply_even_if_manual,
                        ),
                    )

            threading.Thread(target=worker, daemon=True).start()

        def live_quote_symbols() -> list[str]:
            return [
                symbol
                for symbol in advice_symbols
                if live_quote_mode_by_symbol.get(symbol, False)
            ]

        def change_quote_change_range() -> None:
            normalized_range = selected_quote_change_range()
            if advice_quote_change_range_var.get() != normalized_range:
                advice_quote_change_range_var.set(normalized_range)
            persist_gui_preferences()
            quote_day_change_by_symbol.clear()
            for symbol in advice_symbols:
                set_price_day_change(symbol, None, None)
            update_portfolio_day_change()
            symbols_to_refresh = set(live_quote_symbols())
            symbols_to_refresh.update(fetch_symbol for fetch_symbol, _range in quote_fetch_in_progress_symbols)
            for symbol in sorted(symbols_to_refresh):
                start_online_quote_fetch(symbol, apply_even_if_manual=True)

        def schedule_live_quote_auto_refresh() -> None:
            nonlocal live_quote_refresh_after_id
            if live_quote_refresh_after_id is not None:
                return
            if not popup_exists() or not online_quote_supported or not live_quote_symbols():
                return
            live_quote_refresh_after_id = root.after(15000, live_quote_auto_refresh)

        def live_quote_auto_refresh() -> None:
            nonlocal live_quote_refresh_after_id
            live_quote_refresh_after_id = None
            if not popup_exists() or not online_quote_supported:
                return
            symbols = live_quote_symbols()
            if not symbols:
                return
            for symbol in symbols:
                start_online_quote_fetch(symbol, apply_even_if_manual=True)
            schedule_live_quote_auto_refresh()

        def cancel_live_quote_auto_refresh() -> None:
            nonlocal live_quote_refresh_after_id
            if live_quote_refresh_after_id is None:
                return
            try:
                root.after_cancel(live_quote_refresh_after_id)
            except tk.TclError:
                pass
            live_quote_refresh_after_id = None

        def close_advise_popup() -> None:
            nonlocal active_advise_reload_callback
            if active_advise_reload_callback is reload_advise_popup:
                active_advise_reload_callback = None
            cancel_live_quote_auto_refresh()
            popup.destroy()

        for symbol, button in live_quote_buttons.items():
            button.configure(command=lambda symbol=symbol: start_online_quote_fetch(symbol, apply_even_if_manual=True))
        close_advise_button.configure(command=close_advise_popup)
        popup.protocol("WM_DELETE_WINDOW", close_advise_popup)

        def show_order_tracking_confirmation(title: str, confirmation_text: str) -> None:
            if order_tracking_reminder_suppressed_var.get():
                messagebox.showinfo(title, confirmation_text, parent=popup)
                return

            dialog = tk.Toplevel(popup)
            set_window_title(dialog, title)
            dialog.transient(popup)
            dialog.resizable(False, False)
            dialog.columnconfigure(0, weight=1)

            ttk.Label(
                dialog,
                text=confirmation_text,
                justify="left",
                wraplength=560,
            ).grid(row=0, column=0, sticky="ew", padx=12, pady=(12, 8))
            ttk.Separator(dialog).grid(row=1, column=0, sticky="ew", padx=12, pady=(0, 8))
            ttk.Label(dialog, text="Order-system reminder", style="QuoteError.TLabel").grid(
                row=2,
                column=0,
                sticky="w",
                padx=12,
                pady=(0, 4),
            )
            ttk.Label(
                dialog,
                text=(
                    "This program only tracks placed and cancelled order markers for Advise estimates. "
                    "It does not place, cancel, or modify any order with your broker or order system.\n\n"
                    "You must really perform the order action yourself in the broker/order system."
                ),
                justify="left",
                wraplength=560,
            ).grid(row=3, column=0, sticky="ew", padx=12, pady=(0, 8))

            do_not_show_again_var = tk.BooleanVar(value=False)
            ttk.Checkbutton(
                dialog,
                text="Do not show this reminder again",
                variable=do_not_show_again_var,
            ).grid(row=4, column=0, sticky="w", padx=12, pady=(0, 8))

            def acknowledge() -> None:
                if do_not_show_again_var.get():
                    order_tracking_reminder_suppressed_var.set(True)
                    persist_gui_preferences()
                dialog.destroy()

            def close_without_saving() -> None:
                dialog.destroy()

            button_row = ttk.Frame(dialog)
            button_row.grid(row=5, column=0, sticky="ew", padx=12, pady=(0, 12))
            button_row.columnconfigure(0, weight=1)
            acknowledge_button = ttk.Button(button_row, text="Acknowledge", command=acknowledge)
            acknowledge_button.grid(row=0, column=1)
            dialog.bind("<Return>", lambda _event: acknowledge())
            dialog.bind("<Escape>", lambda _event: close_without_saving())
            dialog.protocol("WM_DELETE_WINDOW", close_without_saving)
            dialog.grab_set()
            acknowledge_button.focus_set()
            popup.wait_window(dialog)

        def fidelity_transfer_output_initialdir() -> str:
            current_output = gui_path(out_prefix_var.get().strip() or ".")
            parent = current_output.parent
            if str(parent) in ("", ".") or not parent.exists():
                return str(Path.cwd())
            return str(parent)

        def fidelity_transfer_default_filename(
            receiving_details: FidelityReceivingInstitutionDetails,
        ) -> str:
            profile = safe_filename_component(receiving_details.profile_name, "receiving_institution")
            today_text = date.today().isoformat()
            return f"Fidelity_Transfer_of_Assets_form_filled_{profile}_{today_text}.pdf"

        def confirm_existing_transfer_output(path: Path) -> str:
            dialog = tk.Toplevel(popup)
            set_window_title(dialog, "Output file already exists")
            dialog.transient(popup)
            dialog.resizable(False, False)
            dialog.columnconfigure(0, weight=1)
            result = {"choice": "cancel"}

            ttk.Label(
                dialog,
                text="This transfer form already exists. Choose whether to replace it or select another filename.",
                wraplength=520,
            ).grid(row=0, column=0, columnspan=3, sticky="ew", padx=12, pady=(12, 6))
            ttk.Label(dialog, text=str(path), wraplength=520).grid(
                row=1,
                column=0,
                columnspan=3,
                sticky="ew",
                padx=12,
                pady=(0, 12),
            )

            def choose(choice: str) -> None:
                result["choice"] = choice
                dialog.destroy()

            button_row = ttk.Frame(dialog)
            button_row.grid(row=2, column=0, columnspan=3, sticky="ew", padx=12, pady=(0, 12))
            button_row.columnconfigure(0, weight=1)
            ttk.Button(button_row, text="Cancel", command=lambda: choose("cancel")).grid(
                row=0,
                column=1,
                padx=(0, 8),
            )
            ttk.Button(button_row, text="Rename...", command=lambda: choose("rename")).grid(
                row=0,
                column=2,
                padx=(0, 8),
            )
            ttk.Button(button_row, text="Overwrite", command=lambda: choose("overwrite")).grid(row=0, column=3)
            dialog.bind("<Escape>", lambda _event: choose("cancel"))
            dialog.protocol("WM_DELETE_WINDOW", lambda: choose("cancel"))
            dialog.grab_set()
            popup.wait_window(dialog)
            return str(result["choice"])

        def choose_fidelity_transfer_output_path(
            receiving_details: FidelityReceivingInstitutionDetails,
        ) -> Path | None:
            def next_available_output_path(path: Path) -> Path:
                for index in range(2, 1000):
                    candidate = path.with_name(f"{path.stem}_{index}{path.suffix}")
                    if not candidate.exists():
                        return candidate
                return path.with_name(f"{path.stem}_{int(time.time())}{path.suffix}")

            initialdir = fidelity_transfer_output_initialdir()
            initialfile = fidelity_transfer_default_filename(receiving_details)
            while True:
                selected = filedialog.asksaveasfilename(
                    **file_dialog_options(
                        title="Save filled Fidelity transfer form",
                        defaultextension=".pdf",
                        initialdir=initialdir,
                        initialfile=initialfile,
                        filetypes=[("PDF files", PDF_FILE_PATTERN), ("All files", "*")],
                        parent=popup,
                        confirmoverwrite=False,
                    )
                )
                if not selected:
                    return None
                output_path = gui_path(selected)
                if not output_path.exists():
                    remember_file_chooser_path(selected)
                    return output_path
                choice = confirm_existing_transfer_output(output_path)
                if choice == "overwrite":
                    remember_file_chooser_path(selected)
                    return output_path
                if choice == "rename":
                    suggested_path = next_available_output_path(output_path)
                    initialdir = str(suggested_path.parent)
                    initialfile = suggested_path.name
                    continue
                return None

        def prompt_fidelity_transfer_participant_details() -> FidelityTransferParticipantDetails | None:
            dialog = tk.Toplevel(popup)
            set_window_title(dialog, "Confirm Fidelity participant details")
            dialog.transient(popup)
            dialog.resizable(False, False)
            dialog.columnconfigure(1, weight=1)

            ttk.Label(
                dialog,
                text=(
                    "Confirm or correct the participant details below. These values are written "
                    "into the PDF; saving stores them in the local GUI cache for next time."
                ),
                wraplength=420,
            ).grid(row=0, column=0, columnspan=2, sticky="ew", padx=12, pady=(12, 8))

            field_specs = [
                ("Participant name", fidelity_participant_name_var),
                ("Fidelity participant number", fidelity_participant_number_var),
                ("Participant phone", fidelity_participant_phone_var),
                ("Participant email", fidelity_participant_email_var),
            ]
            entry_vars: list[tk.StringVar] = []
            first_entry: ttk.Entry | None = None
            for row_index, (label, cached_var) in enumerate(field_specs, 1):
                ttk.Label(dialog, text=label).grid(row=row_index, column=0, sticky="w", padx=(12, 8), pady=4)
                entry_var = tk.StringVar(value=cached_var.get().strip())
                entry_vars.append(entry_var)
                entry = ttk.Entry(dialog, textvariable=entry_var, width=42)
                entry.grid(row=row_index, column=1, sticky="ew", padx=(0, 12), pady=4)
                if first_entry is None:
                    first_entry = entry

            signature_row = len(field_specs) + 1
            signature_path_var = tk.StringVar(value=fidelity_participant_signature_png_var.get().strip())
            signature_preview_image: dict[str, tk.PhotoImage | None] = {"image": None}
            signature_message_var = tk.StringVar()

            ttk.Label(dialog, text="Signature PNG").grid(
                row=signature_row,
                column=0,
                sticky="w",
                padx=(12, 8),
                pady=4,
            )
            signature_path_entry = ttk.Entry(dialog, textvariable=signature_path_var, width=42)
            signature_path_entry.grid(row=signature_row, column=1, sticky="ew", padx=(0, 8), pady=4)
            signature_button_row = ttk.Frame(dialog)
            signature_button_row.grid(row=signature_row, column=2, sticky="e", padx=(0, 12), pady=4)
            signature_preview_label = ttk.Label(dialog, textvariable=signature_message_var)
            signature_preview_label.grid(
                row=signature_row + 1,
                column=1,
                columnspan=2,
                sticky="w",
                padx=(0, 12),
                pady=(0, 6),
            )

            def refresh_signature_preview() -> None:
                path_text = signature_path_var.get().strip()
                signature_preview_image["image"] = None
                signature_preview_label.configure(image="")
                if not path_text:
                    signature_message_var.set("No signature PNG selected.")
                    return
                path = gui_path(path_text)
                if not path.is_file():
                    signature_message_var.set("Signature PNG not found.")
                    return
                try:
                    image = tk.PhotoImage(file=str(path))
                except tk.TclError:
                    signature_message_var.set("Signature PNG cannot be displayed.")
                    return
                shrink = max(1, (image.width() + 219) // 220, (image.height() + 69) // 70)
                if shrink > 1:
                    image = image.subsample(shrink, shrink)
                signature_preview_image["image"] = image
                signature_preview_label.configure(image=image, compound="left")
                signature_message_var.set(f" {path.name}")

            def choose_signature_png() -> None:
                selected = filedialog.askopenfilename(
                    **file_dialog_options(
                        title="Select signature PNG",
                        filetypes=[("PNG files", PNG_FILE_PATTERN), ("All files", "*")],
                        parent=dialog,
                    )
                )
                if not selected:
                    return
                selected_path = gui_path(selected)
                remember_file_chooser_path(selected)
                signature_path_var.set(display_path_text(selected_path))
                refresh_signature_preview()

            def clear_signature_png() -> None:
                signature_path_var.set("")
                refresh_signature_preview()

            ttk.Button(signature_button_row, text="Pick...", command=choose_signature_png).grid(
                row=0,
                column=0,
                padx=(0, 6),
            )
            ttk.Button(signature_button_row, text="Clear", command=clear_signature_png).grid(row=0, column=1)
            signature_path_entry.bind("<FocusOut>", lambda _event: refresh_signature_preview())
            refresh_signature_preview()

            result: dict[str, FidelityTransferParticipantDetails | None] = {"details": None}
            status_var = tk.StringVar()

            def validated_signature_png_path() -> Path | None:
                path_text = signature_path_var.get().strip()
                if not path_text:
                    return None
                path = gui_path(path_text)
                if not path.is_file():
                    messagebox.showerror("Fidelity transfer form", "Signature PNG file was not found.", parent=dialog)
                    return None
                if path.suffix.casefold() != ".png":
                    messagebox.showerror("Fidelity transfer form", "Signature image must be a PNG file.", parent=dialog)
                    return None
                try:
                    read_png_for_pdf(path)
                except Exception as exc:
                    messagebox.showerror(
                        "Fidelity transfer form",
                        f"Signature PNG cannot be used in the PDF:\n{exc}",
                        parent=dialog,
                    )
                    return None
                return path

            def validated_participant_details() -> FidelityTransferParticipantDetails | None:
                details = FidelityTransferParticipantDetails(
                    name=entry_vars[0].get(),
                    participant_number=entry_vars[1].get(),
                    phone=entry_vars[2].get(),
                    email=entry_vars[3].get(),
                )
                try:
                    validated = validate_fidelity_transfer_participant_details(details)
                except ValueError as exc:
                    messagebox.showerror("Fidelity transfer form", str(exc), parent=dialog)
                    return None
                if not validated.name:
                    messagebox.showerror(
                        "Fidelity transfer form",
                        "Participant name is required to fill page 3 Print Name.",
                        parent=dialog,
                    )
                    return None
                return validated

            def save_participant_details() -> FidelityTransferParticipantDetails | None:
                validated = validated_participant_details()
                if validated is None:
                    return None
                signature_path = validated_signature_png_path()
                if signature_path_var.get().strip() and signature_path is None:
                    return None
                fidelity_participant_name_var.set(validated.name)
                fidelity_participant_number_var.set(validated.participant_number)
                fidelity_participant_phone_var.set(validated.phone)
                fidelity_participant_email_var.set(validated.email)
                fidelity_participant_signature_png_var.set(
                    display_path_text(signature_path) if signature_path is not None else ""
                )
                persist_gui_preferences()
                status_var.set("Saved to local cache.")
                return validated

            def save_and_continue() -> None:
                validated = save_participant_details()
                if validated is None:
                    return
                result["details"] = validated
                dialog.destroy()

            def cancel() -> None:
                dialog.destroy()

            button_row = ttk.Frame(dialog)
            button_row.grid(row=signature_row + 2, column=0, columnspan=3, sticky="ew", padx=12, pady=(8, 12))
            button_row.columnconfigure(0, weight=1)
            ttk.Label(button_row, textvariable=status_var).grid(row=0, column=0, sticky="w")
            ttk.Button(button_row, text="Cancel", command=cancel).grid(row=0, column=1, padx=(0, 8))
            ttk.Button(button_row, text="Save to cache", command=save_participant_details).grid(
                row=0,
                column=2,
                padx=(0, 8),
            )
            ttk.Button(button_row, text="Save and continue", command=save_and_continue).grid(row=0, column=3)
            dialog.bind("<Return>", lambda _event: save_and_continue())
            dialog.bind("<Escape>", lambda _event: cancel())
            dialog.protocol("WM_DELETE_WINDOW", cancel)
            dialog.grab_set()
            if first_entry is not None:
                first_entry.focus_set()
            popup.wait_window(dialog)
            return result["details"]

        def prompt_fidelity_receiving_institution_details() -> FidelityReceivingInstitutionDetails | None:
            dialog = tk.Toplevel(popup)
            set_window_title(dialog, "Receiving institution details")
            dialog.transient(popup)
            dialog.minsize(620, 0)
            dialog.columnconfigure(1, weight=1)

            ttk.Label(
                dialog,
                text="Select or enter a receiving-institution profile to write into the Fidelity transfer form.",
                wraplength=560,
            ).grid(row=0, column=0, columnspan=3, sticky="ew", padx=12, pady=(12, 8))

            profile_names = sorted(fidelity_receiving_institutions)
            last_profile = last_fidelity_receiving_institution_var.get().strip()
            if last_profile not in fidelity_receiving_institutions:
                last_profile = profile_names[0] if profile_names else ""
            profile_var = tk.StringVar(value=last_profile)
            ttk.Label(dialog, text="Profile").grid(row=1, column=0, sticky="w", padx=(12, 8), pady=4)
            profile_combo = ttk.Combobox(dialog, textvariable=profile_var, values=profile_names, width=42)
            profile_combo.grid(row=1, column=1, sticky="ew", padx=(0, 8), pady=4)

            field_specs = [
                ("Receiving financial institution", "institution_name"),
                ("Institution phone", "telephone"),
                ("Receiving account number", "account_number"),
                ("Account registration type", "registration_type"),
                ("Contact name", "contact_name"),
                ("Contact email", "contact_email"),
                ("Full name at receiving institution", "account_full_name"),
                ("U.S. intermediary institution", "intermediary_name"),
                ("DTC number", "dtc_number"),
                ("U.S. intermediary phone", "intermediary_phone"),
                ("U.S. intermediary account number", "intermediary_account_number"),
            ]
            entry_vars: dict[str, tk.StringVar] = {}
            for row_index, (label, key) in enumerate(field_specs, 2):
                ttk.Label(dialog, text=label).grid(row=row_index, column=0, sticky="w", padx=(12, 8), pady=3)
                entry_var = tk.StringVar()
                entry_vars[key] = entry_var
                ttk.Entry(dialog, textvariable=entry_var, width=52).grid(
                    row=row_index,
                    column=1,
                    columnspan=2,
                    sticky="ew",
                    padx=(0, 12),
                    pady=3,
                )

            def cached_receiving_details(profile_name: str) -> FidelityReceivingInstitutionDetails:
                return fidelity_receiving_institution_from_mapping(
                    profile_name,
                    fidelity_receiving_institutions.get(profile_name, {}),
                )

            def load_profile(profile_name: str) -> None:
                details = cached_receiving_details(profile_name)
                profile_var.set(details.profile_name)
                for _label, key in field_specs:
                    entry_vars[key].set(getattr(details, key))

            def clear_profile() -> None:
                profile_var.set("")
                for entry_var in entry_vars.values():
                    entry_var.set("")

            if last_profile:
                load_profile(last_profile)

            ttk.Button(dialog, text="New", command=clear_profile).grid(row=1, column=2, sticky="ew", padx=(0, 12))
            profile_combo.bind("<<ComboboxSelected>>", lambda _event: load_profile(profile_var.get().strip()))

            result: dict[str, FidelityReceivingInstitutionDetails | None] = {"details": None}

            def accept() -> None:
                details = FidelityReceivingInstitutionDetails(
                    profile_name=profile_var.get(),
                    institution_name=entry_vars["institution_name"].get(),
                    telephone=entry_vars["telephone"].get(),
                    account_number=entry_vars["account_number"].get(),
                    registration_type=entry_vars["registration_type"].get(),
                    contact_name=entry_vars["contact_name"].get(),
                    contact_email=entry_vars["contact_email"].get(),
                    account_full_name=entry_vars["account_full_name"].get(),
                    intermediary_name=entry_vars["intermediary_name"].get(),
                    dtc_number=entry_vars["dtc_number"].get(),
                    intermediary_phone=entry_vars["intermediary_phone"].get(),
                    intermediary_account_number=entry_vars["intermediary_account_number"].get(),
                )
                try:
                    validated = validate_fidelity_receiving_institution_details(details)
                except ValueError as exc:
                    messagebox.showerror("Fidelity transfer form", str(exc), parent=dialog)
                    return
                fidelity_receiving_institutions[validated.profile_name] = asdict(validated)
                last_fidelity_receiving_institution_var.set(validated.profile_name)
                persist_gui_preferences()
                result["details"] = validated
                dialog.destroy()

            def cancel() -> None:
                dialog.destroy()

            button_row = ttk.Frame(dialog)
            button_row.grid(row=len(field_specs) + 2, column=0, columnspan=3, sticky="ew", padx=12, pady=(8, 12))
            button_row.columnconfigure(0, weight=1)
            ttk.Button(button_row, text="Cancel", command=cancel).grid(row=0, column=1, padx=(0, 8))
            ttk.Button(button_row, text="Continue", command=accept).grid(row=0, column=2)
            dialog.bind("<Return>", lambda _event: accept())
            dialog.bind("<Escape>", lambda _event: cancel())
            dialog.protocol("WM_DELETE_WINDOW", cancel)
            dialog.grab_set()
            profile_combo.focus_set()
            popup.wait_window(dialog)
            return result["details"]

        def prompt_fidelity_transfer_request_details() -> FidelityTransferRequestDetails | None:
            default_trade_date = date.today() + timedelta(days=5)
            default_settlement_date = default_trade_date + timedelta(days=2)

            dialog = tk.Toplevel(popup)
            set_window_title(dialog, "Transfer dates")
            dialog.transient(popup)
            dialog.resizable(False, False)
            dialog.columnconfigure(1, weight=1)

            ttk.Label(
                dialog,
                text=(
                    "Confirm the transfer dates. Trade Date is suggested as today + 5 days. "
                    "Settlement Date is suggested as Trade Date + 2 days; "
                    "change it if Fidelity gives a different settlement date."
                ),
                wraplength=460,
            ).grid(row=0, column=0, columnspan=3, sticky="ew", padx=12, pady=(12, 8))

            trade_date_var = tk.StringVar(value=default_trade_date.isoformat())
            settlement_date_var = tk.StringVar(value=default_settlement_date.isoformat())
            last_suggested_settlement = {"value": settlement_date_var.get()}

            ttk.Label(dialog, text="Trade Date* (required)").grid(
                row=1,
                column=0,
                sticky="w",
                padx=(12, 8),
                pady=4,
            )
            trade_date_input = add_calendar_date_input(dialog, trade_date_var, width=14)
            trade_date_input.grid(row=1, column=1, sticky="w", padx=(0, 12), pady=4)

            ttk.Label(dialog, text="Settlement Date* (required)").grid(
                row=2,
                column=0,
                sticky="w",
                padx=(12, 8),
                pady=4,
            )
            settlement_date_input = add_calendar_date_input(dialog, settlement_date_var, width=14)
            settlement_date_input.grid(row=2, column=1, sticky="w", padx=(0, 12), pady=4)
            ttk.Label(dialog, text="suggested +2 days").grid(row=2, column=2, sticky="w", padx=(0, 12), pady=4)

            result: dict[str, FidelityTransferRequestDetails | None] = {"details": None}

            def suggest_settlement_date(force: bool = False) -> None:
                current_settlement = settlement_date_var.get().strip()
                if not force and current_settlement and current_settlement != last_suggested_settlement["value"]:
                    return
                try:
                    trade_date = parse_transfer_request_date(trade_date_var.get())
                except ValueError:
                    return
                suggested = (trade_date + timedelta(days=2)).isoformat()
                settlement_date_var.set(suggested)
                last_suggested_settlement["value"] = suggested

            def validated_request_details() -> FidelityTransferRequestDetails | None:
                try:
                    details = FidelityTransferRequestDetails(
                        trade_date=parse_transfer_request_date(trade_date_var.get()),
                        settlement_date=parse_transfer_request_date(settlement_date_var.get()),
                        signature_date=date.today(),
                    )
                    return validate_fidelity_transfer_request_details(details)
                except ValueError as exc:
                    messagebox.showerror("Fidelity transfer form", str(exc), parent=dialog)
                    return None

            def accept() -> None:
                validated = validated_request_details()
                if validated is None:
                    return
                result["details"] = validated
                dialog.destroy()

            def cancel() -> None:
                dialog.destroy()

            trade_date_var.trace_add("write", lambda *_args: suggest_settlement_date())
            ttk.Button(dialog, text="Suggest +2 days", command=lambda: suggest_settlement_date(force=True)).grid(
                row=2,
                column=3,
                sticky="ew",
                padx=(0, 12),
                pady=4,
            )

            button_row = ttk.Frame(dialog)
            button_row.grid(row=3, column=0, columnspan=4, sticky="ew", padx=12, pady=(8, 12))
            button_row.columnconfigure(0, weight=1)
            ttk.Button(button_row, text="Cancel", command=cancel).grid(row=0, column=1, padx=(0, 8))
            ttk.Button(button_row, text="Continue", command=accept).grid(row=0, column=2)
            dialog.bind("<Return>", lambda _event: accept())
            dialog.bind("<Escape>", lambda _event: cancel())
            dialog.protocol("WM_DELETE_WINDOW", cancel)
            dialog.grab_set()
            trade_date_input.focus_set()
            popup.wait_window(dialog)
            return result["details"]

        def fill_fidelity_transfer_form_from_advice(
            selected_rows: list[OpenLotAdviceRow],
            *,
            all_available: bool = False,
        ) -> None:
            lot_details = [fidelity_transfer_lot_from_advice_row(row) for row in selected_rows]

            def total_share_quantity_text() -> str:
                if all_available:
                    return "all available ARM Holdings PLC ADR"
                total_quantity = sum((lot.quantity for lot in lot_details), Decimal("0"))
                return f"{format_transfer_lot_quantity(total_quantity)} ARM Holdings PLC ADR"

            def transfer_email_body() -> str:
                lines = [
                    "Dear Fidelity Stock Plan Services,",
                    "",
                    "Please find attached my signed Transfer of Assets form requesting the transfer of "
                    f"{total_share_quantity_text()} shares to my {receiving_details.institution_name} account.",
                    "",
                    f"Participant name: {participant_details.name}",
                    f"Participant number: {participant_details.participant_number}",
                    f"Receiving institution: {receiving_details.institution_name}",
                ]
                if receiving_details.account_number:
                    lines.append(f"Receiving account number: {receiving_details.account_number}")
                lines.extend(
                    [
                        "",
                        "Please process the transfer according to the instructions provided in the attached form.",
                        "Please let me know if any additional information or verification is required.",
                        "",
                        "Best regards,",
                        participant_details.name,
                    ]
                )
                if participant_details.email:
                    lines.append(participant_details.email)
                if participant_details.phone:
                    lines.append(participant_details.phone)
                return "\n".join(lines)

            def offer_transfer_email_draft(output_path: Path) -> None:
                body = transfer_email_body()
                subject = "Signed Transfer of Assets form"
                receiving_contact_email = receiving_details.contact_email.strip()
                draft_message = (
                    "Open an email draft to sps@fidelity.com?\n\n"
                    "The app will not send the email. It only opens a draft in your email program. "
                    "If Outlook is available on Windows, the generated PDF will be attached automatically. "
                    "You must review it and click Send yourself.\n\n"
                    f"Generated PDF:\n{output_path}"
                )
                if not messagebox.askyesno("Fidelity transfer email draft", draft_message, parent=popup):
                    return

                cc_email = ""
                if receiving_contact_email and messagebox.askyesno(
                    "Fidelity transfer email draft",
                    "Add the receiving institution email in CC?\n\n"
                    f"{receiving_contact_email}",
                    parent=popup,
                ):
                    cc_email = receiving_contact_email

                root.clipboard_clear()
                root.clipboard_append(body)

                if sys.platform.startswith("win"):
                    powershell_script = (
                        "$ErrorActionPreference = 'Stop'\n"
                        "$payload = Get-Content -Raw -LiteralPath $args[0] | ConvertFrom-Json\n"
                        "if (-not (Test-Path -LiteralPath $payload.attachment)) {\n"
                        "  throw \"Attachment file not found: $($payload.attachment)\"\n"
                        "}\n"
                        "$outlook = New-Object -ComObject Outlook.Application\n"
                        "$mail = $outlook.CreateItem(0)\n"
                        "$mail.To = $payload.to\n"
                        "$mail.CC = $payload.cc\n"
                        "$mail.Subject = $payload.subject\n"
                        "$mail.Body = $payload.body\n"
                        "$null = $mail.Attachments.Add($payload.attachment)\n"
                        "$mail.Display($false)\n"
                    )
                    payload = {
                        "to": "sps@fidelity.com",
                        "cc": cc_email,
                        "subject": subject,
                        "body": body,
                        "attachment": str(output_path),
                    }
                    script_path: Path | None = None
                    payload_path: Path | None = None
                    try:
                        with tempfile.NamedTemporaryFile(
                            "w",
                            suffix=".ps1",
                            delete=False,
                            encoding="utf-8",
                        ) as script_file:
                            script_file.write(powershell_script)
                            script_path = Path(script_file.name)
                        with tempfile.NamedTemporaryFile(
                            "w",
                            suffix=".json",
                            delete=False,
                            encoding="utf-8",
                        ) as payload_file:
                            json.dump(payload, payload_file)
                            payload_path = Path(payload_file.name)
                        completed = subprocess.run(
                            [
                                "powershell.exe",
                                "-NoProfile",
                                "-ExecutionPolicy",
                                "Bypass",
                                "-File",
                                str(script_path),
                                str(payload_path),
                            ],
                            check=False,
                            capture_output=True,
                            text=True,
                            timeout=30,
                        )
                    except (FileNotFoundError, subprocess.TimeoutExpired) as exc:
                        completed = None
                        outlook_error = str(exc)
                    else:
                        outlook_error = (completed.stderr or completed.stdout or "").strip()
                    finally:
                        for temp_path in (script_path, payload_path):
                            if temp_path is None:
                                continue
                            try:
                                temp_path.unlink()
                            except OSError:
                                pass
                    if completed is not None and completed.returncode == 0:
                        messagebox.showinfo(
                            "Fidelity transfer email draft",
                            "Outlook draft opened with the generated PDF attached.\n\n"
                            "The app did not send the email. Review it and click Send manually.",
                            parent=popup,
                        )
                        return
                    if outlook_error:
                        append_output(f"\nCould not open Outlook draft with attachment: {outlook_error}\n")
                        messagebox.showwarning(
                            "Fidelity transfer email draft",
                            "Outlook draft with attachment failed. The app will try the basic email fallback next, "
                            "but that fallback cannot attach the PDF automatically.\n\n"
                            f"Outlook error:\n{outlook_error}",
                            parent=popup,
                        )

                mailto_params = {
                    "subject": subject,
                    "body": body
                    + "\n\nAttachment to add manually:\n"
                    + str(output_path),
                }
                if cc_email:
                    mailto_params["cc"] = cc_email
                mailto_url = "mailto:sps@fidelity.com?" + urllib.parse.urlencode(
                    mailto_params,
                    quote_via=urllib.parse.quote,
                )
                opened = webbrowser.open(mailto_url, new=1)
                if opened:
                    messagebox.showinfo(
                        "Fidelity transfer email draft",
                        "Email draft requested. The email body was also copied to the clipboard.\n\n"
                        "This fallback cannot attach the PDF automatically. Attach the generated PDF, review, "
                        "and send manually.",
                        parent=popup,
                    )
                else:
                    messagebox.showwarning(
                        "Fidelity transfer email draft",
                        "Could not open an email program. The email body was copied to the clipboard.",
                        parent=popup,
                    )

            def offer_mark_generated_lots_in_transfer() -> None:
                markable_rows = [
                    row
                    for row in selected_rows
                    if row.share_source != CLOSED_SALE_SHARE_SOURCE
                    and row.lot_key in valid_transfer_lot_keys
                    and row.lot_key not in in_transfer_lot_keys
                    and row.lot_key not in observed_transfer_out_lot_keys
                    and row.lot_key not in confirmed_transfer_in_lot_keys
                    and not is_transfer_remainder_lot_key(row.lot_key)
                ]
                if not markable_rows:
                    return
                if not messagebox.askyesno(
                    "In transfer",
                    f"Mark the {len(markable_rows)} selected lot(s) as In transfer?",
                    parent=popup,
                ):
                    return
                for row in markable_rows:
                    in_transfer_lot_keys.add(row.lot_key)
                    selected_advice_lot_owners.pop(row.lot_key, None)
                persist_advise_in_transfer_lots()
                persist_advise_selected_lots()
                refresh_all_advice_tab_states()

            participant_details = prompt_fidelity_transfer_participant_details()
            if participant_details is None:
                return
            receiving_details = prompt_fidelity_receiving_institution_details()
            if receiving_details is None:
                return
            request_details = prompt_fidelity_transfer_request_details()
            if request_details is None:
                return
            warning_lines = [
                "Before transferring shares, save a Fidelity Current shares / open lots export.",
                "",
                "After the transfer, the shares may disappear from Fidelity. The receiving broker may show only "
                "a transfer-date market basis, not the original Fidelity RSU/ESPP tax basis.",
                "",
                "The pre-transfer Fidelity open-lots export is what preserves the original acquisition date, "
                "cost/share, grant date, share source, and qualified/non-qualified classification.",
            ]
            if not messagebox.askokcancel(
                "Keep Fidelity open-lots evidence",
                "\n".join(warning_lines) + "\n\nContinue filling the transfer form?",
                parent=popup,
            ):
                return
            try:
                pre_transfer_backup_result = run_relevant_file_backup(popup, allow_skip=True)
            except GuiInputCancelled:
                return
            signature_png_path = None
            signature_png_text = fidelity_participant_signature_png_var.get().strip()
            if signature_png_text:
                candidate_signature_path = gui_path(signature_png_text)
                if candidate_signature_path.is_file():
                    signature_png_path = candidate_signature_path
            output_path = choose_fidelity_transfer_output_path(receiving_details)
            if output_path is None:
                return
            try:
                fill_fidelity_transfer_form(
                    fidelity_transfer_form_template_path(),
                    output_path,
                    participant_details,
                    receiving_details,
                    lot_details,
                    request_details,
                    signature_png_path,
                    all_available=all_available,
                )
            except Exception as exc:
                messagebox.showerror("Fidelity transfer form", f"Could not fill form:\n{exc}", parent=popup)
                return
            try:
                post_transfer_backup_result = run_relevant_file_backup(
                    popup,
                    allow_skip=True,
                    extra_files=(("Generated Fidelity transfer form PDF", output_path),),
                )
            except GuiInputCancelled:
                post_transfer_backup_result = None
            lot_message = (
                '"All Available" was ticked.'
                if all_available
                else f"{len(lot_details)} selected tax lot(s) were included."
            )
            signature_message = " Signature was filled." if signature_png_path is not None else ""
            backup_result = post_transfer_backup_result or pre_transfer_backup_result
            backup_message = "\n\nCloud backup: not created."
            if backup_result is not None:
                backed_up_count = len(backup_result.get("backed_up", []))
                skipped_count = len(backup_result.get("skipped", []))
                backup_message = (
                    "\n\nCloud backup: "
                    f"{backed_up_count} copied, {skipped_count} unchanged/skipped."
                )
            messagebox.showinfo(
                "Fidelity transfer form",
                "Wrote filled transfer form:\n"
                f"{output_path}\n\n"
                "Participant, transfer date, settlement date, and receiving-institution information was filled. "
                "The receiving-firm acknowledgement was ticked. "
                "Page 3 Date and Print Name were filled."
                f"{signature_message} "
                f"{lot_message} "
                "Complete and sign the remaining fields manually."
                f"{backup_message}",
                parent=popup,
            )
            offer_mark_generated_lots_in_transfer()
            if signature_png_path is not None:
                offer_transfer_email_draft(output_path)

        def add_advice_tab(
            title: str,
            rows: list[OpenLotAdviceRow],
            capital_gain_tax_rate: Decimal,
            capital_gain_income_tax_rate: Decimal,
            capital_gain_tax_label: str,
            capital_gain_tax_detail: str,
            tab_auto_tmi_context: AutoTmiContext | None,
            tab_high_income_context: AdviceHighIncomeContext,
            *,
            include_transfer_form_button: bool = False,
        ) -> None:
            frame = ttk.Frame(notebook)
            frame.columnconfigure(0, weight=1)
            frame.rowconfigure(1, weight=1)
            notebook.add(frame, text=f"{title} {advice_income_year}")
