            def row_location_code(row: OpenLotAdviceRow) -> str:
                origin = compact_institution_code(row.broker, fallback="FID") if row.broker else "FID"
                manual_metadata = manual_transfer_out_metadata_by_lot_key.get(row.lot_key)
                if manual_metadata is not None:
                    if row.lot_key in confirmed_transfer_in_lot_keys:
                        confirmation = confirmed_transfer_ins_by_lot_key[row.lot_key]
                        origin = compact_institution_code(confirmation.broker, fallback=origin)
                    destination = (
                        compact_transfer_source_code(manual_metadata.receiving_institution)
                        if manual_metadata.receiving_institution
                        else "TRF"
                    )
                    return f"{origin}>{destination}"
                if row.lot_key in confirmed_transfer_in_lot_keys:
                    confirmation = confirmed_transfer_ins_by_lot_key[row.lot_key]
                    return compact_institution_code(confirmation.broker, fallback=origin)
                if (
                    row.lot_key in in_transfer_lot_keys
                    or row.lot_key in observed_transfer_out_lot_keys
                ):
                    receiving_institution = (
                        manual_metadata.receiving_institution
                        if manual_metadata is not None
                        else ""
                    ) or transfer_form_sources.get(row.lot_key, "")
                    destination = (
                        compact_transfer_source_code(receiving_institution)
                        if receiving_institution
                        else "TRF"
                    )
                    return f"{origin}>{destination}"
                if row.share_source == CLOSED_SALE_SHARE_SOURCE:
                    return origin
                if is_future_like_share_source(row.share_source):
                    return "FID"
                if row.broker:
                    return compact_institution_code(row.broker, fallback="OTH")
                if row.share_source.upper() in {"RS", "SP", "AEPFRA", "RSUFRA"}:
                    return "FID"
                if row.share_source:
                    return compact_institution_code(row.share_source, fallback="LOT")
                return "LOT"

            def composite_location_image(code: str) -> tk.PhotoImage | None:
                codes = code.split(">")
                if len(codes) != 2:
                    return None
                images = [location_images.get(part) for part in codes]
                if any(image is None for image in images):
                    return None
                image_names = tuple(str(image) for image in images if image is not None)
                cache_key = ">".join(image_names)
                cached = location_images.get(cache_key)
                if cached is not None:
                    return cached
                source, destination = images
                assert source is not None and destination is not None
                width = source.width() + 9 + destination.width()
                height = max(source.height(), destination.height())
                composite = tk.PhotoImage(width=width, height=height)
                composite.tk.call(composite, "copy", source, "-to", 0, (height - source.height()) // 2)
                midpoint = source.width() + 1
                y_mid = height // 2
                composite.put("#666666", to=(midpoint, max(0, y_mid - 1), midpoint + 1, y_mid + 2))
                composite.put("#666666", to=(midpoint + 1, y_mid - 2, midpoint + 2, y_mid + 3))
                composite.put("#666666", to=(midpoint + 2, y_mid - 3, midpoint + 3, y_mid + 4))
                composite.tk.call(
                    composite,
                    "copy",
                    destination,
                    "-to",
                    source.width() + 9,
                    (height - destination.height()) // 2,
                )
                location_images[cache_key] = composite
                return composite

            def row_location_display(row: OpenLotAdviceRow) -> tuple[str, tk.PhotoImage | str]:
                code = row_location_code(row)
                composite_image = composite_location_image(code)
                if composite_image is not None:
                    return "", composite_image
                image = location_images.get(code)
                if image is not None:
                    return "", image
                return code, ""

