            def hide_reason_tooltip(_event: tk.Event | None = None) -> None:
                nonlocal reason_tooltip_item, reason_tooltip_text, reason_tooltip_window
                if reason_tooltip_window is not None:
                    reason_tooltip_window.destroy()
                reason_tooltip_window = None
                reason_tooltip_item = ""
                reason_tooltip_text = ""

            def maybe_show_reason_tooltip(event: tk.Event) -> None:
                nonlocal reason_tooltip_item, reason_tooltip_text, reason_tooltip_window
                if tree.identify_region(event.x, event.y) != "cell":
                    hide_reason_tooltip()
                    return
                column_id = tree.identify_column(event.x)
                if column_id not in {reason_column_id, selected_column_id}:
                    hide_reason_tooltip()
                    return
                item_id = tree.identify_row(event.y)
                if not item_id:
                    hide_reason_tooltip()
                    return
                if column_id == selected_column_id:
                    marker = str(tree.set(item_id, "selected")).strip()
                    tooltip_text = {
                        "[X]": "Selected in this Advise tab.",
                        "[-]": (
                            "Unavailable here because it is selected or blocked elsewhere, such as in "
                            "the other Advise tab or prior-year planning."
                        ),
                        "[C]": "Closed/sold lot from the selected income year; shown for reference.",
                        "[S]": (
                            "Temporarily marked sold by you while waiting for refreshed broker data. "
                            "The entered sale price is used in estimates."
                        ),
                        "[P]": (
                            "Included in an active simulated limit sale order. The order price is used "
                            "in estimates until the order is cleared, expires, or is confirmed sold."
                        ),
                        "[E]": (
                            "Day limit order expired. The lot is available again and uses the current "
                            "quote or manual price."
                        ),
                        "[I]": "Marked as currently in transfer; receipt at the destination is not confirmed.",
                        "[D]": (
                            "Donation recorded in a manual broker statement row. The recipient projection "
                            "uses that row."
                        ),
                        "[O]": (
                            "[O] Transfer-out observed: Fidelity transaction history shows these "
                            "shares leaving Fidelity. Receipt at the destination is not confirmed, "
                            "so this lot remains blocked from selection."
                        ),
                        "[R]": (
                            "[R] Transfer-in confirmed: receiving-broker evidence matched these "
                            "shares to a Fidelity transfer-out. This lot is available again for "
                            "Sale or Transfer/Donation."
                        ),
                    }.get(marker, "")
                else:
                    try:
                        visible_reason = str(tree.set(item_id, "reason"))
                    except tk.TclError:
                        visible_reason = ""
                    tooltip_text = format_reason_tooltip_text(visible_reason)
                if not tooltip_text:
                    hide_reason_tooltip()
                    return

                x = tree.winfo_rootx() + event.x + 18
                y = tree.winfo_rooty() + event.y + 18
                if reason_tooltip_window is not None and reason_tooltip_item == item_id and reason_tooltip_text == tooltip_text:
                    reason_tooltip_window.wm_geometry(f"+{x}+{y}")
                    return

                hide_reason_tooltip()
                reason_tooltip_item = item_id
                reason_tooltip_text = tooltip_text
                reason_tooltip_window = tk.Toplevel(tree)
                reason_tooltip_window.wm_overrideredirect(True)
                wraplength = min(820, max(320, tree.winfo_screenwidth() - x - 40))
                label = tk.Label(
                    reason_tooltip_window,
                    text=tooltip_text,
                    justify="left",
                    wraplength=wraplength,
                    background="#fff8dc",
                    relief="solid",
                    borderwidth=1,
                    padx=8,
                    pady=6,
                )
                label.pack()
                reason_tooltip_window.update_idletasks()
                x = max(0, min(x, tree.winfo_screenwidth() - reason_tooltip_window.winfo_reqwidth() - 12))
                y = max(0, min(y, tree.winfo_screenheight() - reason_tooltip_window.winfo_reqheight() - 36))
                reason_tooltip_window.wm_geometry(f"+{x}+{y}")

