            def grid_summary_currency_widget(
                currency: str,
                widget: tk.Widget,
                **grid_options: object,
            ) -> None:
                summary_currency_widgets[currency].append((widget, dict(grid_options)))
                widget.grid(**grid_options)

            def apply_summary_currency_visibility() -> None:
                if not advice_summary_show_usd_var.get() and not advice_summary_show_eur_var.get():
                    advice_summary_show_usd_var.set(True)
                for currency, widgets in summary_currency_widgets.items():
                    visible = summary_currency_visible(currency)
                    for widget, grid_options in widgets:
                        if visible:
                            widget.grid(**grid_options)
                        else:
                            widget.grid_remove()

            def summary_currency_visibility_changed(changed_currency: str) -> None:
                if not advice_summary_show_usd_var.get() and not advice_summary_show_eur_var.get():
                    if changed_currency == "USD":
                        advice_summary_show_usd_var.set(True)
